def auto_select_time_period(tracks_df, target_tracks=30, frame_interval=0.01, start_offset=1.0):
    """
    Automatically select a time period based on the number of unique tracks.
    
    Starting from start_offset seconds into the data, this function finds the first
    time window where at least target_tracks unique tracks are present.
    
    Parameters
    ----------
    tracks_df : polars.DataFrame or pandas.DataFrame
        DataFrame containing track data with 'unique_id' and 'frame' columns
    target_tracks : int, default 30
        Target number of unique tracks to find in the time window
    frame_interval : float, default 0.01
        Time between frames in seconds
    start_offset : float, default 1.0
        Starting time offset in seconds (to skip initial frames)
        
    Returns
    -------
    tuple
        (time_start, time_end) in seconds, or (None, None) if insufficient tracks found
    """
    import polars as pl
    
    # Convert to polars if pandas
    if hasattr(tracks_df, 'to_polars'):
        df = tracks_df.to_polars()
    elif not hasattr(tracks_df, 'lazy'):
        # It's pandas, convert to polars
        df = pl.from_pandas(tracks_df)
    else:
        df = tracks_df
    
    # Get total unique tracks in the dataset
    total_unique_tracks = df['unique_id'].n_unique()
    
    # If we don't have enough tracks overall, adjust target or return fallback
    if total_unique_tracks < target_tracks:
        # Use a fallback: target 80% of available tracks or at least 5 tracks
        adjusted_target = max(5, int(total_unique_tracks * 0.8))
        print(f"Dataset has only {total_unique_tracks} total tracks, adjusting target to {adjusted_target}")
    else:
        adjusted_target = target_tracks
    
    # Get frame range
    min_frame = int(df['frame'].min())
    max_frame = int(df['frame'].max())
    
    # Convert start_offset to frame number
    start_frame = int(start_offset / frame_interval)
    start_frame = max(min_frame, start_frame)
    
    # Search for suitable time window, incrementing by 1 second (1/frame_interval frames)
    frames_per_second = int(1.0 / frame_interval)
    
    # Try progressively longer time windows
    for current_start_frame in range(start_frame, max_frame, frames_per_second):
        # Try different window sizes: 5s, 10s, 15s, 20s, 30s, 45s, 60s
        for window_duration in [5, 10, 15, 20, 30, 45, 60]:
            window_frames = int(window_duration / frame_interval)
            end_frame = current_start_frame + window_frames
            
            if end_frame > max_frame:
                continue
                
            # Count unique tracks in this window
            window_df = df.filter(
                (pl.col('frame') >= current_start_frame) & 
                (pl.col('frame') <= end_frame)
            )
            
            unique_tracks = window_df['unique_id'].n_unique()
            
            if unique_tracks >= adjusted_target:
                time_start = current_start_frame * frame_interval
                time_end = end_frame * frame_interval
                return time_start, time_end
    
    # If no suitable window found with adjusted target, try a very permissive fallback
    # Just find any window with at least 5 tracks
    if adjusted_target > 5:
        for current_start_frame in range(start_frame, max_frame, frames_per_second):
            for window_duration in [10, 20, 30, 60]:
                window_frames = int(window_duration / frame_interval)
                end_frame = current_start_frame + window_frames
                
                if end_frame > max_frame:
                    continue
                    
                window_df = df.filter(
                    (pl.col('frame') >= current_start_frame) & 
                    (pl.col('frame') <= end_frame)
                )
                
                unique_tracks = window_df['unique_id'].n_unique()
                
                if unique_tracks >= 5:
                    time_start = current_start_frame * frame_interval
                    time_end = end_frame * frame_interval
                    print(f"Fallback: found {unique_tracks} tracks (less than target {target_tracks})")
                    return time_start, time_end
    
    # If still no suitable window found, return None
    print(f"Warning: Could not find time window with sufficient tracks (target: {target_tracks}, total: {total_unique_tracks})")
    return None, None


def plot_tracks_polars_static(
    tracks_df,
    color_by="particle",
    time_start=None,
    time_end=None,
    overlay_image=False,
    master_dir=None,
    display_final_frame=True,
    max_projection=False,
    contrast_limits=None,
    invert_image=False,
    scale_bar_length=2,  # in microns
    scale_bar_color="black",
    scale_bar_thickness=2,
    transparent_background=True,
    save_path=None,
    figsize=(3, 3),  # figure size in inches
    plot_size_um=10,  # final data range (in microns)
    line_thickness=0.8,  # thickness of track lines
    dpi=200,
    export_format="svg",  # 'png' or 'svg'
    show_plot=True,  # whether to show the plot after saving/exporting
    colorway="tab20",
    frame_interval=0.01,  # seconds per frame
    pixel_size_um=0.065,  # microns per pixel conversion factor
    gradient=False,
    order=None,  # Order for categorical coloring
    motion_type=None,  # Filter by motion type if column exists
    return_svg=False,  # if True and exporting as SVG, return the SVG string
    auto_select_tracks=30,  # target number of tracks for auto time selection (disabled if time_start/end specified)
    filename=None,  # filename to display on the plot
    contours_df=None,  # optional contour dataframe with stored contour_x/contour_y columns
    show_contour=False,
    contour_group_col="filename",
    contour_x_col="contour_x",
    contour_y_col="contour_y",
    contour_coordinate_units="pixels",
    contour_color="black",
    contour_linewidth=1.0,
    contour_alpha=0.95,
    contour_linestyle="--",
):
    """
    Create a static plot of tracks using Polars DataFrame directly with full functionality.
    
    Enhanced version with image overlay, proper timing annotations, and all original features
    while maintaining streamlined Polars input without complex filtering logic.
    
    Parameters
    ----------
    tracks_df : polars.DataFrame
        Pre-filtered DataFrame containing tracks to plot
    color_by : str
        Column name to use for coloring tracks
    time_start : float, optional
        Start time in seconds for temporal filtering
    time_end : float, optional  
        End time in seconds for temporal filtering
    overlay_image : bool
        Whether to overlay tracks on microscopy image
    master_dir : str, optional
        Master directory containing image data (required if overlay_image=True)
    display_final_frame : bool
        Whether to show final frame of image (vs max projection)
    max_projection : bool
        Whether to use max projection of image stack
    contrast_limits : tuple, optional
        (lower, upper) contrast limits for image display
    invert_image : bool
        Whether to invert image colors
    scale_bar_length : float
        Length of scale bar in microns
    scale_bar_color : str
        Color of scale bar and labels
    scale_bar_thickness : float
        Thickness of scale bar line
    transparent_background : bool
        Whether to use transparent background
    save_path : str, optional
        Directory to save plot (if None, won't save)
    figsize : tuple
        Figure size in inches (width, height)
    plot_size_um : float
        Size of plot area in microns
    line_thickness : float
        Thickness of track lines
    dpi : int
        Resolution for saving
    export_format : str
        Format for saving ('png' or 'svg')
    show_plot : bool
        Whether to display the plot
    colorway : str
        Matplotlib colormap name
    frame_interval : float
        Time between frames in seconds
    pixel_size_um : float
        Microns per pixel conversion factor
    gradient : bool
        Whether to apply gradient effect (for future enhancement)
    order : list, optional
        Order for categorical coloring
    motion_type : str, optional
        Filter by specific motion type if motion_class column exists
    return_svg : bool
        If True and export_format='svg', return SVG string
    auto_select_tracks : int, default 30
        Target number of tracks for automatic time period selection.
        Only used when both time_start and time_end are None.
    filename : str, optional
        Filename to display on the plot as an annotation
    contours_df : polars.DataFrame or pandas.DataFrame, optional
        Contour dataframe containing stored contour coordinate columns.
    show_contour : bool
        Whether to overlay matching contours from ``contours_df``.
    contour_group_col : str
        Column used to match contour rows to this plotted cell/movie.
    contour_x_col, contour_y_col : str
        Columns containing stored contour x/y coordinate arrays.
    contour_coordinate_units : str
        ``"pixels"`` converts contours by ``pixel_size_um``; otherwise coordinates
        are assumed to already be in microns.
    contour_color, contour_linewidth, contour_alpha, contour_linestyle
        Matplotlib styling for contour overlays.
        
    Returns
    -------
    dict
        Dictionary with plotted track info, filtered data, and optional SVG string
    """
    import polars as pl
    import matplotlib.pyplot as plt
    import numpy as np
    import os
    import re
    from skimage.io import imread
    from skimage.util import img_as_float
    
    # Convert to pandas for matplotlib compatibility
    # (Polars -> Pandas conversion for plotting only)
    df_pandas = tracks_df.to_pandas()
    
    # Filter by motion type if specified
    if motion_type is not None and 'motion_class' in df_pandas.columns:
        df_pandas = df_pandas[df_pandas['motion_class'] == motion_type]
    
    # Text scaling based on figure size
    baseline_width = 6.0
    baseline_font = 12
    scale_factor = figsize[0] / baseline_width
    default_font = baseline_font * scale_factor
    
    plt.rcParams.update({
        "font.size": default_font,
        "axes.titlesize": default_font,
        "axes.labelsize": default_font,
        "xtick.labelsize": default_font,
        "ytick.labelsize": default_font,
    })
    
    # Ensure required columns exist
    required_cols = ['unique_id', 'frame', 'x_um', 'y_um']
    missing_cols = [col for col in required_cols if col not in df_pandas.columns]
    if missing_cols:
        raise ValueError(f"Missing required columns: {missing_cols}")
    
    # Temporal filtering with auto-selection support
    min_frame = df_pandas['frame'].min()
    max_frame = df_pandas['frame'].max()
    
    # Auto-select time period if both time_start and time_end are None
    if time_start is None and time_end is None and auto_select_tracks is not None:
        auto_time_start, auto_time_end = auto_select_time_period(
            tracks_df, 
            target_tracks=auto_select_tracks, 
            frame_interval=frame_interval
        )
        if auto_time_start is not None and auto_time_end is not None:
            time_start, time_end = auto_time_start, auto_time_end
            print(f"Auto-selected time period: {time_start:.2f}s to {time_end:.2f}s "
                  f"(targeting {auto_select_tracks} tracks)")
        else:
            print(f"Auto-selection failed, using full time range (all {tracks_df.shape[0]} data points)")
    
    if time_start is not None:
        start_frame = int(time_start / frame_interval)
        start_frame = max(min_frame, min(start_frame, max_frame))
    else:
        start_frame = min_frame
        
    if time_end is not None:
        end_frame = int(time_end / frame_interval)
        end_frame = max(min_frame, min(end_frame, max_frame))
    else:
        end_frame = max_frame
    
    if time_start is not None or time_end is not None:
        df_pandas = df_pandas[
            (df_pandas['frame'] >= start_frame) & 
            (df_pandas['frame'] <= end_frame)
        ]
    
    # Calculate time range for annotation
    time_start_sec = start_frame * frame_interval
    time_end_sec = end_frame * frame_interval
    
    if df_pandas.empty:
        raise ValueError("No data remaining after filtering")
    
    # Enhanced color mapping with order support. If an explicit dictionary is
    # provided, always use it as state -> color and do not infer/sample colors.
    if color_by in df_pandas.columns:
        if isinstance(colorway, dict):
            all_unique_values = [v for v in df_pandas[color_by].unique() if pd.notna(v)]
            if order is None:
                unique_classes = list(colorway.keys())
                unique_classes.extend([v for v in sorted(all_unique_values) if v not in unique_classes])
            else:
                unique_classes = [c for c in order if c in all_unique_values or c in colorway]
                unique_classes.extend([v for v in sorted(all_unique_values) if v not in unique_classes])
            color_map = {cls: colorway.get(cls, "gray") for cls in unique_classes}
            df_pandas['plot_color'] = df_pandas[color_by].map(color_map).fillna("gray")
        else:
        # Handle categorical vs continuous coloring
            is_categorical = (
                df_pandas[color_by].dtype == 'object' or 
                pd.api.types.is_categorical_dtype(df_pandas[color_by]) or
                color_by in ['cluster', 'cluster_id', 'motion_class'] or 
                'cluster' in color_by.lower()
            )
        
            if is_categorical:
                # Get unique values and apply order if provided
                all_unique_values = sorted([v for v in df_pandas[color_by].unique() if pd.notna(v)])
                
                if order is None:
                    unique_classes = all_unique_values
                else:
                    # Use provided order, but only include values that exist in data
                    unique_classes = [c for c in order if c in all_unique_values]
                    # Add any remaining values not in the provided order
                    remaining_values = [c for c in all_unique_values if c not in unique_classes]
                    unique_classes.extend(remaining_values)
                
                n_colors = len(unique_classes)
                if n_colors > 0:
                    colors = plt.cm.get_cmap(colorway)(np.linspace(0, 1, max(n_colors, 1)))
                    color_map = dict(zip(unique_classes, colors))
                    df_pandas['plot_color'] = df_pandas[color_by].map(color_map)
                else:
                    df_pandas['plot_color'] = 'blue'
            else:
                # Continuous coloring
                norm = plt.Normalize(vmin=df_pandas[color_by].min(), 
                                   vmax=df_pandas[color_by].max())
                df_pandas['plot_color'] = df_pandas[color_by].apply(
                    lambda x: plt.cm.get_cmap(colorway)(norm(x))
                )
                unique_classes = None  # For continuous data
    else:
        # Default color if column doesn't exist
        df_pandas['plot_color'] = 'blue'
        unique_classes = None
    
    # Create figure
    figure_background = "none" if transparent_background else "white"
    axis_background = (0, 0, 0, 0) if transparent_background else "white"
    
    fig, ax = plt.subplots(figsize=figsize, dpi=dpi)
    fig.patch.set_facecolor(figure_background)
    ax.set_facecolor(axis_background)
    
    # Overlay image if requested
    if overlay_image:
        if master_dir is None:
            raise ValueError("master_dir must be provided when overlay_image=True")
            
        # Get filename and condition from data
        if 'filename' in df_pandas.columns and 'condition' in df_pandas.columns:
            filename = df_pandas['filename'].iloc[0]
            condition = df_pandas['condition'].iloc[0]
            
            # Construct image path
            image_filename = filename.replace("_tracked", "") + ".tif"
            image_path = os.path.join(master_dir, "data", condition, image_filename)
            
            try:
                overlay_data = imread(image_path)
                
                # Process image based on settings
                if max_projection:
                    overlay_data = np.max(overlay_data, axis=0)
                elif display_final_frame:
                    overlay_data = overlay_data[-1, :, :]
                    
                overlay_data = img_as_float(overlay_data)
                
                # Apply contrast limits
                if contrast_limits:
                    lower, upper = contrast_limits
                    overlay_data = np.clip((overlay_data - lower) / (upper - lower), 0, 1)
                else:
                    overlay_data = (overlay_data - overlay_data.min()) / (
                        overlay_data.max() - overlay_data.min()
                    )
                
                # Invert if requested
                if invert_image:
                    overlay_data = 1 - overlay_data
                
                # Set image extent in microns
                height, width = overlay_data.shape
                extent = [0, width * pixel_size_um, 0, height * pixel_size_um]
                ax.imshow(overlay_data, cmap="gray", origin="lower", extent=extent, alpha=0.8)
                
            except Exception as e:
                print(f"Warning: Could not load image from {image_path}: {e}")
        else:
            print("Warning: filename and condition columns required for image overlay")
    
    # Plot tracks
    unique_tracks = df_pandas['unique_id'].unique()
    plotted_tracks = []
    
    for track_id in unique_tracks:
        track_data = df_pandas[df_pandas['unique_id'] == track_id].sort_values('frame')
        
        # Skip single-point tracks
        if len(track_data) < 2:
            continue
            
        # Get color for this track
        if 'plot_color' in track_data.columns:
            track_color = track_data['plot_color'].iloc[0]
        else:
            track_color = 'blue'
        
        # Plot track as line
        line = ax.plot(
            track_data['x_um'],
            track_data['y_um'],
            color=track_color,
            linewidth=line_thickness,
            alpha=0.8
        )[0]
        
        # Set unique identifier for SVG
        line.set_gid(f"track_{track_id}")
        plotted_tracks.append(track_id)

    # Optionally overlay stored cell contours on the same axes.
    n_contours_plotted = 0
    if show_contour and contours_df is not None:
        if isinstance(contours_df, pl.DataFrame):
            contour_pdf = contours_df.to_pandas()
        elif isinstance(contours_df, pd.DataFrame):
            contour_pdf = contours_df.copy()
        else:
            raise TypeError("contours_df must be a Polars or pandas dataframe")

        missing_contour_cols = [
            col for col in [contour_x_col, contour_y_col] if col not in contour_pdf.columns
        ]
        if missing_contour_cols:
            raise ValueError(f"contours_df is missing required columns: {missing_contour_cols}")

        contour_match_value = filename
        if contour_match_value is None and contour_group_col in df_pandas.columns:
            non_null_values = df_pandas[contour_group_col].dropna().unique()
            if len(non_null_values):
                contour_match_value = non_null_values[0]

        if contour_group_col in contour_pdf.columns and contour_match_value is not None:
            contour_pdf = contour_pdf[contour_pdf[contour_group_col] == contour_match_value].copy()

        for _, contour_row in contour_pdf.iterrows():
            x_values = contour_row[contour_x_col]
            y_values = contour_row[contour_y_col]
            if x_values is None or y_values is None:
                continue

            contour_x = np.asarray(x_values, dtype=float)
            contour_y = np.asarray(y_values, dtype=float)
            if contour_x.ndim != 1 or contour_y.ndim != 1 or len(contour_x) != len(contour_y):
                raise ValueError("Stored contour x/y values must be 1D arrays of equal length")
            if len(contour_x) == 0:
                continue

            if str(contour_coordinate_units).lower().startswith("pixel"):
                contour_x = contour_x * pixel_size_um
                contour_y = contour_y * pixel_size_um

            contour_line = ax.plot(
                contour_x,
                contour_y,
                color=contour_color,
                linewidth=contour_linewidth,
                alpha=contour_alpha,
                linestyle=contour_linestyle,
            )[0]
            if "contour_id" in contour_row:
                contour_line.set_gid(f"contour_{contour_row['contour_id']}")
            n_contours_plotted += 1
    
    # Set plot limits and aspect
    ax.set_xlim(0, plot_size_um)
    ax.set_ylim(0, plot_size_um)
    ax.set_aspect("equal", adjustable="datalim")
    
    # Remove axes if no overlay image
    if not overlay_image:
        ax.axis("off")
    
    # Add scale bar
    margin = plot_size_um * 0.05
    x_end = plot_size_um - margin
    x_start = x_end - scale_bar_length
    y_bar = margin
    
    ax.plot(
        [x_start, x_end],
        [y_bar, y_bar],
        color=scale_bar_color,
        lw=scale_bar_thickness,
        solid_capstyle="butt",
    )
    
    # Scale bar label
    ax.text(
        (x_start + x_end) / 2,
        y_bar - margin * 0.3,
        f"{scale_bar_length} µm",
        ha="center",
        va="top",
        fontsize=10 * scale_factor,
        color=scale_bar_color,
    )
    
    # Add Time Range Annotation (the "timer" at the top)
    ax.annotate(
        f"Time: {time_start_sec:.2f}s - {time_end_sec:.2f}s",
        xy=(0.5, 1.02),
        xycoords="axes fraction",
        ha="center",
        va="bottom",
        fontsize=default_font,
        color=scale_bar_color,
    )
    
    # Add filename annotation at the bottom if provided
    if filename is not None:
        ax.annotate(
            filename,
            xy=(0.5, -0.08),
            xycoords="axes fraction",
            ha="center",
            va="top",
            fontsize=default_font * 0.8,  # Slightly smaller than time annotation
            color=scale_bar_color,
        )
    
    # Add colorbar or legend if needed
    is_categorical = (
        color_by in df_pandas.columns and 
        (df_pandas[color_by].dtype == 'object' or 
         pd.api.types.is_categorical_dtype(df_pandas[color_by]) or
         color_by in ['cluster', 'cluster_id', 'motion_class'] or 
         'cluster' in color_by.lower())
    )
    
    if color_by in df_pandas.columns and unique_classes is not None:
        if is_categorical:
            # Only show colors for classes actually present in the filtered data
            present_classes = [
                cls for cls in unique_classes if cls in df_pandas[color_by].unique()
            ]
            handles = []
            for cls in present_classes[:10]:  # Limit to 10 for readability
                if 'color_map' in locals():
                    color = color_map.get(cls, 'gray')
                    handles.append(plt.Line2D([0], [0], color=color, lw=2, label=f"{cls}"))

            if handles:
                ax.legend(
                    handles=handles,
                    loc="upper left",
                    bbox_to_anchor=(1.05, 1),
                    borderaxespad=0.0,
                    title=f"Legend: {color_by}",
                    fontsize=default_font * 0.8,
                    title_fontsize=default_font * 0.8,
                )
        else:
            # Continuous colorbar
            color_min = df_pandas[color_by].min()
            color_max = df_pandas[color_by].max()
            sm = plt.cm.ScalarMappable(
                cmap=colorway, norm=plt.Normalize(vmin=color_min, vmax=color_max)
            )
            sm.set_array([])
            cbar = plt.colorbar(
                sm, ax=ax, orientation="vertical", pad=0.1, fraction=0.03, shrink=0.25
            )
            cbar.set_label(
                f"{color_by} (range: {round(color_min, 2)} - {round(color_max, 2)})",
                color=scale_bar_color,
                fontsize=default_font,
            )
            cbar.ax.yaxis.set_tick_params(color=scale_bar_color, labelsize=default_font)
            plt.setp(cbar.ax.yaxis.get_ticklabels(), color=scale_bar_color)
    
    plt.tight_layout()
    
    # Save if requested
    svg_data = None
    if save_path:
        save_dir = os.path.dirname(save_path) if os.path.dirname(save_path) else save_path
        if not os.path.exists(save_dir):
            os.makedirs(save_dir)
            
        ext = export_format.lower()
        if ext not in ["png", "svg"]:
            print("Invalid export format specified. Defaulting to 'png'.")
            ext = "png"
            
        # Create filename based on available data
        if 'filename' in df_pandas.columns:
            base_name = df_pandas['filename'].iloc[0].split(".")[0]
        else:
            base_name = f"tracks_plot_{len(plotted_tracks)}tracks"
            
        suffix = "tracks_with_contour" if show_contour else "tracks"
        out_filename = f"{base_name}_{suffix}.{ext}"
        full_save_path = os.path.join(save_dir, out_filename)
        
        plt.savefig(
            full_save_path, 
            transparent=transparent_background, 
            dpi=dpi, 
            format=ext,
            bbox_inches='tight'
        )
        
        # SVG post-processing (like in original function)
        if ext == "svg":
            try:
                with open(full_save_path, encoding="utf-8") as f:
                    svg_data = f.read()
                # Remove <clipPath> definitions, metadata, XML declaration, and DOCTYPE
                svg_data = re.sub(
                    r'<clipPath id="[^"]*">.*?</clipPath>', "", svg_data, flags=re.DOTALL
                )
                svg_data = re.sub(r'\s*clip-path="url\([^)]*\)"', "", svg_data)
                svg_data = re.sub(
                    r"<metadata>.*?</metadata>", "", svg_data, flags=re.DOTALL
                )
                svg_data = re.sub(r"<\?xml[^>]*\?>", "", svg_data, flags=re.DOTALL)
                svg_data = re.sub(r"<!DOCTYPE[^>]*>", "", svg_data, flags=re.DOTALL)
                svg_data = svg_data.strip()
                with open(full_save_path, "w", encoding="utf-8") as f:
                    f.write(svg_data)
            except Exception as e:
                print(f"Warning: SVG post-processing failed: {e}")
        
        print(f"Plot saved to: {full_save_path}")
    
    # Show plot
    if show_plot:
        plt.show()
    else:
        plt.close()
    
    # Prepare return data
    result = {
        "plotted_tracks": plotted_tracks,
        "n_tracks_plotted": len(plotted_tracks),
        "filtered_data_shape": df_pandas.shape,
        "n_contours_plotted": n_contours_plotted,
        "coordinate_range": {
            "x_min": df_pandas['x_um'].min(),
            "x_max": df_pandas['x_um'].max(),
            "y_min": df_pandas['y_um'].min(), 
            "y_max": df_pandas['y_um'].max()
        },
        "tracks_df": df_pandas  # Include filtered data like original function
    }
    
    # Add SVG data if requested and available
    if export_format.lower() == "svg" and return_svg and svg_data:
        result["svg_data"] = svg_data
    
    return result


def _as_pandas_copy(df):
    """Return a pandas copy while accepting pandas or Polars input."""
    if isinstance(df, pl.DataFrame):
        return df.to_pandas()
    if isinstance(df, pd.DataFrame):
        return df.copy()
    raise TypeError("Expected a pandas.DataFrame or polars.DataFrame")


def _restore_dataframe_type(df_pandas, template_df):
    """Return a dataframe with the same backend as the input template."""
    if isinstance(template_df, pl.DataFrame):
        return pl.from_pandas(df_pandas)
    return df_pandas


def select_single_cell_df(
    tracks_df,
    filename=None,
    file_id=None,
    *,
    filename_col="filename",
    file_id_col="file_id",
    random_state=None,
):
    """
    Select one cell/movie from a larger dataframe.

    This is intended as the first step for paper raw-movie overlays: do all broad
    filtering upstream, then pass the returned single-cell dataframe to the movie
    and still-image helpers.
    """
    df = _as_pandas_copy(tracks_df)

    if filename is not None:
        if filename_col not in df.columns:
            raise ValueError(f"Column {filename_col!r} not found")
        df = df[df[filename_col] == filename].copy()
    elif file_id is not None:
        if file_id_col not in df.columns:
            raise ValueError(f"Column {file_id_col!r} not found")
        df = df[df[file_id_col] == file_id].copy()
    else:
        if filename_col not in df.columns:
            raise ValueError(f"Column {filename_col!r} not found")
        filenames = df[filename_col].dropna().unique()
        if len(filenames) == 0:
            raise ValueError("No filenames available for single-cell selection")
        rng = np.random.default_rng(random_state)
        filename = rng.choice(filenames)
        df = df[df[filename_col] == filename].copy()

    if df.empty:
        raise ValueError("Single-cell selection returned no rows")

    n_cells = df[filename_col].nunique() if filename_col in df.columns else 0
    if n_cells != 1:
        raise ValueError(
            f"Expected exactly one {filename_col!r}; selected data contains {n_cells}"
        )

    return _restore_dataframe_type(df, tracks_df)


def find_track_rich_frame_range(
    single_cell_df,
    *,
    target_tracks=30,
    window_frames=None,
    window_seconds=15,
    step_frames=None,
    frame_interval=config.TIME_BETWEEN_FRAMES,
    start_frame=None,
    min_track_points=2,
    track_id_col="unique_id",
    frame_col="frame",
):
    """
    Find the first time window containing at least ``target_tracks`` usable tracks.

    This is a frame-based version of the older auto-selection logic used by
    ``plot_tracks_polars_static``. It deliberately returns only a frame range so
    track selection can stay outside the rendering functions.
    """
    df = _as_pandas_copy(single_cell_df)
    for col in [track_id_col, frame_col]:
        if col not in df.columns:
            raise ValueError(f"Column {col!r} not found")

    if window_frames is None:
        window_frames = int(round(window_seconds / frame_interval))
    if window_frames <= 0:
        raise ValueError("window_frames must be positive")

    min_frame = int(df[frame_col].min())
    max_frame = int(df[frame_col].max())
    if start_frame is None:
        start_frame = min_frame
    else:
        start_frame = max(min_frame, int(start_frame))

    if step_frames is None:
        step_frames = max(1, int(round(1.0 / frame_interval)))

    best = None
    for current_start in range(start_frame, max_frame + 1, step_frames):
        current_end = min(max_frame, current_start + window_frames - 1)
        window = df[(df[frame_col] >= current_start) & (df[frame_col] <= current_end)]
        counts = window.groupby(track_id_col).size()
        usable = counts[counts >= min_track_points]
        n_tracks = int(len(usable))

        if best is None or n_tracks > best["n_tracks"]:
            best = {
                "frame_start": current_start,
                "frame_end": current_end,
                "n_tracks": n_tracks,
            }

        if n_tracks >= target_tracks:
            return {
                "frame_start": current_start,
                "frame_end": current_end,
                "n_tracks": n_tracks,
                "target_tracks": target_tracks,
                "target_met": True,
            }

    if best is None:
        raise ValueError("Could not find a valid frame window")

    best["target_tracks"] = target_tracks
    best["target_met"] = False
    return best


def find_population_rich_frame_range(
    single_cell_df,
    *,
    populations=None,
    population_col="final_population",
    min_tracks_per_population=1,
    window_frames=None,
    window_seconds=15,
    step_frames=None,
    frame_interval=config.TIME_BETWEEN_FRAMES,
    start_frame=None,
    min_track_points=2,
    track_id_col="unique_id",
    frame_col="frame",
):
    """
    Find a frame window containing examples from every requested population.

    A population is considered present when at least ``min_tracks_per_population``
    unique tracks have at least ``min_track_points`` rows in that population within
    the candidate window. This makes it useful for choosing one movie segment that
    contains all behaviour types at some point in the clip.
    """
    df = _as_pandas_copy(single_cell_df)
    for col in [track_id_col, frame_col, population_col]:
        if col not in df.columns:
            raise ValueError(f"Column {col!r} not found")

    if populations is None:
        populations = sorted(pd.Series(df[population_col]).dropna().unique())
    else:
        populations = list(populations)
    if len(populations) == 0:
        raise ValueError("No populations were provided or found")

    if isinstance(min_tracks_per_population, dict):
        min_by_population = {
            pop: int(min_tracks_per_population.get(pop, 1)) for pop in populations
        }
    else:
        min_by_population = {
            pop: int(min_tracks_per_population) for pop in populations
        }

    if window_frames is None:
        window_frames = int(round(window_seconds / frame_interval))
    if window_frames <= 0:
        raise ValueError("window_frames must be positive")

    min_frame = int(df[frame_col].min())
    max_frame = int(df[frame_col].max())
    if start_frame is None:
        start_frame = min_frame
    else:
        start_frame = max(min_frame, int(start_frame))

    if step_frames is None:
        step_frames = max(1, int(round(1.0 / frame_interval)))

    def summarize_window(window_df):
        counts_by_population = {}
        for pop in populations:
            pop_window = window_df[window_df[population_col] == pop]
            if pop_window.empty:
                counts_by_population[pop] = 0
                continue
            track_counts = pop_window.groupby(track_id_col).size()
            usable = track_counts[track_counts >= min_track_points]
            counts_by_population[pop] = int(len(usable))
        missing = [
            pop
            for pop in populations
            if counts_by_population[pop] < min_by_population[pop]
        ]
        return counts_by_population, missing

    best = None
    for current_start in range(start_frame, max_frame + 1, step_frames):
        current_end = min(max_frame, current_start + window_frames - 1)
        window = df[(df[frame_col] >= current_start) & (df[frame_col] <= current_end)]
        counts_by_population, missing = summarize_window(window)
        populations_present = len(populations) - len(missing)
        total_population_tracks = int(sum(counts_by_population.values()))

        candidate = {
            "frame_start": current_start,
            "frame_end": current_end,
            "counts_by_population": counts_by_population,
            "missing_populations": missing,
            "populations_present": populations_present,
            "total_population_tracks": total_population_tracks,
        }

        if best is None:
            best = candidate
        else:
            best_score = (
                best["populations_present"],
                best["total_population_tracks"],
            )
            candidate_score = (populations_present, total_population_tracks)
            if candidate_score > best_score:
                best = candidate

        if len(missing) == 0:
            candidate["target_met"] = True
            candidate["populations"] = populations
            candidate["min_tracks_per_population"] = min_by_population
            return candidate

    if best is None:
        raise ValueError("Could not find a valid frame window")

    best["target_met"] = False
    best["populations"] = populations
    best["min_tracks_per_population"] = min_by_population
    return best


def filter_tracks_for_raw_overlay(
    single_cell_df,
    *,
    frame_range=None,
    track_id_col="unique_id",
    frame_col="frame",
    min_track_points=2,
    min_track_length_frames=None,
    target_tracks=30,
    selection_method="longest",
    include_track_ids=None,
    population_col=None,
    populations=None,
    tracks_per_population=None,
    random_state=42,
):
    """
    Select the track subset to overlay, without doing any rendering.

    The returned dataframe keeps all rows for the selected track IDs, so the same
    selection can be used consistently for quick QC, napari movies, and stills.
    """
    df = _as_pandas_copy(single_cell_df)
    for col in [track_id_col, frame_col]:
        if col not in df.columns:
            raise ValueError(f"Column {col!r} not found")

    if population_col is not None and populations is not None:
        if population_col not in df.columns:
            raise ValueError(f"Column {population_col!r} not found")
        populations = list(populations)
        df = df[df[population_col].isin(populations)].copy()

    if include_track_ids is not None:
        selected_ids = list(include_track_ids)
    else:
        if frame_range is None:
            window_df = df
        else:
            frame_start, frame_end = frame_range
            window_df = df[
                (df[frame_col] >= int(frame_start)) & (df[frame_col] <= int(frame_end))
            ].copy()

        if window_df.empty:
            raise ValueError("No tracks are present in the requested frame range")

        summary = (
            window_df.groupby(track_id_col)[frame_col]
            .agg(["count", "min", "max"])
            .reset_index()
        )
        summary["track_length_frames"] = summary["max"] - summary["min"] + 1
        summary = summary[summary["count"] >= min_track_points]

        if min_track_length_frames is not None:
            summary = summary[
                summary["track_length_frames"] >= int(min_track_length_frames)
            ]

        if summary.empty:
            raise ValueError("No tracks passed the selection filters")

        if selection_method == "balanced_by_population":
            if population_col is None:
                raise ValueError(
                    "population_col is required for selection_method='balanced_by_population'"
                )
            if population_col not in window_df.columns:
                raise ValueError(f"Column {population_col!r} not found")
            if populations is None:
                populations = sorted(
                    pd.Series(window_df[population_col]).dropna().unique()
                )
            else:
                populations = list(populations)
            if len(populations) == 0:
                raise ValueError("No populations available for balanced selection")

            if tracks_per_population is None:
                if target_tracks is None:
                    tracks_per_population = 1
                else:
                    tracks_per_population = max(1, int(target_tracks) // len(populations))
            tracks_per_population = int(tracks_per_population)

            selected_ids = []
            selected_by_population = {}
            for pop in populations:
                pop_window = window_df[window_df[population_col] == pop]
                pop_summary = (
                    pop_window.groupby(track_id_col)[frame_col]
                    .agg(["count", "min", "max"])
                    .reset_index()
                )
                if pop_summary.empty:
                    selected_by_population[pop] = []
                    continue
                pop_summary["track_length_frames"] = (
                    pop_summary["max"] - pop_summary["min"] + 1
                )
                pop_summary = pop_summary[pop_summary["count"] >= min_track_points]
                if min_track_length_frames is not None:
                    pop_summary = pop_summary[
                        pop_summary["track_length_frames"]
                        >= int(min_track_length_frames)
                    ]
                pop_summary = pop_summary.sort_values(
                    ["track_length_frames", "count"], ascending=False
                )
                pop_ids = pop_summary[track_id_col].head(tracks_per_population).tolist()
                selected_by_population[pop] = pop_ids
                for track_id in pop_ids:
                    if track_id not in selected_ids:
                        selected_ids.append(track_id)

            if len(selected_ids) == 0:
                raise ValueError("Balanced population selection returned no tracks")

        elif selection_method == "longest":
            summary = summary.sort_values(
                ["track_length_frames", "count"], ascending=False
            )
        elif selection_method == "most_points":
            summary = summary.sort_values(["count", "track_length_frames"], ascending=False)
        elif selection_method == "random":
            summary = summary.sample(
                frac=1, random_state=random_state
            ).reset_index(drop=True)
        else:
            raise ValueError(
                "selection_method must be 'longest', 'most_points', 'random', "
                "or 'balanced_by_population'"
            )

        if selection_method != "balanced_by_population":
            if target_tracks is not None:
                summary = summary.head(int(target_tracks))
            selected_ids = summary[track_id_col].tolist()

    selected = df[df[track_id_col].isin(selected_ids)].copy()
    if selected.empty:
        raise ValueError("Track selection returned no rows")

    return {
        "tracks_df": _restore_dataframe_type(selected, single_cell_df),
        "selected_track_ids": selected_ids,
        "n_tracks": len(selected_ids),
        "frame_range": frame_range,
    }


def choose_single_cell_for_display(
    source_df,
    *,
    mode="most_tracks",
    gallery_lookup_df=None,
    gallery_number=1,
    manual_filename=None,
    population_col="final_population",
    target_population=None,
    random_seed=42,
    group_col="filename",
    track_id_col="unique_id",
):
    """
    Select one cell/movie for display workflows.

    Modes are ``gallery_number``, ``manual``, ``random``, ``most_tracks``, and
    ``most_tracks_in_population``.
    """
    candidate_source = source_df
    if mode == "most_tracks_in_population":
        if population_col not in candidate_source.columns:
            raise ValueError(f"Column {population_col!r} not found")
        if target_population is None:
            raise ValueError("Set target_population for most_tracks_in_population")
        if isinstance(candidate_source, pl.DataFrame):
            candidate_source = candidate_source.filter(
                pl.col(population_col) == target_population
            )
        else:
            candidate_source = candidate_source[
                candidate_source[population_col] == target_population
            ]

    selected_key = None
    if mode == "gallery_number":
        if gallery_lookup_df is None:
            raise ValueError("Run the gallery first or use a non-gallery selection mode")
        lookup_pdf = _as_pandas_copy(gallery_lookup_df)
        selected_key = lookup_pdf.loc[
            lookup_pdf["gallery_number"] == gallery_number,
            group_col,
        ].iloc[0]
    elif mode == "manual":
        if manual_filename is None:
            raise ValueError("Set manual_filename when mode='manual'")
        selected_key = manual_filename
    else:
        if isinstance(candidate_source, pl.DataFrame):
            cell_track_counts = (
                candidate_source.group_by(group_col)
                .agg(
                    [
                        pl.col(track_id_col).n_unique().alias("n_tracks"),
                        pl.len().alias("n_datapoints"),
                    ]
                )
                .sort(["n_tracks", "n_datapoints"], descending=True)
            )
            if mode == "random":
                filenames = cell_track_counts.select(group_col).to_series().to_list()
                import random

                random.seed(random_seed)
                selected_key = random.choice(filenames)
            elif mode in {"most_tracks", "most_tracks_in_population"}:
                selected_key = cell_track_counts.select(group_col).to_series()[0]
            else:
                raise ValueError("Unknown display cell selection mode")
        else:
            df = _as_pandas_copy(candidate_source)
            cell_track_counts = (
                df.groupby(group_col)
                .agg(
                    n_tracks=(track_id_col, "nunique"),
                    n_datapoints=(group_col, "size"),
                )
                .reset_index()
                .sort_values(["n_tracks", "n_datapoints"], ascending=False)
            )
            if mode == "random":
                selected_key = cell_track_counts[group_col].sample(
                    n=1, random_state=random_seed
                ).iloc[0]
            elif mode in {"most_tracks", "most_tracks_in_population"}:
                selected_key = cell_track_counts[group_col].iloc[0]
            else:
                raise ValueError("Unknown display cell selection mode")

    if isinstance(source_df, pl.DataFrame):
        if group_col not in source_df.columns:
            raise ValueError(f"Column {group_col!r} not found")
        selected_cell_df = source_df.filter(pl.col(group_col) == selected_key)
    else:
        df = _as_pandas_copy(source_df)
        if group_col not in df.columns:
            raise ValueError(f"Column {group_col!r} not found")
        selected_cell_df = df[df[group_col] == selected_key].copy()
    selected_pdf = _as_pandas_copy(selected_cell_df)
    selected_key = selected_pdf[group_col].dropna().unique()[0]
    return selected_key, selected_cell_df


def choose_frame_range_for_display(
    single_cell_df,
    *,
    mode="all",
    manual_frame_range=None,
    target_tracks=30,
    window_seconds=15,
    frame_interval=config.TIME_BETWEEN_FRAMES,
    start_frame=None,
    min_track_points=10,
    population_col="final_population",
    populations=None,
    min_tracks_per_population=1,
    track_id_col="unique_id",
    frame_col="frame",
):
    """Choose a frame range for display workflows."""
    if mode == "all":
        df = _as_pandas_copy(single_cell_df)
        frame_range = (int(df[frame_col].min()), int(df[frame_col].max()))
        return frame_range, {"mode": "all", "target_met": None}
    if mode == "manual":
        if manual_frame_range is None:
            raise ValueError("Set manual_frame_range when mode='manual'")
        return manual_frame_range, {"mode": "manual", "target_met": None}
    if mode == "track_rich":
        info = find_track_rich_frame_range(
            single_cell_df,
            target_tracks=target_tracks,
            window_seconds=window_seconds,
            frame_interval=frame_interval,
            start_frame=start_frame,
            min_track_points=min_track_points,
            track_id_col=track_id_col,
            frame_col=frame_col,
        )
        return (info["frame_start"], info["frame_end"]), info
    if mode == "population_rich":
        info = find_population_rich_frame_range(
            single_cell_df,
            populations=populations,
            population_col=population_col,
            min_tracks_per_population=min_tracks_per_population,
            window_seconds=window_seconds,
            frame_interval=frame_interval,
            start_frame=start_frame,
            min_track_points=min_track_points,
            track_id_col=track_id_col,
            frame_col=frame_col,
        )
        return (info["frame_start"], info["frame_end"]), info
    raise ValueError("Unknown display frame range mode")


def select_tracks_for_gallery_cells(
    source_df,
    *,
    frame_range=None,
    selection_method="longest",
    target_tracks_per_cell=20,
    min_track_points=20,
    min_track_length_frames=None,
    population_col=None,
    populations=None,
    tracks_per_population=None,
    random_state=42,
    group_col="filename",
    track_id_col="unique_id",
):
    """Select track subsets independently for every cell in a gallery source df."""
    selected_cells = []
    selection_rows = []
    filenames = _as_pandas_copy(source_df)[group_col].dropna().unique().tolist()
    for filename in filenames:
        if isinstance(source_df, pl.DataFrame):
            cell_df = source_df.filter(pl.col(group_col) == filename)
        else:
            cell_df = source_df[source_df[group_col] == filename].copy()
        try:
            selection = filter_tracks_for_raw_overlay(
                cell_df,
                frame_range=frame_range,
                selection_method=selection_method,
                target_tracks=target_tracks_per_cell,
                min_track_points=min_track_points,
                min_track_length_frames=min_track_length_frames,
                population_col=population_col,
                populations=populations,
                tracks_per_population=tracks_per_population,
                random_state=random_state,
                track_id_col=track_id_col,
            )
        except ValueError:
            continue
        tracks_df = selection["tracks_df"]
        if len(_as_pandas_copy(tracks_df)) == 0:
            continue
        selected_cells.append(tracks_df)
        selection_rows.append(
            {
                group_col: filename,
                "n_selected_tracks": selection["n_tracks"],
                "selected_track_ids": selection["selected_track_ids"],
            }
        )
    if not selected_cells:
        raise ValueError("No gallery tracks were selected. Loosen the gallery filters.")
    if isinstance(source_df, pl.DataFrame):
        return pl.concat(selected_cells, how="vertical"), pl.DataFrame(selection_rows)
    return pd.concat(selected_cells, ignore_index=True), pd.DataFrame(selection_rows)


def quick_plot_single_cell_tracks(
    single_cell_df,
    tracks_to_plot_df=None,
    *,
    frame_range=None,
    color_by="unique_id",
    track_id_col="unique_id",
    frame_col="frame",
    x_col=None,
    y_col=None,
    use_microns=True,
    colorway="tab20",
    line_width=0.8,
    alpha=0.85,
    figsize=(3, 3),
    dpi=150,
    show_plot=True,
    save_path=None,
):
    """
    Quick notebook QC plot of selected tracks without raw-image overlay.
    """
    df = _as_pandas_copy(tracks_to_plot_df if tracks_to_plot_df is not None else single_cell_df)
    if x_col is None:
        x_col = "x_um" if use_microns and "x_um" in df.columns else "x"
    if y_col is None:
        y_col = "y_um" if use_microns and "y_um" in df.columns else "y"

    for col in [track_id_col, frame_col, x_col, y_col]:
        if col not in df.columns:
            raise ValueError(f"Column {col!r} not found")

    if frame_range is not None:
        frame_start, frame_end = frame_range
        df = df[(df[frame_col] >= int(frame_start)) & (df[frame_col] <= int(frame_end))]

    if df.empty:
        raise ValueError("No data available to plot")

    track_ids = list(pd.unique(df[track_id_col]))
    color_map = _track_color_map(df, track_id_col, color_by, colorway)

    fig, ax = plt.subplots(figsize=figsize, dpi=dpi)
    for track_id, track in df.sort_values(frame_col).groupby(track_id_col):
        if len(track) < 2:
            continue
        color = color_map.get(track_id, "blue")
        ax.plot(track[x_col], track[y_col], color=color, lw=line_width, alpha=alpha)

    ax.set_aspect("equal", adjustable="box")
    ax.axis("off")
    if frame_range is not None:
        ax.set_title(f"Frames {int(frame_range[0])}-{int(frame_range[1])}")

    if save_path is not None:
        os.makedirs(os.path.dirname(save_path) or ".", exist_ok=True)
        fig.savefig(save_path, dpi=dpi, bbox_inches="tight", transparent=True)

    if show_plot:
        plt.show()
    else:
        plt.close(fig)

    return {"fig": fig, "ax": ax, "n_tracks": len(track_ids), "tracks_df": df}


def _single_value_from_df(df, column, default=None):
    if column not in df.columns or df.empty:
        return default
    values = pd.Series(df[column]).dropna().unique()
    if len(values) == 0:
        return default
    return values[0]


def with_cell_key(
    df,
    *,
    folder_col="foldername",
    filename_col="filename",
    key_col="cell_key",
    separator="||",
):
    """Return a dataframe with a stable unique key made from folder + filename."""
    if isinstance(df, pl.DataFrame):
        for col in [folder_col, filename_col]:
            if col not in df.columns:
                raise ValueError(f"Column {col!r} not found")
        return df.with_columns(
            (
                pl.col(folder_col).cast(pl.Utf8)
                + separator
                + pl.col(filename_col).cast(pl.Utf8)
            ).alias(key_col)
        )

    out = _as_pandas_copy(df)
    for col in [folder_col, filename_col]:
        if col not in out.columns:
            raise ValueError(f"Column {col!r} not found")
    out[key_col] = out[folder_col].astype(str) + separator + out[filename_col].astype(str)
    return out


def _resolve_raw_movie_path(single_cell_df, master_dir=None, filename=None, condition=None):
    df = _as_pandas_copy(single_cell_df)
    filename = filename or _single_value_from_df(df, "filename")
    condition = condition or _single_value_from_df(df, "condition")
    if filename is None:
        raise ValueError("Could not infer filename from single_cell_df")
    image_filename = str(filename).replace("_tracked", "") + ".tif"

    if master_dir is None:
        master_dir = _single_value_from_df(df, "foldername")
    if master_dir is None:
        raise ValueError("master_dir was not provided and foldername was not found")

    candidates = []
    if condition is not None:
        candidates.append(os.path.join(master_dir, "data", str(condition), image_filename))
        candidates.append(os.path.join(master_dir, str(condition), image_filename))
    candidates.append(os.path.join(master_dir, "data", image_filename))
    candidates.append(os.path.join(master_dir, image_filename))

    for candidate in candidates:
        if os.path.exists(candidate):
            return candidate

    return candidates[0]


def compute_fixed_cell_contour(
    single_cell_df,
    *,
    coordinate_units="pixels",
    x_col=None,
    y_col=None,
    contour_method="radial",
    edge_angle_bins=180,
    edge_padding=0.05,
    edge_smoothing=0.1,
    minimal_bridge_point_radius=2.0,
    minimal_bridge_width=1.5,
    minimal_bridge_mask_padding=12,
):
    """
    Compute one fixed averaged cell contour from all coordinates in one cell.
    """
    df = _as_pandas_copy(single_cell_df)
    if x_col is None:
        x_col = "x" if coordinate_units == "pixels" else "x_um"
    if y_col is None:
        y_col = "y" if coordinate_units == "pixels" else "y_um"
    for col in [x_col, y_col]:
        if col not in df.columns:
            raise ValueError(f"Column {col!r} not found")

    points = df[[x_col, y_col]].dropna().to_numpy()
    if len(points) < 3:
        raise ValueError("At least three points are required to compute a contour")

    centroid = points.mean(axis=0)
    if contour_method == "radial":
        return compute_cell_edge_angle_binning(
            points,
            centroid,
            edge_angle_bins=edge_angle_bins,
            edge_padding=edge_padding,
            edge_smoothing=edge_smoothing,
        )
    if contour_method == "legacy_outer_envelope":
        return compute_cell_edge_angle_binning_legacy_outer_envelope(
            points,
            centroid,
            edge_angle_bins=edge_angle_bins,
            edge_padding=edge_padding,
            edge_smoothing=edge_smoothing,
        )
    if contour_method == "minimal_bridge":
        return compute_cell_edge_minimal_bridge(
            points,
            point_radius=minimal_bridge_point_radius,
            bridge_width=minimal_bridge_width,
            mask_padding=minimal_bridge_mask_padding,
            edge_padding=edge_padding,
            edge_smoothing=edge_smoothing,
        )
    raise ValueError(
        "contour_method must be 'radial', 'legacy_outer_envelope', or 'minimal_bridge'"
    )


def _polygon_area_perimeter(points):
    """Return polygon area and perimeter for an ordered Nx2 contour."""
    if points is None or len(points) < 3:
        return np.nan, np.nan
    x = points[:, 0]
    y = points[:, 1]
    area = 0.5 * abs(np.dot(x, np.roll(y, -1)) - np.dot(y, np.roll(x, -1)))
    diffs = np.diff(np.vstack([points, points[0]]), axis=0)
    perimeter = float(np.sum(np.sqrt(np.sum(diffs**2, axis=1))))
    return float(area), perimeter


def _contour_from_stored_row(contour_source):
    """Extract an Nx2 contour from a one-row dataframe with contour_x/contour_y."""
    df = _as_pandas_copy(contour_source)
    if "contour_x" not in df.columns or "contour_y" not in df.columns or df.empty:
        return None

    x_values = df["contour_x"].iloc[0]
    y_values = df["contour_y"].iloc[0]
    if x_values is None or y_values is None:
        return None

    x = np.asarray(x_values, dtype=float)
    y = np.asarray(y_values, dtype=float)
    if x.ndim != 1 or y.ndim != 1 or len(x) != len(y):
        raise ValueError("Stored contour_x and contour_y must be 1D arrays of equal length")
    return np.column_stack([x, y])


def get_contour_array(contour_source, *, coordinate_units="pixels", contour_method="radial"):
    """
    Return an Nx2 contour from either a stored contour dataframe or a track dataframe.
    """
    stored = _contour_from_stored_row(contour_source)
    if stored is not None:
        return stored
    return compute_fixed_cell_contour(
        contour_source,
        coordinate_units=coordinate_units,
        contour_method=contour_method,
    )


def compute_cell_contours_dataframe(
    tracks_df,
    *,
    group_col="filename",
    coordinate_units="pixels",
    x_col=None,
    y_col=None,
    metadata_cols=None,
    selection_method=None,
    n_cells=None,
    track_id_col="unique_id",
    random_state=42,
    contour_method="radial",
    edge_angle_bins=180,
    edge_padding=0.05,
    edge_smoothing=0.1,
    minimal_bridge_point_radius=2.0,
    minimal_bridge_width=1.5,
    minimal_bridge_mask_padding=12,
    on_error="raise",
    show_progress=False,
    return_backend="polars",
):
    """
    Compute fixed contours for cells and store them one row per cell.

    The contour itself is stored as list columns, ``contour_x`` and ``contour_y``.
    This keeps the table compact and easy to save as Parquet while preserving
    numeric arrays for later geometry measurements.
    """
    if x_col is None:
        x_col = "x" if coordinate_units == "pixels" else "x_um"
    if y_col is None:
        y_col = "y" if coordinate_units == "pixels" else "y_um"

    if isinstance(tracks_df, pl.DataFrame):
        if group_col not in tracks_df.columns:
            raise ValueError(f"Column {group_col!r} not found")
        for col in [x_col, y_col]:
            if col not in tracks_df.columns:
                raise ValueError(f"Column {col!r} not found")

        agg_exprs = [pl.len().alias("n_datapoints")]
        if track_id_col in tracks_df.columns:
            agg_exprs.append(pl.col(track_id_col).n_unique().alias("n_tracks"))
        else:
            agg_exprs.append(pl.len().alias("n_tracks"))
        summary_pl = tracks_df.group_by(group_col).agg(agg_exprs)

        if selection_method == "most_tracks":
            summary_pl = summary_pl.sort(["n_tracks", "n_datapoints"], descending=True)
        elif selection_method == "most_points":
            summary_pl = summary_pl.sort(["n_datapoints", "n_tracks"], descending=True)
        elif selection_method == "random":
            summary_pl = summary_pl.sample(fraction=1.0, shuffle=True, seed=random_state)
        elif selection_method is not None:
            raise ValueError(
                "selection_method must be None, 'most_tracks', 'most_points', or 'random'"
            )
        if n_cells is not None:
            summary_pl = summary_pl.head(int(n_cells))

        metadata_cols = list(metadata_cols or [])
        metadata_cols = [
            col for col in metadata_cols if col in tracks_df.columns and col != group_col
        ]
        selected_cells = summary_pl[group_col].to_list()
        selected_cell_set = set(selected_cells)
        selected_tracks_df = tracks_df.filter(pl.col(group_col).is_in(selected_cells))

        grouped_cells = selected_tracks_df.group_by(group_col, maintain_order=True)
        if show_progress:
            try:
                from tqdm.auto import tqdm

                grouped_cells = tqdm(
                    grouped_cells,
                    total=len(selected_cells),
                    desc="Computing cell contours",
                    unit="cell",
                )
            except Exception:
                pass

        rows = []
        for group_key, sub_pl in grouped_cells:
            cell_id = group_key[0] if isinstance(group_key, tuple) else group_key
            if cell_id not in selected_cell_set:
                continue
            sub = sub_pl.to_pandas()
            points = sub[[x_col, y_col]].dropna().to_numpy()
            if len(points) < 3:
                continue
            try:
                contour = compute_fixed_cell_contour(
                    sub,
                    coordinate_units=coordinate_units,
                    x_col=x_col,
                    y_col=y_col,
                    contour_method=contour_method,
                    edge_angle_bins=edge_angle_bins,
                    edge_padding=edge_padding,
                    edge_smoothing=edge_smoothing,
                    minimal_bridge_point_radius=minimal_bridge_point_radius,
                    minimal_bridge_width=minimal_bridge_width,
                    minimal_bridge_mask_padding=minimal_bridge_mask_padding,
                )
            except Exception as exc:
                if on_error == "raise":
                    raise ValueError(
                        f"Failed to compute contour for {group_col}={cell_id!r}"
                    ) from exc
                if on_error != "record":
                    raise ValueError("on_error must be 'raise' or 'record'") from exc
                centroid = points.mean(axis=0)
                row = {
                    group_col: cell_id,
                    "contour_id": 1,
                    "coordinate_units": coordinate_units,
                    "x_col": x_col,
                    "y_col": y_col,
                    "contour_x": [],
                    "contour_y": [],
                    "centroid_x": float(centroid[0]),
                    "centroid_y": float(centroid[1]),
                    "area": np.nan,
                    "perimeter": np.nan,
                    "circumference": np.nan,
                    "bbox_min_x": np.nan,
                    "bbox_max_x": np.nan,
                    "bbox_min_y": np.nan,
                    "bbox_max_y": np.nan,
                    "n_contour_points": 0,
                    "n_source_points": int(len(points)),
                    "n_tracks": int(sub[track_id_col].nunique())
                    if track_id_col in sub.columns
                    else np.nan,
                    "edge_angle_bins": int(edge_angle_bins),
                    "edge_padding": float(edge_padding),
                    "edge_smoothing": float(edge_smoothing),
                    "minimal_bridge_point_radius": float(minimal_bridge_point_radius),
                    "minimal_bridge_width": float(minimal_bridge_width),
                    "minimal_bridge_mask_padding": int(minimal_bridge_mask_padding),
                    "contour_method": contour_method,
                    "contour_status": "failed",
                    "contour_error": str(exc),
                }
                for col in metadata_cols:
                    row[col] = _single_value_from_df(sub, col)
                rows.append(row)
                continue
            area, perimeter = _polygon_area_perimeter(contour)
            centroid = points.mean(axis=0)
            row = {
                group_col: cell_id,
                "contour_id": 1,
                "coordinate_units": coordinate_units,
                "x_col": x_col,
                "y_col": y_col,
                "contour_x": contour[:, 0].astype(float).tolist(),
                "contour_y": contour[:, 1].astype(float).tolist(),
                "centroid_x": float(centroid[0]),
                "centroid_y": float(centroid[1]),
                "area": area,
                "perimeter": perimeter,
                "circumference": perimeter,
                "bbox_min_x": float(np.min(contour[:, 0])),
                "bbox_max_x": float(np.max(contour[:, 0])),
                "bbox_min_y": float(np.min(contour[:, 1])),
                "bbox_max_y": float(np.max(contour[:, 1])),
                "n_contour_points": int(len(contour)),
                "n_source_points": int(len(points)),
                "n_tracks": int(sub[track_id_col].nunique())
                if track_id_col in sub.columns
                else np.nan,
                "edge_angle_bins": int(edge_angle_bins),
                "edge_padding": float(edge_padding),
                "edge_smoothing": float(edge_smoothing),
                "minimal_bridge_point_radius": float(minimal_bridge_point_radius),
                "minimal_bridge_width": float(minimal_bridge_width),
                "minimal_bridge_mask_padding": int(minimal_bridge_mask_padding),
                "contour_method": contour_method,
                "contour_status": "ok",
                "contour_error": None,
            }
            for col in metadata_cols:
                row[col] = _single_value_from_df(sub, col)
            rows.append(row)

        result = pd.DataFrame(rows)
        if return_backend == "pandas":
            return result
        if return_backend == "polars":
            return pl.from_pandas(result)
        raise ValueError("return_backend must be 'polars' or 'pandas'")

    df = _as_pandas_copy(tracks_df)
    if group_col not in df.columns:
        raise ValueError(f"Column {group_col!r} not found")

    for col in [x_col, y_col]:
        if col not in df.columns:
            raise ValueError(f"Column {col!r} not found")

    metadata_cols = list(metadata_cols or [])
    metadata_cols = [col for col in metadata_cols if col in df.columns and col != group_col]

    cell_summary = (
        df.groupby(group_col)
        .agg(
            n_datapoints=(x_col, "size"),
            n_tracks=(track_id_col, "nunique") if track_id_col in df.columns else (x_col, "size"),
        )
        .reset_index()
    )

    if selection_method == "most_tracks":
        cell_summary = cell_summary.sort_values(
            ["n_tracks", "n_datapoints"], ascending=False
        )
    elif selection_method == "most_points":
        cell_summary = cell_summary.sort_values(
            ["n_datapoints", "n_tracks"], ascending=False
        )
    elif selection_method == "random":
        cell_summary = cell_summary.sample(
            frac=1, random_state=random_state
        ).reset_index(drop=True)
    elif selection_method is not None:
        raise ValueError(
            "selection_method must be None, 'most_tracks', 'most_points', or 'random'"
        )

    if n_cells is not None:
        cell_summary = cell_summary.head(int(n_cells))

    cell_ids = cell_summary[group_col].tolist()
    if show_progress:
        try:
            from tqdm.auto import tqdm

            cell_ids = tqdm(
                cell_ids,
                total=len(cell_ids),
                desc="Computing cell contours",
                unit="cell",
            )
        except Exception:
            pass

    rows = []
    for cell_id in cell_ids:
        sub = df[df[group_col] == cell_id].copy()
        points = sub[[x_col, y_col]].dropna().to_numpy()
        if len(points) < 3:
            continue

        try:
            contour = compute_fixed_cell_contour(
                sub,
                coordinate_units=coordinate_units,
                x_col=x_col,
                y_col=y_col,
                contour_method=contour_method,
                edge_angle_bins=edge_angle_bins,
                edge_padding=edge_padding,
                edge_smoothing=edge_smoothing,
                minimal_bridge_point_radius=minimal_bridge_point_radius,
                minimal_bridge_width=minimal_bridge_width,
                minimal_bridge_mask_padding=minimal_bridge_mask_padding,
            )
        except Exception as exc:
            if on_error == "raise":
                raise ValueError(
                    f"Failed to compute contour for {group_col}={cell_id!r}"
                ) from exc
            if on_error != "record":
                raise ValueError("on_error must be 'raise' or 'record'") from exc
            centroid = points.mean(axis=0)
            row = {
                group_col: cell_id,
                "contour_id": 1,
                "coordinate_units": coordinate_units,
                "x_col": x_col,
                "y_col": y_col,
                "contour_x": [],
                "contour_y": [],
                "centroid_x": float(centroid[0]),
                "centroid_y": float(centroid[1]),
                "area": np.nan,
                "perimeter": np.nan,
                "circumference": np.nan,
                "bbox_min_x": np.nan,
                "bbox_max_x": np.nan,
                "bbox_min_y": np.nan,
                "bbox_max_y": np.nan,
                "n_contour_points": 0,
                "n_source_points": int(len(points)),
                "n_tracks": int(sub[track_id_col].nunique())
                if track_id_col in sub.columns
                else np.nan,
                "edge_angle_bins": int(edge_angle_bins),
                "edge_padding": float(edge_padding),
                "edge_smoothing": float(edge_smoothing),
                "minimal_bridge_point_radius": float(minimal_bridge_point_radius),
                "minimal_bridge_width": float(minimal_bridge_width),
                "minimal_bridge_mask_padding": int(minimal_bridge_mask_padding),
                "contour_method": contour_method,
                "contour_status": "failed",
                "contour_error": str(exc),
            }
            for col in metadata_cols:
                row[col] = _single_value_from_df(sub, col)
            rows.append(row)
            continue
        area, perimeter = _polygon_area_perimeter(contour)
        centroid = points.mean(axis=0)
        row = {
            group_col: cell_id,
            "contour_id": 1,
            "coordinate_units": coordinate_units,
            "x_col": x_col,
            "y_col": y_col,
            "contour_x": contour[:, 0].astype(float).tolist(),
            "contour_y": contour[:, 1].astype(float).tolist(),
            "centroid_x": float(centroid[0]),
            "centroid_y": float(centroid[1]),
            "area": area,
            "perimeter": perimeter,
            "circumference": perimeter,
            "bbox_min_x": float(np.min(contour[:, 0])),
            "bbox_max_x": float(np.max(contour[:, 0])),
            "bbox_min_y": float(np.min(contour[:, 1])),
            "bbox_max_y": float(np.max(contour[:, 1])),
            "n_contour_points": int(len(contour)),
            "n_source_points": int(len(points)),
            "n_tracks": int(sub[track_id_col].nunique()) if track_id_col in sub.columns else np.nan,
            "edge_angle_bins": int(edge_angle_bins),
            "edge_padding": float(edge_padding),
            "edge_smoothing": float(edge_smoothing),
            "minimal_bridge_point_radius": float(minimal_bridge_point_radius),
            "minimal_bridge_width": float(minimal_bridge_width),
            "minimal_bridge_mask_padding": int(minimal_bridge_mask_padding),
            "contour_method": contour_method,
            "contour_status": "ok",
            "contour_error": None,
        }
        for col in metadata_cols:
            row[col] = _single_value_from_df(sub, col)
        rows.append(row)

    result = pd.DataFrame(rows)
    if return_backend == "pandas":
        return result
    if return_backend == "polars":
        return pl.from_pandas(result)
    raise ValueError("return_backend must be 'polars' or 'pandas'")


def compute_segmented_cell_contours(
    single_cell_df,
    *,
    max_contours=2,
    group_col="filename",
    track_id_col="unique_id",
    coordinate_units="pixels",
    x_col=None,
    y_col=None,
    clustering_method="dbscan",
    eps_pixels=20,
    min_samples=3,
    min_component_points=100,
    min_component_tracks=5,
    min_component_fraction=0.15,
    fallback_to_single=True,
    contour_method="radial",
    edge_angle_bins=180,
    edge_padding=0.05,
    edge_smoothing=0.1,
):
    """
    Experimental multi-contour version of ``compute_fixed_cell_contour``.

    Tracks are clustered by their spatial centroids, then one fixed contour is
    computed from all detections belonging to each retained track cluster. This
    keeps a direct ``unique_id -> contour_id`` mapping for downstream dataframes.
    """
    df = _as_pandas_copy(single_cell_df)
    if x_col is None:
        x_col = "x" if coordinate_units == "pixels" else "x_um"
    if y_col is None:
        y_col = "y" if coordinate_units == "pixels" else "y_um"
    for col in [x_col, y_col, track_id_col]:
        if col not in df.columns:
            raise ValueError(f"Column {col!r} not found")

    df = df.dropna(subset=[x_col, y_col, track_id_col]).copy()
    if len(df) < 3:
        raise ValueError("At least three points are required to compute a contour")

    def _single_contour_result(reason):
        contour = compute_fixed_cell_contour(
            df,
            coordinate_units=coordinate_units,
            x_col=x_col,
            y_col=y_col,
            contour_method=contour_method,
            edge_angle_bins=edge_angle_bins,
            edge_padding=edge_padding,
            edge_smoothing=edge_smoothing,
        )
        area, perimeter = _polygon_area_perimeter(contour)
        points = df[[x_col, y_col]].to_numpy()
        centroid = points.mean(axis=0)
        return [
            {
                "contour_id": 1,
                "component_label": -1,
                "split_status": reason,
                "coordinate_units": coordinate_units,
                "x_col": x_col,
                "y_col": y_col,
                "contour_x": contour[:, 0].astype(float).tolist(),
                "contour_y": contour[:, 1].astype(float).tolist(),
                "centroid_x": float(centroid[0]),
                "centroid_y": float(centroid[1]),
                "area": area,
                "perimeter": perimeter,
                "bbox_min_x": float(np.min(contour[:, 0])),
                "bbox_max_x": float(np.max(contour[:, 0])),
                "bbox_min_y": float(np.min(contour[:, 1])),
                "bbox_max_y": float(np.max(contour[:, 1])),
                "n_contour_points": int(len(contour)),
                "n_source_points": int(len(points)),
                "n_tracks": int(df[track_id_col].nunique()),
                "track_ids": list(pd.unique(df[track_id_col])),
                "clustering_method": clustering_method,
                "eps_pixels": float(eps_pixels),
                "min_samples": int(min_samples),
                "min_component_points": int(min_component_points),
                "min_component_tracks": int(min_component_tracks),
                "min_component_fraction": float(min_component_fraction),
                "max_contours": int(max_contours),
                "edge_angle_bins": int(edge_angle_bins),
                "edge_padding": float(edge_padding),
                "edge_smoothing": float(edge_smoothing),
                "contour_method": contour_method,
            }
        ]

    track_summary = (
        df.groupby(track_id_col)
        .agg(
            centroid_x=(x_col, "median"),
            centroid_y=(y_col, "median"),
            n_points=(x_col, "size"),
        )
        .reset_index()
    )
    if len(track_summary) < max(2, int(min_component_tracks)):
        if fallback_to_single:
            return _single_contour_result("fallback_too_few_tracks")
        return []

    if clustering_method != "dbscan":
        raise ValueError("Currently only clustering_method='dbscan' is supported")
    try:
        from sklearn.cluster import DBSCAN
    except ImportError as exc:
        raise ImportError("scikit-learn is required for segmented contours") from exc

    labels = DBSCAN(eps=float(eps_pixels), min_samples=int(min_samples)).fit_predict(
        track_summary[["centroid_x", "centroid_y"]].to_numpy()
    )
    track_summary["_component_label"] = labels

    labeled = df.merge(
        track_summary[[track_id_col, "_component_label"]],
        on=track_id_col,
        how="left",
    )
    component_rows = []
    total_points = len(labeled)
    for label, component in labeled[labeled["_component_label"] >= 0].groupby(
        "_component_label"
    ):
        n_points = len(component)
        n_tracks = component[track_id_col].nunique()
        fraction = n_points / total_points if total_points else 0
        if n_points < min_component_points:
            continue
        if n_tracks < min_component_tracks:
            continue
        if fraction < min_component_fraction:
            continue
        component_rows.append(
            {
                "label": label,
                "df": component.copy(),
                "n_points": n_points,
                "n_tracks": n_tracks,
                "fraction": fraction,
            }
        )

    component_rows = sorted(
        component_rows,
        key=lambda row: (row["n_tracks"], row["n_points"]),
        reverse=True,
    )[: int(max_contours)]

    if len(component_rows) < 2:
        if fallback_to_single:
            return _single_contour_result("fallback_no_valid_split")
        return []

    rows = []
    for contour_id, component_row in enumerate(component_rows, start=1):
        component = component_row["df"]
        if len(component[[x_col, y_col]].dropna()) < 3:
            continue
        contour = compute_fixed_cell_contour(
            component,
            coordinate_units=coordinate_units,
            x_col=x_col,
            y_col=y_col,
            contour_method=contour_method,
            edge_angle_bins=edge_angle_bins,
            edge_padding=edge_padding,
            edge_smoothing=edge_smoothing,
        )
        area, perimeter = _polygon_area_perimeter(contour)
        points = component[[x_col, y_col]].to_numpy()
        centroid = points.mean(axis=0)
        rows.append(
            {
                "contour_id": contour_id,
                "component_label": int(component_row["label"]),
                "split_status": "segmented",
                "coordinate_units": coordinate_units,
                "x_col": x_col,
                "y_col": y_col,
                "contour_x": contour[:, 0].astype(float).tolist(),
                "contour_y": contour[:, 1].astype(float).tolist(),
                "centroid_x": float(centroid[0]),
                "centroid_y": float(centroid[1]),
                "area": area,
                "perimeter": perimeter,
                "bbox_min_x": float(np.min(contour[:, 0])),
                "bbox_max_x": float(np.max(contour[:, 0])),
                "bbox_min_y": float(np.min(contour[:, 1])),
                "bbox_max_y": float(np.max(contour[:, 1])),
                "n_contour_points": int(len(contour)),
                "n_source_points": int(len(points)),
                "n_tracks": int(component[track_id_col].nunique()),
                "track_ids": list(pd.unique(component[track_id_col])),
                "component_fraction": float(component_row["fraction"]),
                "clustering_method": clustering_method,
                "eps_pixels": float(eps_pixels),
                "min_samples": int(min_samples),
                "min_component_points": int(min_component_points),
                "min_component_tracks": int(min_component_tracks),
                "min_component_fraction": float(min_component_fraction),
                "max_contours": int(max_contours),
                "edge_angle_bins": int(edge_angle_bins),
                "edge_padding": float(edge_padding),
                "edge_smoothing": float(edge_smoothing),
                "contour_method": contour_method,
            }
        )

    if not rows and fallback_to_single:
        return _single_contour_result("fallback_invalid_components")
    return rows


def _largest_blob_point_mask(points, *, point_radius=2.0, mask_padding=12):
    """
    Return a boolean mask for points belonging to the largest rasterized blob.
    """
    from skimage.measure import label

    points = np.asarray(points, dtype=float)
    pad = int(max(mask_padding, point_radius * 4, 4))
    min_xy = np.floor(points.min(axis=0)).astype(int) - pad
    max_xy = np.ceil(points.max(axis=0)).astype(int) + pad
    width = int(max_xy[0] - min_xy[0] + 1)
    height = int(max_xy[1] - min_xy[1] + 1)
    shifted = points - min_xy

    mask = np.zeros((height, width), dtype=bool)
    for x, y in shifted:
        _draw_disk_on_mask(mask, y, x, point_radius)

    labels = label(mask, connectivity=2)
    point_labels = labels[
        np.clip(np.round(shifted[:, 1]).astype(int), 0, height - 1),
        np.clip(np.round(shifted[:, 0]).astype(int), 0, width - 1),
    ]
    valid_labels = point_labels[point_labels > 0]
    if len(valid_labels) == 0:
        return np.ones(len(points), dtype=bool)
    label_counts = pd.Series(valid_labels).value_counts()
    largest_label = label_counts.index[0]
    return point_labels == largest_label


def compute_minimal_bridge_uncovered_cell_contours(
    single_cell_df,
    *,
    group_col="filename",
    track_id_col="unique_id",
    coordinate_units="pixels",
    x_col=None,
    y_col=None,
    max_contours=2,
    min_uncovered_points=20,
    min_uncovered_tracks=1,
    min_uncovered_fraction=0.05,
    point_radius=2.0,
    bridge_width=1.5,
    mask_padding=12,
    edge_padding=0.0,
    edge_smoothing=0.02,
):
    """
    Compute one or two minimal-bridge contours for a cell.

    The first contour is made from the largest locally connected point blob.
    Points not covered by that first contour are then tested against thresholds;
    if enough remain, a second minimal-bridge contour is made only from those
    uncovered points.
    """
    df = _as_pandas_copy(single_cell_df)
    if x_col is None:
        x_col = "x" if coordinate_units == "pixels" else "x_um"
    if y_col is None:
        y_col = "y" if coordinate_units == "pixels" else "y_um"
    for col in [x_col, y_col, track_id_col]:
        if col not in df.columns:
            raise ValueError(f"Column {col!r} not found")

    df = df.dropna(subset=[x_col, y_col, track_id_col]).copy()
    points = df[[x_col, y_col]].to_numpy()
    if len(points) < 3:
        raise ValueError("At least three points are required to compute a contour")

    def _row_from_subset(sub, contour_id, source_status, forbidden_contours=None):
        sub_points = sub[[x_col, y_col]].to_numpy()
        contour = compute_cell_edge_minimal_bridge(
            sub_points,
            point_radius=point_radius,
            bridge_width=bridge_width,
            mask_padding=mask_padding,
            edge_padding=edge_padding,
            edge_smoothing=edge_smoothing,
            forbidden_contours=forbidden_contours,
            enforce_point_containment=forbidden_contours is None,
        )
        area, perimeter = _polygon_area_perimeter(contour)
        centroid = sub_points.mean(axis=0)
        return {
            group_col: _single_value_from_df(df, group_col),
            "contour_id": int(contour_id),
            "split_status": source_status,
            "coordinate_units": coordinate_units,
            "x_col": x_col,
            "y_col": y_col,
            "contour_x": contour[:, 0].astype(float).tolist(),
            "contour_y": contour[:, 1].astype(float).tolist(),
            "centroid_x": float(centroid[0]),
            "centroid_y": float(centroid[1]),
            "area": area,
            "perimeter": perimeter,
            "bbox_min_x": float(np.min(contour[:, 0])),
            "bbox_max_x": float(np.max(contour[:, 0])),
            "bbox_min_y": float(np.min(contour[:, 1])),
            "bbox_max_y": float(np.max(contour[:, 1])),
            "n_contour_points": int(len(contour)),
            "n_source_points": int(len(sub_points)),
            "n_tracks": int(sub[track_id_col].nunique()),
            "track_ids": list(pd.unique(sub[track_id_col])),
            "contour_method": "minimal_bridge_uncovered",
            "minimal_bridge_point_radius": float(point_radius),
            "minimal_bridge_width": float(bridge_width),
            "minimal_bridge_mask_padding": int(mask_padding),
            "edge_padding": float(edge_padding),
            "edge_smoothing": float(edge_smoothing),
        }

    main_mask = _largest_blob_point_mask(
        points,
        point_radius=point_radius,
        mask_padding=mask_padding,
    )
    main_df = df[main_mask].copy()
    if len(main_df) < 3:
        main_df = df.copy()

    rows = [_row_from_subset(main_df, 1, "main_largest_blob")]
    if int(max_contours) <= 1:
        return rows

    contour1 = np.column_stack([rows[0]["contour_x"], rows[0]["contour_y"]])
    covered = mpltPath.Path(contour1).contains_points(points, radius=0.5)
    uncovered_df = df[~covered].copy()

    if len(uncovered_df) >= int(min_uncovered_points):
        if uncovered_df[track_id_col].nunique() >= int(min_uncovered_tracks):
            if len(uncovered_df) / len(df) >= float(min_uncovered_fraction):
                if len(uncovered_df[[x_col, y_col]].dropna()) >= 3:
                    rows.append(
                        _row_from_subset(
                            uncovered_df,
                            2,
                            "uncovered_points",
                            forbidden_contours=[contour1],
                        )
                    )

    return rows


def compute_minimal_bridge_uncovered_contours_dataframe(
    tracks_df,
    *,
    group_col="filename",
    coordinate_units="pixels",
    x_col=None,
    y_col=None,
    metadata_cols=None,
    selection_method=None,
    n_cells=None,
    track_id_col="unique_id",
    random_state=42,
    return_backend="polars",
    **kwargs,
):
    """
    Compute one or two minimal-bridge contours for multiple cells.
    """
    if x_col is None:
        x_col = "x" if coordinate_units == "pixels" else "x_um"
    if y_col is None:
        y_col = "y" if coordinate_units == "pixels" else "y_um"

    df = _as_pandas_copy(tracks_df)
    for col in [group_col, x_col, y_col, track_id_col]:
        if col not in df.columns:
            raise ValueError(f"Column {col!r} not found")

    metadata_cols = list(metadata_cols or [])
    metadata_cols = [col for col in metadata_cols if col in df.columns and col != group_col]

    cell_summary = (
        df.groupby(group_col)
        .agg(
            n_datapoints=(x_col, "size"),
            n_tracks=(track_id_col, "nunique"),
        )
        .reset_index()
    )
    if selection_method == "most_tracks":
        cell_summary = cell_summary.sort_values(
            ["n_tracks", "n_datapoints"], ascending=False
        )
    elif selection_method == "most_points":
        cell_summary = cell_summary.sort_values(
            ["n_datapoints", "n_tracks"], ascending=False
        )
    elif selection_method == "random":
        cell_summary = cell_summary.sample(
            frac=1, random_state=random_state
        ).reset_index(drop=True)
    elif selection_method is not None:
        raise ValueError(
            "selection_method must be None, 'most_tracks', 'most_points', or 'random'"
        )
    if n_cells is not None:
        cell_summary = cell_summary.head(int(n_cells))

    rows = []
    for cell_id in cell_summary[group_col].tolist():
        sub = df[df[group_col] == cell_id].copy()
        contour_rows = compute_minimal_bridge_uncovered_cell_contours(
            sub,
            group_col=group_col,
            track_id_col=track_id_col,
            coordinate_units=coordinate_units,
            x_col=x_col,
            y_col=y_col,
            **kwargs,
        )
        for row in contour_rows:
            for col in metadata_cols:
                row[col] = _single_value_from_df(sub, col)
            rows.append(row)

    result = pd.DataFrame(rows)
    if return_backend == "pandas":
        return result
    if return_backend == "polars":
        return pl.from_pandas(result)
    raise ValueError("return_backend must be 'polars' or 'pandas'")


def compute_segmented_cell_contours_dataframe(
    tracks_df,
    *,
    group_col="filename",
    coordinate_units="pixels",
    x_col=None,
    y_col=None,
    metadata_cols=None,
    selection_method=None,
    n_cells=None,
    track_id_col="unique_id",
    random_state=42,
    return_backend="polars",
    **segmented_kwargs,
):
    """
    Compute experimental segmented contours for multiple cells.

    Returns one row per contour component. For unsplit cells, the returned table
    still contains one row with ``contour_id == 1`` and ``split_status`` showing
    the fallback reason.
    """
    if x_col is None:
        x_col = "x" if coordinate_units == "pixels" else "x_um"
    if y_col is None:
        y_col = "y" if coordinate_units == "pixels" else "y_um"

    if isinstance(tracks_df, pl.DataFrame) and n_cells is not None:
        agg_exprs = [pl.len().alias("n_datapoints")]
        if track_id_col in tracks_df.columns:
            agg_exprs.append(pl.col(track_id_col).n_unique().alias("n_tracks"))
        else:
            agg_exprs.append(pl.len().alias("n_tracks"))
        summary_pl = tracks_df.group_by(group_col).agg(agg_exprs)
        if selection_method == "most_tracks":
            summary_pl = summary_pl.sort(["n_tracks", "n_datapoints"], descending=True)
        elif selection_method == "most_points":
            summary_pl = summary_pl.sort(["n_datapoints", "n_tracks"], descending=True)
        elif selection_method == "random":
            summary_pl = summary_pl.sample(fraction=1.0, shuffle=True, seed=random_state)
        elif selection_method is not None:
            raise ValueError(
                "selection_method must be None, 'most_tracks', 'most_points', or 'random'"
            )
        selected_cells = summary_pl.head(int(n_cells))[group_col].to_list()
        tracks_df = tracks_df.filter(pl.col(group_col).is_in(selected_cells))

    df = _as_pandas_copy(tracks_df)
    for col in [group_col, x_col, y_col, track_id_col]:
        if col not in df.columns:
            raise ValueError(f"Column {col!r} not found")

    metadata_cols = list(metadata_cols or [])
    metadata_cols = [col for col in metadata_cols if col in df.columns and col != group_col]

    cell_summary = (
        df.groupby(group_col)
        .agg(
            n_datapoints=(x_col, "size"),
            n_tracks=(track_id_col, "nunique"),
        )
        .reset_index()
    )
    if selection_method == "most_tracks":
        cell_summary = cell_summary.sort_values(
            ["n_tracks", "n_datapoints"], ascending=False
        )
    elif selection_method == "most_points":
        cell_summary = cell_summary.sort_values(
            ["n_datapoints", "n_tracks"], ascending=False
        )
    elif selection_method == "random":
        cell_summary = cell_summary.sample(
            frac=1, random_state=random_state
        ).reset_index(drop=True)
    elif selection_method is not None:
        raise ValueError(
            "selection_method must be None, 'most_tracks', 'most_points', or 'random'"
        )
    if n_cells is not None:
        cell_summary = cell_summary.head(int(n_cells))

    rows = []
    for cell_id in cell_summary[group_col].tolist():
        sub = df[df[group_col] == cell_id].copy()
        contour_rows = compute_segmented_cell_contours(
            sub,
            group_col=group_col,
            track_id_col=track_id_col,
            coordinate_units=coordinate_units,
            x_col=x_col,
            y_col=y_col,
            **segmented_kwargs,
        )
        for row in contour_rows:
            row[group_col] = cell_id
            for col in metadata_cols:
                row[col] = _single_value_from_df(sub, col)
            rows.append(row)

    result = pd.DataFrame(rows)
    if not result.empty and "component_label" in result.columns:
        result["component_label"] = pd.to_numeric(
            result["component_label"], errors="coerce"
        ).astype("Int64")
    if return_backend == "pandas":
        return result
    if return_backend == "polars":
        return pl.from_pandas(result)
    raise ValueError("return_backend must be 'polars' or 'pandas'")


def add_contour_ids_for_multicontour_tracks(
    df,
    contours_df,
    *,
    group_col="filename",
    track_id_col="unique_id",
    contour_id_col="contour_id",
    output_col="contour_id",
    track_ids_col="track_ids",
    return_backend=None,
):
    """
    Add contour IDs to track rows only for filenames with multiple contours.

    The mapping uses the ``track_ids`` stored in segmented ``contours_df``. This
    avoids recomputing clustering for instant/windowed dataframes and only
    touches cells where a filename has more than one contour row.
    """
    input_is_polars = isinstance(df, pl.DataFrame)
    contours_pdf = _as_pandas_copy(contours_df)
    for col in [group_col, contour_id_col, track_ids_col]:
        if col not in contours_pdf.columns:
            raise ValueError(f"Column {col!r} not found in contours_df")

    contour_counts = contours_pdf.groupby(group_col)[contour_id_col].nunique()
    multicontour_cells = contour_counts[contour_counts > 1].index.tolist()
    mapping_rows = []
    for _, row in contours_pdf[
        contours_pdf[group_col].isin(multicontour_cells)
    ].iterrows():
        for track_id in row[track_ids_col]:
            mapping_rows.append(
                {
                    group_col: row[group_col],
                    track_id_col: track_id,
                    "_mapped_contour_id": row[contour_id_col],
                }
            )

    if not mapping_rows:
        if return_backend == "polars" or (return_backend is None and input_is_polars):
            result = df.clone() if input_is_polars else pl.from_pandas(_as_pandas_copy(df))
            if output_col not in result.columns:
                result = result.with_columns(pl.lit(None).alias(output_col))
            return result
        result = _as_pandas_copy(df)
        if output_col not in result.columns:
            result[output_col] = pd.NA
        return result

    mapping_pdf = pd.DataFrame(mapping_rows).drop_duplicates(
        subset=[group_col, track_id_col]
    )
    if input_is_polars:
        mapping_pl = pl.from_pandas(mapping_pdf)
        result = df.join(mapping_pl, on=[group_col, track_id_col], how="left")
        if output_col in result.columns:
            result = result.with_columns(
                pl.coalesce([pl.col("_mapped_contour_id"), pl.col(output_col)]).alias(
                    output_col
                )
            )
        else:
            result = result.rename({"_mapped_contour_id": output_col})
        if "_mapped_contour_id" in result.columns:
            result = result.drop("_mapped_contour_id")
        if return_backend == "pandas":
            return result.to_pandas()
        return result

    result = _as_pandas_copy(df)
    result = result.merge(mapping_pdf, on=[group_col, track_id_col], how="left")
    if output_col in result.columns:
        result[output_col] = result["_mapped_contour_id"].combine_first(result[output_col])
        result = result.drop(columns=["_mapped_contour_id"])
    else:
        result = result.rename(columns={"_mapped_contour_id": output_col})
    if return_backend == "polars":
        return pl.from_pandas(result)
    return result


def add_contour_measurements_by_filename(
    df,
    contours_df,
    *,
    group_col="filename",
    contour_id_col="contour_id",
    area_col="area",
    perimeter_col="perimeter",
    circumference_col="circumference",
    prefix="contour_",
):
    """
    Join one-contour-per-filename measurements onto a track dataframe.

    This is intended for the settled single-contour workflow. If ``contours_df``
    contains multiple contour rows for a filename, the first contour_id after
    sorting is used to avoid duplicating track rows.
    """
    output_is_polars = isinstance(df, pl.DataFrame)

    if isinstance(contours_df, pl.DataFrame):
        contour_columns = contours_df.columns
        required = [group_col, contour_id_col, area_col, perimeter_col]
        for col in required:
            if col not in contour_columns:
                raise ValueError(f"Column {col!r} not found in contours_df")
        circumference_expr = (
            pl.col(circumference_col)
            if circumference_col in contour_columns
            else pl.col(perimeter_col)
        )
        mapping = (
            contours_df.sort([group_col, contour_id_col])
            .group_by(group_col, maintain_order=True)
            .agg(
                [
                    pl.col(contour_id_col).first().alias(f"{prefix}id"),
                    pl.col(area_col).first().alias(f"{prefix}area"),
                    pl.col(perimeter_col).first().alias(f"{prefix}perimeter"),
                    circumference_expr.first().alias(f"{prefix}circumference"),
                ]
            )
        )
        if output_is_polars:
            return df.join(mapping, on=group_col, how="left")
        return _as_pandas_copy(df).merge(mapping.to_pandas(), on=group_col, how="left")

    contour_pdf = _as_pandas_copy(contours_df)
    required = [group_col, contour_id_col, area_col, perimeter_col]
    for col in required:
        if col not in contour_pdf.columns:
            raise ValueError(f"Column {col!r} not found in contours_df")
    if circumference_col not in contour_pdf.columns:
        contour_pdf[circumference_col] = contour_pdf[perimeter_col]
    mapping_pdf = (
        contour_pdf.sort_values([group_col, contour_id_col])
        .groupby(group_col, as_index=False)
        .first()
    )
    mapping_pdf = mapping_pdf[
        [group_col, contour_id_col, area_col, perimeter_col, circumference_col]
    ].rename(
        columns={
            contour_id_col: f"{prefix}id",
            area_col: f"{prefix}area",
            perimeter_col: f"{prefix}perimeter",
            circumference_col: f"{prefix}circumference",
        }
    )
    if output_is_polars:
        return df.join(pl.from_pandas(mapping_pdf), on=group_col, how="left")
    return _as_pandas_copy(df).merge(mapping_pdf, on=group_col, how="left")


def plot_segmented_cell_contours_qc(
    single_cell_df,
    contours_df,
    *,
    group_col="filename",
    track_id_col="unique_id",
    contour_id_col="contour_id",
    coordinate_units="pixels",
    x_col=None,
    y_col=None,
    frame_col="frame",
    frame_range=None,
    track_colorway="tab10",
    track_line_width=0.8,
    track_alpha=0.7,
    contour_colors=None,
    contour_line_width=1.4,
    contour_line_style="--",
    show_raw_projection=False,
    raw_movie_path=None,
    raw_master_dir=None,
    raw_projection="max",
    raw_max_frames=250,
    raw_contrast_limits=None,
    invert_raw=False,
    raw_cmap="gray",
    raw_lut=None,
    figsize=(4, 4),
    dpi=150,
    show_plot=True,
):
    """
    QC plot for one cell with segmented contours and matching track colors.
    """
    tracks = _as_pandas_copy(single_cell_df)
    contours = _as_pandas_copy(contours_df)
    if x_col is None:
        x_col = "x" if coordinate_units == "pixels" else "x_um"
    if y_col is None:
        y_col = "y" if coordinate_units == "pixels" else "y_um"
    for col in [x_col, y_col, track_id_col]:
        if col not in tracks.columns:
            raise ValueError(f"Column {col!r} not found in single_cell_df")
    for col in ["contour_x", "contour_y", contour_id_col]:
        if col not in contours.columns:
            raise ValueError(f"Column {col!r} not found in contours_df")

    if group_col in tracks.columns and group_col in contours.columns:
        cell_id = _single_value_from_df(tracks, group_col)
        contours = contours[contours[group_col] == cell_id].copy()

    mapped_tracks = add_contour_ids_for_multicontour_tracks(
        tracks,
        contours,
        group_col=group_col,
        track_id_col=track_id_col,
        contour_id_col=contour_id_col,
        output_col=contour_id_col,
        return_backend="pandas",
    )
    if frame_range is not None and frame_col in mapped_tracks.columns:
        frame_start, frame_end = map(int, frame_range)
        mapped_tracks = mapped_tracks[
            (mapped_tracks[frame_col] >= frame_start)
            & (mapped_tracks[frame_col] <= frame_end)
        ].copy()

    fig, ax = plt.subplots(figsize=figsize, dpi=dpi)

    if show_raw_projection:
        if frame_range is not None:
            raw_frame_start, raw_frame_end = map(int, frame_range)
        elif frame_col in tracks.columns:
            raw_frame_start = int(tracks[frame_col].min())
            raw_frame_end = int(tracks[frame_col].max())
        else:
            raw_frame_start = raw_frame_end = None
        if raw_frame_start is not None and raw_frame_end is not None:
            raw_movie_path = raw_movie_path or _resolve_raw_movie_path(
                tracks, master_dir=raw_master_dir
            )
            raw_frame_indices = np.arange(raw_frame_start, raw_frame_end + 1)
            if raw_max_frames is not None and len(raw_frame_indices) > int(raw_max_frames):
                raw_frame_indices = np.linspace(
                    raw_frame_start,
                    raw_frame_end,
                    int(raw_max_frames),
                    dtype=int,
                )
            raw_stack = _load_raw_frame_indices(raw_movie_path, raw_frame_indices)
            if raw_stack.ndim == 2:
                raw_image = raw_stack
            elif raw_projection == "max":
                raw_image = np.nanmax(raw_stack, axis=0)
            elif raw_projection == "sum":
                raw_image = np.nansum(raw_stack, axis=0)
            elif raw_projection == "mean":
                raw_image = np.nanmean(raw_stack, axis=0)
            else:
                raise ValueError("raw_projection must be 'max', 'sum', or 'mean'")
            ax.imshow(
                _normalize_raw_image(
                    raw_image,
                    contrast_limits=raw_contrast_limits,
                    invert_image=invert_raw,
                ),
                cmap=_coerce_lut_colormap(raw_lut, target="matplotlib", fallback=raw_cmap),
                origin="upper",
            )

    if contour_colors is None:
        cmap = plt.get_cmap(track_colorway, max(len(contours), 1))
        contour_colors = {
            contour_id: cmap(i)
            for i, contour_id in enumerate(pd.unique(contours[contour_id_col]))
        }

    segments = []
    colors = []
    color_source = (
        mapped_tracks.dropna(subset=[contour_id_col])
        if contour_id_col in mapped_tracks.columns
        else pd.DataFrame()
    )
    color_map = (
        _track_color_map(color_source, track_id_col, contour_id_col, track_colorway)
        if not color_source.empty
        else {}
    )
    sort_col = frame_col if frame_col in mapped_tracks.columns else x_col
    for track_id, track in mapped_tracks.sort_values(sort_col).groupby(track_id_col):
        if len(track) < 2:
            continue
        segments.append(track[[x_col, y_col]].to_numpy())
        colors.append(color_map.get(track_id, "0.55"))
    if segments:
        ax.add_collection(
            LineCollection(
                segments,
                colors=colors,
                linewidths=track_line_width,
                alpha=track_alpha,
            )
        )

    for _, row in contours.iterrows():
        contour = np.column_stack(
            [
                np.asarray(row["contour_x"], dtype=float),
                np.asarray(row["contour_y"], dtype=float),
            ]
        )
        contour_id = row[contour_id_col]
        ax.plot(
            contour[:, 0],
            contour[:, 1],
            color=contour_colors.get(contour_id, "yellow")
            if isinstance(contour_colors, dict)
            else None,
            lw=contour_line_width,
            linestyle=contour_line_style,
            label=f"contour {contour_id}",
        )

    ax.set_aspect("equal", adjustable="box")
    if coordinate_units == "pixels":
        ax.invert_yaxis()
    ax.axis("off")
    ax.legend(loc="upper right", fontsize=7)
    if show_plot:
        plt.show()
    else:
        plt.close(fig)
    return {
        "fig": fig,
        "ax": ax,
        "tracks_df": mapped_tracks,
        "contours_df": contours,
    }


def plot_segmented_contour_gallery(
    tracks_df,
    contours_df,
    *,
    n_cells=16,
    selection_method="most_tracks",
    group_col="filename",
    track_id_col="unique_id",
    contour_id_col="contour_id",
    track_ids_col="track_ids",
    coordinate_units="pixels",
    x_col=None,
    y_col=None,
    n_cols=4,
    figsize_per_cell=(2, 2),
    contour_colors=None,
    contour_colorway="tab10",
    contour_line_width=1.0,
    contour_line_style="--",
    show_contour_ids=True,
    contour_id_fontsize=8,
    show_panel_numbers=True,
    panel_number_start=1,
    show_tracks=True,
    track_color_mode="by_contour",
    track_color="0.55",
    track_colorway="tab20",
    track_line_width=0.7,
    track_alpha=0.85,
    max_tracks_per_cell=80,
    frame_range=None,
    frame_col="frame",
    show_raw_projection=False,
    raw_projection="max",
    raw_projection_frame_range=None,
    raw_max_frames=250,
    raw_master_dir=None,
    raw_contrast_limits=None,
    invert_raw=False,
    raw_cmap="gray",
    raw_lut=None,
    raw_alpha=1.0,
    title_col=None,
    save_path=None,
    dpi=150,
    show_plot=True,
):
    """
    Gallery for segmented contour results.

    Unlike ``plot_cell_contour_gallery``, this groups multiple contour rows with
    the same filename into a single panel and labels each ``contour_id``.
    """
    contour_pdf = _as_pandas_copy(contours_df)
    if contour_pdf.empty:
        raise ValueError("contours_df is empty")
    for col in [group_col, contour_id_col, "contour_x", "contour_y"]:
        if col not in contour_pdf.columns:
            raise ValueError(f"Column {col!r} not found in contours_df")

    if isinstance(tracks_df, pl.DataFrame):
        if group_col not in tracks_df.columns:
            raise ValueError(f"Column {group_col!r} not found in tracks_df")
        summary_pl = tracks_df.group_by(group_col).agg(
            [
                pl.len().alias("n_datapoints"),
                pl.col(track_id_col).n_unique().alias("n_tracks")
                if track_id_col in tracks_df.columns
                else pl.len().alias("n_tracks"),
            ]
        )
        if selection_method == "most_tracks":
            summary_pl = summary_pl.sort(["n_tracks", "n_datapoints"], descending=True)
        elif selection_method == "most_points":
            summary_pl = summary_pl.sort(["n_datapoints", "n_tracks"], descending=True)
        elif selection_method == "random":
            summary_pl = summary_pl.sample(fraction=1.0, shuffle=True, seed=42)
        elif selection_method is not None:
            raise ValueError(
                "selection_method must be None, 'most_tracks', 'most_points', or 'random'"
            )
        available_cells = set(contour_pdf[group_col].dropna().unique())
        selected_cells = [
            cell for cell in summary_pl[group_col].to_list() if cell in available_cells
        ]
        if n_cells is not None:
            selected_cells = selected_cells[: int(n_cells)]
        selected_tracks = tracks_df.filter(pl.col(group_col).is_in(selected_cells))
        if frame_range is not None and frame_col in selected_tracks.columns:
            frame_start, frame_end = map(int, frame_range)
            selected_tracks = selected_tracks.filter(
                (pl.col(frame_col) >= frame_start) & (pl.col(frame_col) <= frame_end)
            )
        if (
            max_tracks_per_cell is not None
            and track_id_col in selected_tracks.columns
            and show_tracks
        ):
            track_counts = selected_tracks.group_by([group_col, track_id_col]).agg(
                pl.len().alias("_n_track_points")
            )
            top_tracks = (
                track_counts.with_columns(
                    pl.col("_n_track_points")
                    .rank("ordinal", descending=True)
                    .over(group_col)
                    .alias("_track_rank")
                )
                .filter(pl.col("_track_rank") <= int(max_tracks_per_cell))
                .select([group_col, track_id_col])
            )
            selected_tracks = selected_tracks.join(
                top_tracks, on=[group_col, track_id_col], how="inner"
            )
        selected_track_df = selected_tracks.to_pandas()
    else:
        track_pdf = _as_pandas_copy(tracks_df)
        summary = (
            track_pdf.groupby(group_col)
            .agg(
                n_datapoints=(group_col, "size"),
                n_tracks=(track_id_col, "nunique")
                if track_id_col in track_pdf.columns
                else (group_col, "size"),
            )
            .reset_index()
        )
        if selection_method == "most_tracks":
            summary = summary.sort_values(["n_tracks", "n_datapoints"], ascending=False)
        elif selection_method == "most_points":
            summary = summary.sort_values(["n_datapoints", "n_tracks"], ascending=False)
        elif selection_method == "random":
            summary = summary.sample(frac=1, random_state=42)
        elif selection_method is not None:
            raise ValueError(
                "selection_method must be None, 'most_tracks', 'most_points', or 'random'"
            )
        available_cells = set(contour_pdf[group_col].dropna().unique())
        selected_cells = [
            cell for cell in summary[group_col].tolist() if cell in available_cells
        ]
        if n_cells is not None:
            selected_cells = selected_cells[: int(n_cells)]
        selected_track_df = track_pdf[track_pdf[group_col].isin(selected_cells)].copy()

    contour_pdf = contour_pdf[contour_pdf[group_col].isin(selected_cells)].copy()
    if contour_pdf.empty:
        raise ValueError("No segmented contours available for selected cells")

    n = len(selected_cells)
    n_cols = max(1, int(n_cols))
    n_rows = int(math.ceil(n / n_cols))
    fig, axes = plt.subplots(
        n_rows,
        n_cols,
        figsize=(figsize_per_cell[0] * n_cols, figsize_per_cell[1] * n_rows),
        squeeze=False,
        dpi=dpi,
    )
    for ax in axes.ravel():
        ax.axis("off")

    if contour_colors is None:
        contour_ids = list(pd.unique(contour_pdf[contour_id_col]))
        cmap = plt.get_cmap(contour_colorway, max(len(contour_ids), 1))
        contour_colors = {contour_id: cmap(i) for i, contour_id in enumerate(contour_ids)}

    lookup_rows = []
    for idx, cell_id in enumerate(selected_cells):
        ax = axes.ravel()[idx]
        cell_contours = contour_pdf[contour_pdf[group_col] == cell_id].copy()
        cell_tracks = selected_track_df[selected_track_df[group_col] == cell_id].copy()

        panel_number = int(panel_number_start) + idx
        foldername = _single_value_from_df(cell_tracks, "foldername", default="")
        filename_value = _single_value_from_df(cell_tracks, "filename", default=cell_id)
        lookup_rows.append(
            {
                "gallery_number": panel_number,
                group_col: cell_id,
                "filename": filename_value,
                "foldername": foldername,
                "n_contours": int(cell_contours[contour_id_col].nunique()),
            }
        )

        if show_raw_projection and not cell_tracks.empty:
            if raw_projection_frame_range is not None:
                raw_frame_start, raw_frame_end = map(int, raw_projection_frame_range)
            elif frame_range is not None:
                raw_frame_start, raw_frame_end = map(int, frame_range)
            elif frame_col in cell_tracks.columns:
                raw_frame_start = int(cell_tracks[frame_col].min())
                raw_frame_end = int(cell_tracks[frame_col].max())
            else:
                raw_frame_start = raw_frame_end = None
            if raw_frame_start is not None and raw_frame_end is not None:
                raw_movie_path = _resolve_raw_movie_path(
                    cell_tracks, master_dir=raw_master_dir
                )
                raw_frame_indices = np.arange(raw_frame_start, raw_frame_end + 1)
                if raw_max_frames is not None and len(raw_frame_indices) > int(raw_max_frames):
                    raw_frame_indices = np.linspace(
                        raw_frame_start,
                        raw_frame_end,
                        int(raw_max_frames),
                        dtype=int,
                    )
                raw_stack = _load_raw_frame_indices(raw_movie_path, raw_frame_indices)
                if raw_stack.ndim == 2:
                    raw_image = raw_stack
                elif raw_projection == "max":
                    raw_image = np.nanmax(raw_stack, axis=0)
                elif raw_projection == "sum":
                    raw_image = np.nansum(raw_stack, axis=0)
                elif raw_projection == "mean":
                    raw_image = np.nanmean(raw_stack, axis=0)
                else:
                    raise ValueError("raw_projection must be 'max', 'sum', or 'mean'")
                ax.imshow(
                    _normalize_raw_image(
                        raw_image,
                        contrast_limits=raw_contrast_limits,
                        invert_image=invert_raw,
                    ),
                    cmap=_coerce_lut_colormap(
                        raw_lut, target="matplotlib", fallback=raw_cmap
                    ),
                    origin="upper",
                    alpha=raw_alpha,
                    zorder=0,
                )

        if show_tracks and not cell_tracks.empty:
            x_col = (
                x_col
                or ("x" if coordinate_units == "pixels" and "x" in cell_tracks.columns else "x_um")
            )
            y_col = (
                y_col
                or ("y" if coordinate_units == "pixels" and "y" in cell_tracks.columns else "y_um")
            )
            if x_col not in cell_tracks.columns or y_col not in cell_tracks.columns:
                raise ValueError(f"Columns {x_col!r} and/or {y_col!r} not found in tracks_df")
            if {x_col, y_col, track_id_col}.issubset(cell_tracks.columns):
                track_to_contour = {}
                if track_ids_col in cell_contours.columns:
                    for _, contour_row in cell_contours.iterrows():
                        for track_id in contour_row[track_ids_col]:
                            track_to_contour[track_id] = contour_row[contour_id_col]
                cell_tracks["_gallery_contour_id"] = cell_tracks[track_id_col].map(
                    track_to_contour
                )
                if track_color_mode == "by_contour":
                    color_source = cell_tracks.dropna(subset=["_gallery_contour_id"])
                    track_colors = (
                        _track_color_map(
                            color_source,
                            track_id_col,
                            "_gallery_contour_id",
                            contour_colorway,
                        )
                        if not color_source.empty
                        else {}
                    )
                elif track_color_mode == "by_track":
                    track_colors = _track_color_map(
                        cell_tracks, track_id_col, track_id_col, track_colorway
                    )
                elif track_color_mode == "single":
                    track_colors = None
                else:
                    raise ValueError(
                        "track_color_mode must be 'by_contour', 'by_track', or 'single'"
                    )
                sort_col = frame_col if frame_col in cell_tracks.columns else x_col
                segments = []
                colors = []
                for track_id, track in cell_tracks.sort_values(sort_col).groupby(track_id_col):
                    if len(track) < 2:
                        continue
                    segments.append(track[[x_col, y_col]].to_numpy())
                    colors.append(
                        track_colors.get(track_id, track_color)
                        if track_colors is not None
                        else track_color
                    )
                if segments:
                    ax.add_collection(
                        LineCollection(
                            segments,
                            colors=colors,
                            linewidths=track_line_width,
                            alpha=track_alpha,
                            zorder=1,
                        )
                    )

        for _, contour_row in cell_contours.iterrows():
            contour = np.column_stack(
                [
                    np.asarray(contour_row["contour_x"], dtype=float),
                    np.asarray(contour_row["contour_y"], dtype=float),
                ]
            )
            contour_id = contour_row[contour_id_col]
            color = (
                contour_colors.get(contour_id, "yellow")
                if isinstance(contour_colors, dict)
                else None
            )
            ax.plot(
                contour[:, 0],
                contour[:, 1],
                color=color,
                lw=contour_line_width,
                linestyle=contour_line_style,
                zorder=2,
            )
            if show_contour_ids:
                label_x = contour_row.get("centroid_x", np.nanmean(contour[:, 0]))
                label_y = contour_row.get("centroid_y", np.nanmean(contour[:, 1]))
                ax.text(
                    label_x,
                    label_y,
                    str(contour_id),
                    color=color,
                    fontsize=contour_id_fontsize,
                    weight="bold",
                    ha="center",
                    va="center",
                    zorder=3,
                )

        ax.set_aspect("equal", adjustable="box")
        if coordinate_units == "pixels":
            ax.invert_yaxis()
        ax.axis("off")
        if show_panel_numbers:
            ax.set_title(str(panel_number), fontsize=8)
        elif title_col is not None and title_col in cell_contours.columns:
            ax.set_title(str(_single_value_from_df(cell_contours, title_col)), fontsize=8)
        else:
            ax.set_title(str(cell_id), fontsize=8)

    plt.tight_layout()
    if save_path is not None:
        os.makedirs(os.path.dirname(save_path) or ".", exist_ok=True)
        fig.savefig(save_path, dpi=dpi, bbox_inches="tight", transparent=True)
    if show_plot:
        plt.show()
    else:
        plt.close(fig)

    return {
        "fig": fig,
        "axes": axes,
        "contours_df": contour_pdf,
        "selected_cells": selected_cells,
        "cell_lookup_df": pd.DataFrame(lookup_rows),
    }


def plot_cell_contour_gallery(
    tracks_or_contours_df,
    *,
    n_cells=16,
    selection_method="most_tracks",
    group_col="filename",
    track_id_col="unique_id",
    coordinate_units="pixels",
    metadata_cols=None,
    n_cols=4,
    figsize_per_cell=(2, 2),
    contour_color="cyan",
    contour_line_width=1.0,
    contour_line_style="-",
    show_tracks=False,
    track_color_mode=None,
    track_color="yellow",
    track_color_by=None,
    track_colorway="tab20",
    track_line_width=0.7,
    track_alpha=0.85,
    max_tracks_per_cell=None,
    frame_range=None,
    frame_col="frame",
    show_raw_projection=False,
    raw_projection="max",
    raw_projection_frame_range=None,
    raw_max_frames=None,
    raw_master_dir=None,
    raw_contrast_limits=None,
    invert_raw=False,
    raw_cmap="gray",
    raw_lut=None,
    raw_alpha=1.0,
    show_points=False,
    point_size=0.4,
    point_alpha=0.15,
    title_col=None,
    title_metadata_cols=None,
    title_fontsize=8,
    title_metadata_fontsize=4,
    show_panel_numbers=False,
    panel_number_start=1,
    save_path=None,
    dpi=200,
    show_plot=True,
    **contour_kwargs,
):
    """
    Plot a gallery of fixed contours from either tracks or a stored contour table.

    If ``show_tracks=True`` and the input is a track dataframe, the selected cell
    tracks are drawn behind each contour for track-footprint QC.

    If ``show_raw_projection=True``, a raw movie projection is drawn below the
    tracks/contour for each selected cell. Use ``raw_max_frames`` to sample long
    movies for gallery QC without loading every frame.

    ``track_color_mode`` can be ``"single"``, ``"by_track"``, or ``"by_column"``.
    For ``"by_column"``, pass the column name with ``track_color_by``. If left
    as ``None``, the function uses ``"by_column"`` when ``track_color_by`` is
    valid and otherwise uses ``"by_track"``.
    """
    source_is_contour_table = False
    selected_track_df = None

    if isinstance(tracks_or_contours_df, pl.DataFrame):
        source_columns = tracks_or_contours_df.columns
        source_is_contour_table = {"contour_x", "contour_y"}.issubset(source_columns)
        input_df = _as_pandas_copy(tracks_or_contours_df) if source_is_contour_table else None
    else:
        input_preview = _as_pandas_copy(tracks_or_contours_df)
        source_is_contour_table = {"contour_x", "contour_y"}.issubset(
            input_preview.columns
        )
        input_df = input_preview

    if source_is_contour_table:
        contour_df = input_df.copy()
        if selection_method == "random":
            contour_df = contour_df.sample(
                frac=1, random_state=contour_kwargs.get("random_state", 42)
            ).reset_index(drop=True)
        elif selection_method in {"most_tracks", "most_points"}:
            sort_col = "n_tracks" if selection_method == "most_tracks" else "n_source_points"
            if sort_col in contour_df.columns:
                contour_df = contour_df.sort_values(sort_col, ascending=False)
        elif selection_method is not None:
            raise ValueError(
                "selection_method must be None, 'most_tracks', 'most_points', or 'random'"
            )
        contour_df = contour_df.head(int(n_cells))
    else:
        contour_df = compute_cell_contours_dataframe(
            tracks_or_contours_df,
            group_col=group_col,
            coordinate_units=coordinate_units,
            metadata_cols=metadata_cols,
            selection_method=selection_method,
            n_cells=n_cells,
            track_id_col=track_id_col,
            return_backend="pandas",
            **contour_kwargs,
        )
        selected_cells_for_tracks = (
            contour_df[group_col].tolist()
            if group_col in contour_df.columns
            else []
        )
        if (show_tracks or show_raw_projection) and selected_cells_for_tracks:
            if isinstance(tracks_or_contours_df, pl.DataFrame):
                selected_tracks = tracks_or_contours_df.filter(
                    pl.col(group_col).is_in(selected_cells_for_tracks)
                )
                if frame_range is not None and frame_col in selected_tracks.columns:
                    frame_start, frame_end = map(int, frame_range)
                    selected_tracks = selected_tracks.filter(
                        (pl.col(frame_col) >= frame_start)
                        & (pl.col(frame_col) <= frame_end)
                    )
                if (
                    max_tracks_per_cell is not None
                    and track_id_col in selected_tracks.columns
                ):
                    track_counts = selected_tracks.group_by(
                        [group_col, track_id_col]
                    ).agg(pl.len().alias("_n_track_points"))
                    top_tracks = (
                        track_counts.with_columns(
                            pl.col("_n_track_points")
                            .rank("ordinal", descending=True)
                            .over(group_col)
                            .alias("_track_rank")
                        )
                        .filter(pl.col("_track_rank") <= int(max_tracks_per_cell))
                        .select([group_col, track_id_col])
                    )
                    selected_tracks = selected_tracks.join(
                        top_tracks, on=[group_col, track_id_col], how="inner"
                    )
                selected_track_df = selected_tracks.to_pandas()
            else:
                selected_track_df = input_df[
                    input_df[group_col].isin(selected_cells_for_tracks)
                ].copy()
                if frame_range is not None and frame_col in selected_track_df.columns:
                    frame_start, frame_end = map(int, frame_range)
                    selected_track_df = selected_track_df[
                        (selected_track_df[frame_col] >= frame_start)
                        & (selected_track_df[frame_col] <= frame_end)
                    ]
                if (
                    max_tracks_per_cell is not None
                    and track_id_col in selected_track_df.columns
                ):
                    selected_track_df["_n_track_points"] = selected_track_df.groupby(
                        [group_col, track_id_col]
                    )[track_id_col].transform("size")
                    ranks = (
                        selected_track_df[[group_col, track_id_col, "_n_track_points"]]
                        .drop_duplicates()
                        .sort_values([group_col, "_n_track_points"], ascending=False)
                    )
                    ranks["_track_rank"] = ranks.groupby(group_col).cumcount() + 1
                    keep_tracks = ranks[
                        ranks["_track_rank"] <= int(max_tracks_per_cell)
                    ][[group_col, track_id_col]]
                    selected_track_df = selected_track_df.merge(
                        keep_tracks, on=[group_col, track_id_col], how="inner"
                    )
                    selected_track_df = selected_track_df.drop(
                        columns=["_n_track_points"], errors="ignore"
                    )

    if contour_df.empty:
        raise ValueError("No contours available for gallery")

    contour_df = contour_df.copy()
    contour_df["_gallery_number"] = np.arange(
        int(panel_number_start),
        int(panel_number_start) + len(contour_df),
    )

    n = len(contour_df)
    n_cols = max(1, int(n_cols))
    n_rows = int(math.ceil(n / n_cols))
    fig, axes = plt.subplots(
        n_rows,
        n_cols,
        figsize=(figsize_per_cell[0] * n_cols, figsize_per_cell[1] * n_rows),
        squeeze=False,
        dpi=dpi,
    )

    for ax in axes.ravel():
        ax.axis("off")

    for idx, (_, row) in enumerate(contour_df.iterrows()):
        ax = axes.ravel()[idx]
        contour = np.column_stack(
            [
                np.asarray(row["contour_x"], dtype=float),
                np.asarray(row["contour_y"], dtype=float),
            ]
        )
        cell_tracks = None
        if selected_track_df is not None and group_col in selected_track_df.columns:
            cell_tracks = selected_track_df[selected_track_df[group_col] == row[group_col]]

        if show_raw_projection and cell_tracks is not None and not cell_tracks.empty:
            if raw_projection_frame_range is not None:
                raw_frame_start, raw_frame_end = map(int, raw_projection_frame_range)
            elif frame_range is not None:
                raw_frame_start, raw_frame_end = map(int, frame_range)
            elif frame_col in cell_tracks.columns:
                raw_frame_start = int(cell_tracks[frame_col].min())
                raw_frame_end = int(cell_tracks[frame_col].max())
            else:
                raw_frame_start = raw_frame_end = None

            if raw_frame_start is not None and raw_frame_end is not None:
                raw_movie_path = _resolve_raw_movie_path(
                    cell_tracks,
                    master_dir=raw_master_dir,
                )
                raw_frame_indices = np.arange(raw_frame_start, raw_frame_end + 1)
                if raw_max_frames is not None and len(raw_frame_indices) > int(raw_max_frames):
                    raw_frame_indices = np.linspace(
                        raw_frame_start,
                        raw_frame_end,
                        int(raw_max_frames),
                        dtype=int,
                    )
                raw_stack = _load_raw_frame_indices(raw_movie_path, raw_frame_indices)
                if raw_stack.ndim == 2:
                    raw_image = raw_stack
                elif raw_projection == "max":
                    raw_image = np.nanmax(raw_stack, axis=0)
                elif raw_projection == "sum":
                    raw_image = np.nansum(raw_stack, axis=0)
                elif raw_projection == "mean":
                    raw_image = np.nanmean(raw_stack, axis=0)
                else:
                    raise ValueError("raw_projection must be 'max', 'sum', or 'mean'")
                raw_image = _normalize_raw_image(
                    raw_image,
                    contrast_limits=raw_contrast_limits,
                    invert_image=invert_raw,
                )
                ax.imshow(
                    raw_image,
                    cmap=_coerce_lut_colormap(
                        raw_lut, target="matplotlib", fallback=raw_cmap
                    ),
                    origin="upper",
                    alpha=raw_alpha,
                    zorder=0,
                )

        if show_tracks and selected_track_df is not None and group_col in selected_track_df.columns:
            x_col = "x" if coordinate_units == "pixels" and "x" in cell_tracks.columns else "x_um"
            y_col = "y" if coordinate_units == "pixels" and "y" in cell_tracks.columns else "y_um"
            if {x_col, y_col, track_id_col}.issubset(cell_tracks.columns):
                resolved_track_color_mode = track_color_mode
                if resolved_track_color_mode is None:
                    resolved_track_color_mode = (
                        "by_column"
                        if track_color_by is not None and track_color_by in cell_tracks.columns
                        else "by_track"
                    )
                if resolved_track_color_mode == "single":
                    track_colors = None
                elif (
                    resolved_track_color_mode == "by_column"
                    and track_color_by in cell_tracks.columns
                ):
                    track_colors = _track_color_map(
                        cell_tracks,
                        track_id_col,
                        track_color_by,
                        track_colorway,
                    )
                elif resolved_track_color_mode == "by_track":
                    track_colors = _track_color_map(
                        cell_tracks,
                        track_id_col,
                        track_id_col,
                        track_colorway,
                    )
                else:
                    raise ValueError(
                        "track_color_mode must be 'single', 'by_track', or "
                        "'by_column' with a valid track_color_by column"
                    )
                sort_col = frame_col if frame_col in cell_tracks.columns else x_col
                segments = []
                colors = []
                for track_id, track in cell_tracks.sort_values(sort_col).groupby(track_id_col):
                    if len(track) < 2:
                        continue
                    segments.append(track[[x_col, y_col]].to_numpy())
                    colors.append(track_colors.get(track_id, track_color) if track_colors else track_color)
                if segments:
                    ax.add_collection(
                        LineCollection(
                            segments,
                            colors=colors,
                            linewidths=track_line_width,
                            alpha=track_alpha,
                            zorder=1,
                        )
                    )
        ax.plot(
            contour[:, 0],
            contour[:, 1],
            color=contour_color,
            lw=contour_line_width,
            linestyle=contour_line_style,
            zorder=2,
        )
        if show_points and {"source_x", "source_y"}.issubset(contour_df.columns):
            ax.scatter(
                row["source_x"],
                row["source_y"],
                s=point_size,
                alpha=point_alpha,
                color=contour_color,
            )
        ax.set_aspect("equal", adjustable="box")
        ax.invert_yaxis()
        ax.axis("off")

        if show_panel_numbers:
            title = str(row["_gallery_number"])
        elif title_col is not None and title_col in contour_df.columns:
            title = f"{row[title_col]}"
        elif group_col in contour_df.columns:
            title = str(row[group_col])
        else:
            title = f"cell {idx + 1}"
        ax.set_title(title, fontsize=title_fontsize)
        if title_metadata_cols and not show_panel_numbers:
            metadata_lines = [
                f"{col}: {row[col]}"
                for col in title_metadata_cols
                if col in contour_df.columns
            ]
            if metadata_lines:
                ax.text(
                    0.5,
                    -0.02,
                    "\n".join(metadata_lines),
                    transform=ax.transAxes,
                    ha="center",
                    va="top",
                    fontsize=title_metadata_fontsize,
                    clip_on=False,
                )

    plt.tight_layout()
    if save_path is not None:
        os.makedirs(os.path.dirname(save_path) or ".", exist_ok=True)
        fig.savefig(save_path, dpi=dpi, bbox_inches="tight", transparent=True)

    if show_plot:
        plt.show()
    else:
        plt.close(fig)

    selected_cells = (
        contour_df[group_col].tolist() if group_col in contour_df.columns else list(range(n))
    )
    lookup_cols = ["_gallery_number"]
    for col in ["foldername", group_col]:
        if col in contour_df.columns and col not in lookup_cols:
            lookup_cols.append(col)
    cell_lookup_df = contour_df[lookup_cols].rename(
        columns={"_gallery_number": "gallery_number"}
    )
    return {
        "fig": fig,
        "axes": axes,
        "contour_df": contour_df,
        "selected_cells": selected_cells,
        "cell_lookup_df": cell_lookup_df,
    }


def _normalize_raw_image(image, contrast_limits=None, invert_image=False):
    image = image.astype(float, copy=False)
    if contrast_limits is None:
        lower = np.nanmin(image)
        upper = np.nanmax(image)
    else:
        lower, upper = contrast_limits
    if upper <= lower:
        norm = np.zeros_like(image, dtype=float)
    else:
        norm = np.clip((image - lower) / (upper - lower), 0, 1)
    if invert_image:
        norm = 1 - norm
    return norm


def plot_raw_projection_with_contours(
    single_cell_df,
    *,
    raw_movie_path=None,
    master_dir=None,
    frame_range=None,
    projection="sum",
    contour_methods=("radial", "legacy_outer_envelope"),
    coordinate_units="pixels",
    raw_contrast_limits=None,
    invert_raw=False,
    raw_cmap="gray",
    raw_lut=None,
    contour_colors=None,
    edge_angle_bins=180,
    edge_padding=0.05,
    edge_smoothing=0.1,
    minimal_bridge_point_radius=2.0,
    minimal_bridge_width=1.5,
    minimal_bridge_mask_padding=12,
    figsize=(4, 4),
    dpi=200,
    save_path=None,
    show_plot=True,
):
    """
    Plot a raw-frame projection with one or more contour methods overlaid.

    This is a QC helper for asking whether the computed contour encloses the
    visible cell/movie field well. ``projection='sum'`` is usually best for seeing
    all raw signal over the clip.
    """
    raw_movie_path = raw_movie_path or _resolve_raw_movie_path(
        single_cell_df, master_dir=master_dir
    )
    image = load_image(raw_movie_path)
    if frame_range is not None:
        frame_start, frame_end = map(int, frame_range)
        image = image[frame_start : frame_end + 1]

    if projection == "sum":
        raw = image.sum(axis=0)
    elif projection == "max":
        raw = image.max(axis=0)
    elif projection == "mean":
        raw = image.mean(axis=0)
    else:
        raise ValueError("projection must be 'sum', 'max', or 'mean'")

    raw = _normalize_raw_image(
        raw, contrast_limits=raw_contrast_limits, invert_image=invert_raw
    )

    if contour_colors is None:
        contour_colors = {
            "radial": "cyan",
            "legacy_outer_envelope": "magenta",
        }

    fig, ax = plt.subplots(figsize=figsize, dpi=dpi)
    ax.imshow(
        raw,
        cmap=_coerce_lut_colormap(raw_lut, target="matplotlib", fallback=raw_cmap),
        origin="upper",
    )

    contours = {}
    for method in contour_methods:
        contour = compute_fixed_cell_contour(
            single_cell_df,
            coordinate_units=coordinate_units,
            contour_method=method,
            edge_angle_bins=edge_angle_bins,
            edge_padding=edge_padding,
            edge_smoothing=edge_smoothing,
            minimal_bridge_point_radius=minimal_bridge_point_radius,
            minimal_bridge_width=minimal_bridge_width,
            minimal_bridge_mask_padding=minimal_bridge_mask_padding,
        )
        contours[method] = contour
        ax.plot(
            contour[:, 0],
            contour[:, 1],
            color=contour_colors.get(method, "yellow")
            if isinstance(contour_colors, dict)
            else None,
            lw=1.2,
            label=method,
        )

    ax.set_aspect("equal", adjustable="box")
    ax.axis("off")
    ax.legend(loc="upper right", fontsize=7)

    if save_path is not None:
        os.makedirs(os.path.dirname(save_path) or ".", exist_ok=True)
        fig.savefig(save_path, dpi=dpi, bbox_inches="tight", transparent=True)

    if show_plot:
        plt.show()
    else:
        plt.close(fig)

    return {
        "fig": fig,
        "ax": ax,
        "raw_movie_path": raw_movie_path,
        "projection": projection,
        "contours": contours,
    }


def plot_tracks_with_contours_qc(
    single_cell_df,
    tracks_to_plot_df=None,
    *,
    frame_range=None,
    contour_methods=("radial", "legacy_outer_envelope"),
    coordinate_units="pixels",
    x_col=None,
    y_col=None,
    track_id_col="unique_id",
    frame_col="frame",
    track_color_mode=None,
    track_color="0.45",
    color_by=None,
    colorway="tab20",
    track_line_width=0.35,
    track_alpha=0.35,
    contour_colors=None,
    contour_line_width=1.2,
    contour_line_style="-",
    edge_angle_bins=180,
    edge_padding=0.05,
    edge_smoothing=0.1,
    minimal_bridge_point_radius=2.0,
    minimal_bridge_width=1.5,
    minimal_bridge_mask_padding=12,
    figsize=(4, 4),
    dpi=200,
    save_path=None,
    show_plot=True,
):
    """
    Plot tracks only, with contour methods overlaid for QC.

    This gives a raw-free check of whether the contour encloses the full spatial
    footprint of the tracked particles.
    """
    source_df = tracks_to_plot_df if tracks_to_plot_df is not None else single_cell_df
    df = _as_pandas_copy(source_df)
    contour_source = _as_pandas_copy(single_cell_df)

    if x_col is None:
        x_col = "x" if coordinate_units == "pixels" else "x_um"
    if y_col is None:
        y_col = "y" if coordinate_units == "pixels" else "y_um"
    for col in [x_col, y_col, track_id_col, frame_col]:
        if col not in df.columns:
            raise ValueError(f"Column {col!r} not found")

    if frame_range is not None:
        frame_start, frame_end = map(int, frame_range)
        df = df[(df[frame_col] >= frame_start) & (df[frame_col] <= frame_end)]
    if df.empty:
        raise ValueError("No tracks available for contour QC")

    if contour_colors is None:
        contour_colors = {
            "radial": "cyan",
            "legacy_outer_envelope": "magenta",
        }

    resolved_track_color_mode = track_color_mode
    if resolved_track_color_mode is None:
        resolved_track_color_mode = (
            "by_column" if color_by is not None and color_by in df.columns else "single"
        )

    if resolved_track_color_mode == "single":
        track_colors = None
    elif resolved_track_color_mode == "by_column" and color_by in df.columns:
        track_colors = _track_color_map(df, track_id_col, color_by, colorway)
    elif resolved_track_color_mode == "by_track":
        track_colors = _track_color_map(df, track_id_col, track_id_col, colorway)
    else:
        raise ValueError(
            "track_color_mode must be 'single', 'by_track', or 'by_column' "
            "with a valid color_by column"
        )

    fig, ax = plt.subplots(figsize=figsize, dpi=dpi)
    segments = []
    colors = []
    for track_id, track in df.sort_values(frame_col).groupby(track_id_col):
        if len(track) < 2:
            continue
        segments.append(track[[x_col, y_col]].to_numpy())
        colors.append(track_colors.get(track_id, track_color) if track_colors else track_color)
    if segments:
        ax.add_collection(
            LineCollection(
                segments,
                colors=colors,
                linewidths=track_line_width,
                alpha=track_alpha,
            )
        )

    contours = {}
    for method in contour_methods:
        contour = compute_fixed_cell_contour(
            contour_source,
            coordinate_units=coordinate_units,
            x_col=x_col if x_col in contour_source.columns else None,
            y_col=y_col if y_col in contour_source.columns else None,
            contour_method=method,
            edge_angle_bins=edge_angle_bins,
            edge_padding=edge_padding,
            edge_smoothing=edge_smoothing,
            minimal_bridge_point_radius=minimal_bridge_point_radius,
            minimal_bridge_width=minimal_bridge_width,
            minimal_bridge_mask_padding=minimal_bridge_mask_padding,
        )
        contours[method] = contour
        ax.plot(
            contour[:, 0],
            contour[:, 1],
            color=contour_colors.get(method, "yellow")
            if isinstance(contour_colors, dict)
            else None,
            lw=contour_line_width,
            linestyle=contour_line_style,
            label=method,
        )

    ax.set_aspect("equal", adjustable="box")
    if coordinate_units == "pixels":
        ax.invert_yaxis()
    ax.axis("off")
    ax.legend(loc="upper right", fontsize=7)

    if save_path is not None:
        os.makedirs(os.path.dirname(save_path) or ".", exist_ok=True)
        fig.savefig(save_path, dpi=dpi, bbox_inches="tight", transparent=True)

    if show_plot:
        plt.show()
    else:
        plt.close(fig)

    return {
        "fig": fig,
        "ax": ax,
        "contours": contours,
        "n_tracks": int(df[track_id_col].nunique()),
        "frame_range": frame_range,
    }


def make_raw_track_napari_movie(
    single_cell_df,
    tracks_to_plot_df,
    *,
    frame_range,
    master_dir=None,
    contour_df=None,
    raw_movie_path=None,
    track_id_col="unique_id",
    frame_col="frame",
    x_col="x",
    y_col="y",
    color_by="unique_id",
    tail_length=60,
    tail_width=2,
    contour_color="cyan",
    contour_width=2,
    raw_contrast_limits=None,
    invert_raw=False,
    raw_colormap="gray",
    raw_lut=None,
    raw_frame_offset=0,
    spatial_transform="identity",
    save_path=None,
    fps=100,
    steps=None,
    run_napari=True,
    close_after_save=False,
    background="dark",
    show_time_label=True,
    frame_interval=config.TIME_BETWEEN_FRAMES,
    time_label_position=(10, 10),
    time_label_size=14,
    time_label_color="white",
    show_scale_bar=True,
    scale_bar_length_um=5.0,
    pixel_size_um=config.PIXELSIZE_MICRONS,
    scale_bar_position="lower_right",
    scale_bar_margin_px=12,
    scale_bar_line_width=4,
    scale_bar_color="white",
    scale_bar_label=None,
    scale_bar_label_size=12,
):
    """
    Show/save a napari movie of raw cell frames, selected tracks, and a fixed contour.
    """
    cell_pdf = _as_pandas_copy(single_cell_df)
    tracks = _as_pandas_copy(tracks_to_plot_df)
    for col in [track_id_col, frame_col, x_col, y_col]:
        if col not in tracks.columns:
            raise ValueError(f"Column {col!r} not found in tracks_to_plot_df")

    frame_start, frame_end = map(int, frame_range)
    tracks = tracks[
        (tracks[frame_col] >= frame_start) & (tracks[frame_col] <= frame_end)
    ].copy()
    if tracks.empty:
        raise ValueError("No selected tracks are present in frame_range")

    raw_movie_path = raw_movie_path or _resolve_raw_movie_path(cell_pdf, master_dir=master_dir)
    raw_frame_start = frame_start + int(raw_frame_offset)
    raw_frame_end = frame_end + int(raw_frame_offset)
    if raw_frame_start < 0:
        raise ValueError("raw_frame_offset makes the first requested raw frame negative")
    image = _load_raw_frame_range(raw_movie_path, raw_frame_start, raw_frame_end)
    if invert_raw:
        image = np.nanmax(image) - image

    track_ids = list(pd.unique(tracks[track_id_col]))
    track_id_map = {track_id: i for i, track_id in enumerate(track_ids)}
    tracks["_napari_track_id"] = tracks[track_id_col].map(track_id_map)
    tracks["_relative_frame"] = tracks[frame_col].astype(int) - frame_start
    height, width = image.shape[-2:]
    transformed_x, transformed_y = _transform_xy_for_raw_alignment(
        tracks[x_col].to_numpy(),
        tracks[y_col].to_numpy(),
        width,
        height,
        spatial_transform,
    )
    tracks["_display_x"] = transformed_x
    tracks["_display_y"] = transformed_y
    tracks_new_df = tracks[["_napari_track_id", "_relative_frame", "_display_y", "_display_x"]].copy()
    tracks_new_df.columns = ["track_id", "frame", "y", "x"]

    features_dict = {track_id_col: tracks[track_id_col].to_numpy()}
    color_feature = track_id_col
    if color_by in tracks.columns:
        color_feature = color_by
        if pd.api.types.is_numeric_dtype(tracks[color_by]):
            features_dict[color_by] = tracks[color_by].to_numpy()
        else:
            categories = {v: i for i, v in enumerate(pd.unique(tracks[color_by]))}
            mapped_col = f"{color_by}_numeric"
            tracks[mapped_col] = tracks[color_by].map(categories)
            features_dict[mapped_col] = tracks[mapped_col].to_numpy()
            color_feature = mapped_col

    viewer = napari.Viewer()
    viewer.theme = "light" if background == "light" else "dark"
    viewer.dims.axis_labels = ("time", "y", "x")
    viewer.add_image(
        image,
        name="Raw movie",
        contrast_limits=raw_contrast_limits,
        colormap=_coerce_lut_colormap(raw_lut, target="napari", fallback=raw_colormap),
    )

    viewer.add_tracks(
        tracks_new_df.to_numpy(),
        features=features_dict,
        name="Selected tracks",
        color_by=color_feature,
        tail_length=tail_length,
        tail_width=tail_width,
    )

    contour_source = contour_df if contour_df is not None else single_cell_df
    contour = get_contour_array(contour_source, coordinate_units="pixels")
    contour_x, contour_y = _transform_xy_for_raw_alignment(
        contour[:, 0],
        contour[:, 1],
        width,
        height,
        spatial_transform,
    )
    contour_yx = np.column_stack([contour_y, contour_x])
    viewer.add_shapes(
        [contour_yx],
        shape_type="polygon",
        name="Fixed cell contour",
        edge_color=contour_color,
        face_color="transparent",
        edge_width=contour_width,
    )

    if show_scale_bar and scale_bar_length_um is not None and pixel_size_um:
        scale_bar_length_px = float(scale_bar_length_um) / float(pixel_size_um)
        margin = float(scale_bar_margin_px)
        if scale_bar_position == "lower_left":
            x0 = margin
            x1 = x0 + scale_bar_length_px
            y = height - margin
        elif scale_bar_position == "upper_left":
            x0 = margin
            x1 = x0 + scale_bar_length_px
            y = margin
        elif scale_bar_position == "upper_right":
            x1 = width - margin
            x0 = x1 - scale_bar_length_px
            y = margin
        else:
            x1 = width - margin
            x0 = x1 - scale_bar_length_px
            y = height - margin
        viewer.add_shapes(
            [np.array([[y, x0], [y, x1]], dtype=float)],
            shape_type="line",
            name="Scale bar",
            edge_color=scale_bar_color,
            edge_width=scale_bar_line_width,
        )
        label = scale_bar_label or f"{scale_bar_length_um:g} um"
        viewer.add_points(
            np.array([[y - 10, (x0 + x1) / 2]], dtype=float),
            name="Scale bar label",
            size=0.1,
            face_color=scale_bar_color,
            opacity=1.0,
            text={
                "string": [label],
                "size": scale_bar_label_size,
                "color": scale_bar_color,
                "anchor": "center",
            },
        )

    if show_time_label:
        relative_frames = np.arange(frame_end - frame_start + 1, dtype=int)
        time_points = np.column_stack(
            [
                relative_frames,
                np.full_like(relative_frames, float(time_label_position[0]), dtype=float),
                np.full_like(relative_frames, float(time_label_position[1]), dtype=float),
            ]
        )
        time_labels = [
            f"{(frame_start + int(frame)) * float(frame_interval):.2f} s"
            for frame in relative_frames
        ]
        viewer.add_points(
            time_points,
            name="Time label",
            size=0.1,
            face_color=time_label_color,
            opacity=1.0,
            text={
                "string": time_labels,
                "size": time_label_size,
                "color": time_label_color,
                "anchor": "upper_left",
            },
        )

    if save_path is not None:
        os.makedirs(os.path.dirname(save_path) or ".", exist_ok=True)
        save_movie(
            viewer,
            tracks_new_df,
            save_path=save_path,
            steps=steps,
            fps=fps,
        )
        if close_after_save and not run_napari:
            viewer.close()

    if run_napari:
        napari.run()

    return {
        "viewer": viewer,
        "raw_movie_path": raw_movie_path,
        "frame_range": (frame_start, frame_end),
        "raw_frame_range": (raw_frame_start, raw_frame_end),
        "spatial_transform": spatial_transform,
        "n_tracks": len(track_ids),
        "contour": contour,
    }


def _track_color_map(df, track_id_col, color_by, colorway):
    track_ids = list(pd.unique(df[track_id_col]))
    if color_by in df.columns and color_by != track_id_col:
        values = df.groupby(track_id_col)[color_by].first()
    else:
        values = pd.Series(track_ids, index=track_ids)

    if pd.api.types.is_numeric_dtype(values):
        vmin, vmax = float(values.min()), float(values.max())
        norm = Normalize(vmin=vmin, vmax=vmax if vmax > vmin else vmin + 1)
        cmap = ListedColormap(colorway) if isinstance(colorway, (list, tuple)) else plt.get_cmap(colorway)
        return {track_id: cmap(norm(values.loc[track_id])) for track_id in track_ids}

    categories = list(pd.unique(values))
    if isinstance(colorway, (list, tuple)):
        cmap = ListedColormap(colorway)
    else:
        cmap = plt.get_cmap(colorway, max(len(categories), 1))
    category_colors = {cat: cmap(i) for i, cat in enumerate(categories)}
    return {track_id: category_colors[values.loc[track_id]] for track_id in track_ids}


def _load_raw_frame_indices(raw_movie_path, frame_indices):
    """
    Load only requested frames for TIFF stacks when possible.

    Falls back to the project ``load_image`` helper for formats/readers that do
    not support partial TIFF reads.
    """
    frame_indices = np.asarray(frame_indices, dtype=int)
    if frame_indices.size == 0:
        raise ValueError("No frame indices requested")
    try:
        import tifffile

        with tifffile.TiffFile(raw_movie_path) as tif:
            image = tif.asarray(key=frame_indices.tolist())
    except Exception:
        full_image = load_image(raw_movie_path)
        image = full_image[frame_indices]

    image = np.asarray(image)
    if image.ndim == 2 and frame_indices.size > 1:
        image = image[np.newaxis, ...]
    return image


def _load_raw_frame_range(raw_movie_path, frame_start, frame_end):
    """
    Load only the requested contiguous frame range for TIFF stacks when possible.
    """
    return _load_raw_frame_indices(
        raw_movie_path,
        np.arange(int(frame_start), int(frame_end) + 1),
    )


def save_raw_track_timelapse_stills(
    single_cell_df,
    tracks_to_plot_df,
    *,
    frame_range,
    output_dir,
    master_dir=None,
    contour_df=None,
    raw_movie_path=None,
    raw_mode="final_frame",
    still_step_frames=60,
    track_history="cumulative",
    track_id_col="unique_id",
    frame_col="frame",
    x_col="x",
    y_col="y",
    track_color_mode="by_track",
    track_color="yellow",
    color_by="unique_id",
    colorway="tab20",
    contour_color="cyan",
    contour_line_width=1.0,
    track_line_width=0.8,
    head_size=8,
    raw_cmap="gray",
    raw_lut=None,
    raw_frame_offset=0,
    spatial_transform="identity",
    contrast_limits=None,
    invert_image=False,
    figsize=(3, 3),
    dpi=200,
    output_format="png",
    output_prefix=None,
    show_time_label=True,
    frame_interval=config.TIME_BETWEEN_FRAMES,
    show_scale_bar=True,
    scale_bar_length_um=5.0,
    pixel_size_um=config.PIXELSIZE_MICRONS,
    scale_bar_position="lower_right",
    scale_bar_margin_px=12,
    scale_bar_line_width=3,
    scale_bar_color="white",
    scale_bar_label=None,
    scale_bar_fontsize=8,
):
    """
    Save publication-style PNG stills from raw cell frames and selected tracks.

    ``raw_mode='sum_window'`` sums the raw frames in each output window. 
    ``raw_mode='final_frame'`` uses only the last raw frame of each output window.
    Tracks can be cumulative from the start of ``frame_range`` or limited to the
    current window via ``track_history='window'``.
    """
    if raw_mode not in {"final_frame", "sum_window"}:
        raise ValueError("raw_mode must be 'final_frame' or 'sum_window'")
    if track_history not in {"cumulative", "window"}:
        raise ValueError("track_history must be 'cumulative' or 'window'")
    output_format = str(output_format).lower().lstrip(".")
    if output_format not in {"png", "svg"}:
        raise ValueError("output_format must be 'png' or 'svg'")
    if track_color_mode not in {"single", "by_track", "by_column"}:
        raise ValueError("track_color_mode must be 'single', 'by_track', or 'by_column'")

    tracks = _as_pandas_copy(tracks_to_plot_df)
    for col in [track_id_col, frame_col, x_col, y_col]:
        if col not in tracks.columns:
            raise ValueError(f"Column {col!r} not found in tracks_to_plot_df")

    frame_start, frame_end = map(int, frame_range)
    raw_movie_path = raw_movie_path or _resolve_raw_movie_path(
        single_cell_df, master_dir=master_dir
    )
    image = load_image(raw_movie_path)
    height, width = image.shape[-2:]

    os.makedirs(output_dir, exist_ok=True)
    if output_prefix is None:
        filename = _single_value_from_df(_as_pandas_copy(single_cell_df), "filename", "cell")
        output_prefix = str(filename).replace("_tracked", "")

    if still_step_frames is None:
        windows = [(frame, frame) for frame in range(frame_start, frame_end + 1)]
    else:
        still_step_frames = int(still_step_frames)
        if still_step_frames <= 0:
            raise ValueError("still_step_frames must be positive or None")
        windows = []
        current = frame_start
        while current <= frame_end:
            window_end = min(frame_end, current + still_step_frames - 1)
            windows.append((current, window_end))
            current = window_end + 1

    tracks = tracks[
        (tracks[frame_col] >= frame_start) & (tracks[frame_col] <= frame_end)
    ].copy()
    if tracks.empty:
        raise ValueError("No selected tracks are present in frame_range")

    if track_color_mode == "single":
        color_map = {track_id: track_color for track_id in pd.unique(tracks[track_id_col])}
    elif track_color_mode == "by_column":
        if color_by not in tracks.columns:
            raise ValueError(f"Column {color_by!r} not found for track_color_mode='by_column'")
        color_map = _track_color_map(tracks, track_id_col, color_by, colorway)
    else:
        color_map = _track_color_map(tracks, track_id_col, track_id_col, colorway)
    contour_source = contour_df if contour_df is not None else single_cell_df
    contour = get_contour_array(contour_source, coordinate_units="pixels")

    output_paths = []
    for i, (window_start, window_end) in enumerate(windows):
        if raw_mode == "sum_window":
            raw_start = window_start + int(raw_frame_offset)
            raw_end = window_end + int(raw_frame_offset)
            if raw_start < 0:
                raise ValueError("raw_frame_offset makes a requested raw frame negative")
            raw = image[raw_start : raw_end + 1].sum(axis=0)
        else:
            raw_index = window_end + int(raw_frame_offset)
            if raw_index < 0:
                raise ValueError("raw_frame_offset makes a requested raw frame negative")
            raw = image[raw_index]
        raw = _normalize_raw_image(raw, contrast_limits=contrast_limits, invert_image=invert_image)

        fig, ax = plt.subplots(figsize=figsize, dpi=dpi)
        ax.imshow(
            raw,
            cmap=_coerce_lut_colormap(raw_lut, target="matplotlib", fallback=raw_cmap),
            origin="upper",
        )
        contour_x, contour_y = _transform_xy_for_raw_alignment(
            contour[:, 0],
            contour[:, 1],
            width,
            height,
            spatial_transform,
        )
        ax.plot(
            contour_x,
            contour_y,
            color=contour_color,
            lw=contour_line_width,
            alpha=0.95,
        )

        if track_history == "cumulative":
            plot_start = frame_start
        else:
            plot_start = window_start
        visible_tracks = tracks[
            (tracks[frame_col] >= plot_start) & (tracks[frame_col] <= window_end)
        ]

        for track_id, track in visible_tracks.sort_values(frame_col).groupby(track_id_col):
            if len(track) >= 2:
                tx, ty = _transform_xy_for_raw_alignment(
                    track[x_col].to_numpy(),
                    track[y_col].to_numpy(),
                    width,
                    height,
                    spatial_transform,
                )
                ax.plot(
                    tx,
                    ty,
                    color=color_map.get(track_id, "yellow"),
                    lw=track_line_width,
                    alpha=0.9,
                )
            current = track[track[frame_col] <= window_end].tail(1)
            if not current.empty:
                cx, cy = _transform_xy_for_raw_alignment(
                    current[x_col].to_numpy(),
                    current[y_col].to_numpy(),
                    width,
                    height,
                    spatial_transform,
                )
                ax.scatter(
                    cx,
                    cy,
                    color=color_map.get(track_id, "yellow"),
                    s=head_size,
                    edgecolors="none",
                    alpha=1.0,
                )

        ax.set_xlim(0, width)
        ax.set_ylim(height, 0)
        ax.set_aspect("equal", adjustable="box")
        ax.axis("off")

        if show_time_label:
            t0 = window_start * frame_interval
            t1 = window_end * frame_interval
            ax.text(
                0.02,
                0.04,
                f"{t0:.2f}-{t1:.2f} s",
                transform=ax.transAxes,
                color="white" if not invert_image else "black",
                fontsize=8,
                ha="left",
                va="bottom",
            )

        if show_scale_bar and scale_bar_length_um is not None and pixel_size_um:
            scale_bar_length_px = float(scale_bar_length_um) / float(pixel_size_um)
            margin = float(scale_bar_margin_px)
            if scale_bar_position == "lower_left":
                x0 = margin
                x1 = x0 + scale_bar_length_px
                y = height - margin
                text_y = y - 6
                va = "bottom"
            elif scale_bar_position == "upper_left":
                x0 = margin
                x1 = x0 + scale_bar_length_px
                y = margin
                text_y = y + 6
                va = "top"
            elif scale_bar_position == "upper_right":
                x1 = width - margin
                x0 = x1 - scale_bar_length_px
                y = margin
                text_y = y + 6
                va = "top"
            else:
                x1 = width - margin
                x0 = x1 - scale_bar_length_px
                y = height - margin
                text_y = y - 6
                va = "bottom"
            ax.plot(
                [x0, x1],
                [y, y],
                color=scale_bar_color,
                lw=scale_bar_line_width,
                solid_capstyle="butt",
            )
            ax.text(
                (x0 + x1) / 2,
                text_y,
                scale_bar_label or f"{scale_bar_length_um:g} um",
                color=scale_bar_color,
                fontsize=scale_bar_fontsize,
                ha="center",
                va=va,
            )

        out_path = os.path.join(
            output_dir,
            f"{output_prefix}_{raw_mode}_{i:03d}_frames_{window_start:05d}_{window_end:05d}.{output_format}",
        )
        fig.savefig(out_path, dpi=dpi, bbox_inches="tight", pad_inches=0, format=output_format)
        plt.close(fig)
        output_paths.append(out_path)

    return {
        "output_paths": output_paths,
        "raw_movie_path": raw_movie_path,
        "frame_range": (frame_start, frame_end),
        "n_stills": len(output_paths),
        "raw_mode": raw_mode,
        "track_history": track_history,
        "output_format": output_format,
        "contour": contour,
        "raw_frame_offset": raw_frame_offset,
        "spatial_transform": spatial_transform,
    }


def _transform_xy_for_raw_alignment(x, y, width, height, transform="identity"):
    """Transform x/y display coordinates for raw-image alignment diagnostics."""
    x = np.asarray(x, dtype=float)
    y = np.asarray(y, dtype=float)
    if transform in {None, "identity"}:
        return x, y
    if transform == "flip_x":
        return width - 1 - x, y
    if transform == "flip_y":
        return x, height - 1 - y
    if transform == "flip_xy":
        return width - 1 - x, height - 1 - y
    if transform == "transpose":
        return y, x
    if transform == "transpose_flip_x":
        return height - 1 - y, x
    if transform == "transpose_flip_y":
        return y, width - 1 - x
    if transform == "transpose_flip_xy":
        return height - 1 - y, width - 1 - x
    raise ValueError(
        "transform must be one of identity, flip_x, flip_y, flip_xy, "
        "transpose, transpose_flip_x, transpose_flip_y, transpose_flip_xy"
    )


def plot_raw_track_alignment_diagnostics(
    single_cell_df,
    tracks_to_plot_df,
    *,
    contour_df=None,
    frame=None,
    frame_range=None,
    raw_frame_offset=0,
    projection_half_window=0,
    master_dir=None,
    raw_movie_path=None,
    x_col="x",
    y_col="y",
    track_id_col="unique_id",
    frame_col="frame",
    transforms=("identity", "flip_x", "flip_y", "flip_xy", "transpose", "transpose_flip_xy"),
    raw_cmap="gray",
    raw_lut=None,
    contrast_limits=None,
    invert_raw=False,
    point_size=8,
    track_line_width=0.8,
    contour_line_width=1.4,
    figsize_per_panel=(3, 3),
    dpi=140,
):
    """
    Plot raw frame/projection with selected tracks under several spatial transforms.

    Use this to diagnose whether track coordinates line up with the raw movie, and
    whether a raw frame offset is needed. Track frame numbers are not modified;
    ``raw_frame_offset`` only changes which raw frame is displayed underneath.
    """
    cell_pdf = _as_pandas_copy(single_cell_df)
    tracks = _as_pandas_copy(tracks_to_plot_df)
    for col in [x_col, y_col, frame_col, track_id_col]:
        if col not in tracks.columns:
            raise ValueError(f"Column {col!r} not found in tracks_to_plot_df")

    if frame is None:
        if frame_range is not None:
            frame = int(round((int(frame_range[0]) + int(frame_range[1])) / 2))
        else:
            frame = int(round(float(tracks[frame_col].median())))
    frame = int(frame)
    raw_center_frame = int(frame + raw_frame_offset)
    raw_frame_start = max(0, raw_center_frame - int(projection_half_window))
    raw_frame_end = max(raw_frame_start, raw_center_frame + int(projection_half_window))

    raw_movie_path = raw_movie_path or _resolve_raw_movie_path(cell_pdf, master_dir=master_dir)
    raw_stack = _load_raw_frame_indices(raw_movie_path, np.arange(raw_frame_start, raw_frame_end + 1))
    if raw_stack.ndim == 2:
        raw_image = raw_stack
    elif projection_half_window > 0:
        raw_image = np.nanmax(raw_stack, axis=0)
    else:
        raw_image = raw_stack[0]
    if invert_raw:
        raw_image = np.nanmax(raw_image) - raw_image
    raw_image = _normalize_raw_image(
        raw_image, contrast_limits=contrast_limits, invert_image=False
    )
    height, width = raw_image.shape[-2:]

    if frame_range is not None:
        frame_start, frame_end = map(int, frame_range)
        track_history = tracks[
            (tracks[frame_col] >= frame_start) & (tracks[frame_col] <= frame)
        ].copy()
    else:
        track_history = tracks[tracks[frame_col] <= frame].copy()
    current_points = tracks[tracks[frame_col] == frame].copy()
    if current_points.empty:
        current_points = (
            tracks[tracks[frame_col] <= frame]
            .sort_values(frame_col)
            .groupby(track_id_col)
            .tail(1)
        )

    contour = None
    if contour_df is not None:
        contour = get_contour_array(contour_df, coordinate_units="pixels")

    transforms = list(transforms)
    n_cols = min(3, max(1, len(transforms)))
    n_rows = int(math.ceil(len(transforms) / n_cols))
    fig, axes = plt.subplots(
        n_rows,
        n_cols,
        figsize=(figsize_per_panel[0] * n_cols, figsize_per_panel[1] * n_rows),
        squeeze=False,
        dpi=dpi,
    )
    cmap = _coerce_lut_colormap(raw_lut, target="matplotlib", fallback=raw_cmap)

    for ax, transform in zip(axes.ravel(), transforms):
        ax.imshow(raw_image, cmap=cmap, origin="upper")
        for _, track in track_history.sort_values(frame_col).groupby(track_id_col):
            if len(track) < 2:
                continue
            tx, ty = _transform_xy_for_raw_alignment(
                track[x_col].to_numpy(), track[y_col].to_numpy(), width, height, transform
            )
            ax.plot(tx, ty, color="orange", lw=track_line_width, alpha=0.75)
        if not current_points.empty:
            px, py = _transform_xy_for_raw_alignment(
                current_points[x_col].to_numpy(),
                current_points[y_col].to_numpy(),
                width,
                height,
                transform,
            )
            ax.scatter(px, py, s=point_size, color="cyan", edgecolors="none", alpha=0.9)
        if contour is not None:
            cx, cy = _transform_xy_for_raw_alignment(
                contour[:, 0], contour[:, 1], width, height, transform
            )
            ax.plot(cx, cy, color="red", lw=contour_line_width, ls="--", alpha=0.9)
        ax.set_xlim(0, width)
        ax.set_ylim(height, 0)
        ax.set_aspect("equal", adjustable="box")
        ax.axis("off")
        ax.set_title(transform, fontsize=8)

    for ax in axes.ravel()[len(transforms):]:
        ax.axis("off")

    title = (
        f"track frame={frame}, raw frame={raw_center_frame}, "
        f"raw projection={raw_frame_start}-{raw_frame_end}"
    )
    fig.suptitle(title, fontsize=9)
    plt.tight_layout()
    return {
        "fig": fig,
        "axes": axes,
        "raw_movie_path": raw_movie_path,
        "track_frame": frame,
        "raw_center_frame": raw_center_frame,
        "raw_frame_range": (raw_frame_start, raw_frame_end),
        "image_shape": raw_image.shape,
        "track_xy_range": {
            "x_min": float(tracks[x_col].min()),
            "x_max": float(tracks[x_col].max()),
            "y_min": float(tracks[y_col].min()),
            "y_max": float(tracks[y_col].max()),
        },
    }


def _sample_local_raw_values(image, x, y, *, radius=1):
    """Sample max raw intensity in a small square around each x/y point."""
    image = np.asarray(image, dtype=float)
    height, width = image.shape[-2:]
    x = np.asarray(x, dtype=float)
    y = np.asarray(y, dtype=float)
    valid = np.isfinite(x) & np.isfinite(y)
    xi = np.round(x[valid]).astype(int)
    yi = np.round(y[valid]).astype(int)
    in_bounds = (xi >= 0) & (xi < width) & (yi >= 0) & (yi < height)
    xi = xi[in_bounds]
    yi = yi[in_bounds]
    values = []
    radius = int(max(0, radius))
    for px, py in zip(xi, yi):
        y0 = max(0, py - radius)
        y1 = min(height, py + radius + 1)
        x0 = max(0, px - radius)
        x1 = min(width, px + radius + 1)
        values.append(float(np.nanmax(image[y0:y1, x0:x1])))
    return np.asarray(values, dtype=float), int(np.count_nonzero(in_bounds)), int(len(valid))


def quantify_raw_track_alignment(
    single_cell_df,
    tracks_to_plot_df,
    *,
    frame_range,
    raw_frame_offsets=(0,),
    transforms=("identity", "flip_x", "flip_y", "flip_xy"),
    master_dir=None,
    raw_movie_path=None,
    x_col="x",
    y_col="y",
    track_id_col="unique_id",
    frame_col="frame",
    sample_n_frames=12,
    max_points_per_frame=200,
    local_radius_px=1,
    random_multiplier=5,
    random_state=42,
    invert_raw=False,
    return_backend="polars",
):
    """
    Score raw/track alignment by raw intensity under track points.

    The best transform is the one where track positions land on brighter raw
    pixels than random in-frame positions most consistently.
    """
    cell_pdf = _as_pandas_copy(single_cell_df)
    tracks = _as_pandas_copy(tracks_to_plot_df)
    for col in [x_col, y_col, frame_col, track_id_col]:
        if col not in tracks.columns:
            raise ValueError(f"Column {col!r} not found in tracks_to_plot_df")

    frame_start, frame_end = map(int, frame_range)
    available_frames = np.array(
        sorted(
            tracks[
                (tracks[frame_col] >= frame_start) & (tracks[frame_col] <= frame_end)
            ][frame_col]
            .dropna()
            .astype(int)
            .unique()
        ),
        dtype=int,
    )
    if available_frames.size == 0:
        raise ValueError("No selected tracks are present in frame_range")
    if sample_n_frames is not None and available_frames.size > int(sample_n_frames):
        sample_idx = np.linspace(
            0, available_frames.size - 1, int(sample_n_frames), dtype=int
        )
        sampled_frames = available_frames[sample_idx]
    else:
        sampled_frames = available_frames

    raw_movie_path = raw_movie_path or _resolve_raw_movie_path(cell_pdf, master_dir=master_dir)
    rng = np.random.default_rng(random_state)
    rows = []

    for raw_frame_offset in raw_frame_offsets:
        raw_frames = sampled_frames + int(raw_frame_offset)
        if np.any(raw_frames < 0):
            continue
        raw_stack = _load_raw_frame_indices(raw_movie_path, raw_frames)
        if raw_stack.ndim == 2:
            raw_stack = raw_stack[np.newaxis, ...]

        for transform in transforms:
            point_values_all = []
            random_values_all = []
            total_in_bounds = 0
            total_points = 0

            for track_frame, raw_image in zip(sampled_frames, raw_stack):
                raw_image = np.asarray(raw_image, dtype=float)
                if invert_raw:
                    raw_image = np.nanmax(raw_image) - raw_image
                raw_min = np.nanpercentile(raw_image, 1)
                raw_max = np.nanpercentile(raw_image, 99.8)
                if raw_max > raw_min:
                    raw_norm = np.clip((raw_image - raw_min) / (raw_max - raw_min), 0, 1)
                else:
                    raw_norm = raw_image
                height, width = raw_norm.shape[-2:]

                frame_points = tracks[tracks[frame_col].astype(int) == int(track_frame)]
                if frame_points.empty:
                    continue
                if (
                    max_points_per_frame is not None
                    and len(frame_points) > int(max_points_per_frame)
                ):
                    frame_points = frame_points.sample(
                        n=int(max_points_per_frame), random_state=random_state
                    )

                x_t, y_t = _transform_xy_for_raw_alignment(
                    frame_points[x_col].to_numpy(),
                    frame_points[y_col].to_numpy(),
                    width,
                    height,
                    transform,
                )
                point_values, n_in_bounds, n_total = _sample_local_raw_values(
                    raw_norm, x_t, y_t, radius=local_radius_px
                )
                total_in_bounds += n_in_bounds
                total_points += n_total
                if point_values.size == 0:
                    continue
                point_values_all.append(point_values)

                n_random = max(1, int(point_values.size * int(random_multiplier)))
                random_x = rng.integers(0, width, size=n_random)
                random_y = rng.integers(0, height, size=n_random)
                random_values, _, _ = _sample_local_raw_values(
                    raw_norm, random_x, random_y, radius=local_radius_px
                )
                random_values_all.append(random_values)

            if point_values_all:
                point_values = np.concatenate(point_values_all)
                random_values = np.concatenate(random_values_all)
                point_mean = float(np.nanmean(point_values))
                random_mean = float(np.nanmean(random_values))
                random_std = float(np.nanstd(random_values))
                random_p95 = float(np.nanpercentile(random_values, 95))
                percentile = float(
                    np.mean(point_values[:, None] > random_values[None, :])
                )
                fraction_above_random_p95 = float(np.mean(point_values > random_p95))
                z = (
                    (point_mean - random_mean) / random_std
                    if random_std > 0
                    else np.nan
                )
                score = float(point_mean - random_mean)
                enrichment = float(point_mean / (random_mean + 1e-12))
                n_points = int(point_values.size)
            else:
                point_mean = random_mean = random_std = random_p95 = np.nan
                percentile = fraction_above_random_p95 = z = np.nan
                score = enrichment = np.nan
                n_points = 0

            rows.append(
                {
                    "transform": transform,
                    "raw_frame_offset": int(raw_frame_offset),
                    "score": score,
                    "enrichment": enrichment,
                    "point_mean": point_mean,
                    "random_mean": random_mean,
                    "point_percentile_vs_random": percentile,
                    "fraction_above_random_p95": fraction_above_random_p95,
                    "point_minus_random_z": z,
                    "in_bounds_fraction": (
                        float(total_in_bounds / total_points) if total_points else np.nan
                    ),
                    "n_frames": int(len(sampled_frames)),
                    "n_points": n_points,
                    "track_frame_min": int(np.min(sampled_frames)),
                    "track_frame_max": int(np.max(sampled_frames)),
                    "raw_frame_min": int(np.min(raw_frames)),
                    "raw_frame_max": int(np.max(raw_frames)),
                    "image_width": int(raw_stack.shape[-1]),
                    "image_height": int(raw_stack.shape[-2]),
                    "raw_movie_path": raw_movie_path,
                }
            )

    result = pd.DataFrame(rows).sort_values(
        ["score", "point_minus_random_z", "in_bounds_fraction"],
        ascending=[False, False, False],
    )
    if return_backend == "pandas":
        return result
    if return_backend == "polars":
        return pl.from_pandas(result)
    raise ValueError("return_backend must be 'polars' or 'pandas'")


def _crop_image_around_center(image, center_x, center_y, crop_width, crop_height, fill_value=0):
    """Crop image around center, padding outside the image with fill_value."""
    image = np.asarray(image)
    crop_width = int(max(1, round(crop_width)))
    crop_height = int(max(1, round(crop_height)))
    x0 = int(round(float(center_x) - crop_width / 2))
    y0 = int(round(float(center_y) - crop_height / 2))
    x1 = x0 + crop_width
    y1 = y0 + crop_height

    out = np.full((crop_height, crop_width), fill_value, dtype=image.dtype)
    src_x0 = max(0, x0)
    src_y0 = max(0, y0)
    src_x1 = min(image.shape[1], x1)
    src_y1 = min(image.shape[0], y1)
    if src_x1 > src_x0 and src_y1 > src_y0:
        dst_x0 = src_x0 - x0
        dst_y0 = src_y0 - y0
        out[
            dst_y0 : dst_y0 + (src_y1 - src_y0),
            dst_x0 : dst_x0 + (src_x1 - src_x0),
        ] = image[src_y0:src_y1, src_x0:src_x1]
    return out, x0, y0


def _select_track_ids_for_follow_view(
    tracks,
    *,
    track_id_col="unique_id",
    frame_col="frame",
    selection_mode="specified",
    track_ids=None,
    population_col=None,
    populations=None,
    n_tracks=1,
    random_state=42,
):
    """Select track IDs for follow/center single-molecule rendering."""
    if selection_mode == "specified":
        if track_ids is None:
            raise ValueError("track_ids is required when selection_mode='specified'")
        return list(track_ids)

    summary_source = tracks
    if selection_mode == "population":
        if population_col is None:
            raise ValueError("population_col is required when selection_mode='population'")
        if population_col not in tracks.columns:
            raise ValueError(f"Column {population_col!r} not found")
        if populations is None:
            raise ValueError("populations is required when selection_mode='population'")
        populations = [populations] if isinstance(populations, str) else list(populations)
        summary_source = tracks[tracks[population_col].isin(populations)].copy()
    elif selection_mode not in {"random", "all"}:
        raise ValueError("selection_mode must be 'specified', 'random', 'population', or 'all'")

    if summary_source.empty:
        raise ValueError("No tracks available after follow-view selection filters")

    summary = (
        summary_source.groupby(track_id_col)[frame_col]
        .agg(["count", "min", "max"])
        .reset_index()
    )
    summary["track_length_frames"] = summary["max"] - summary["min"] + 1
    summary = summary.sort_values(["track_length_frames", "count"], ascending=False)

    if selection_mode == "all":
        return summary[track_id_col].tolist()
    if selection_mode == "random":
        return (
            summary.sample(
                n=min(int(n_tracks), len(summary)), random_state=random_state
            )[track_id_col]
            .tolist()
        )
    return summary.head(int(n_tracks))[track_id_col].tolist()


def render_follow_track_views(
    single_cell_df,
    tracks_df,
    *,
    output_dir,
    frame_range,
    master_dir=None,
    raw_movie_path=None,
    render_outputs=("png",),
    view_mode="follow",
    track_selection_mode="specified",
    track_ids=None,
    population_col=None,
    populations=None,
    n_tracks=1,
    random_state=42,
    track_id_col="unique_id",
    frame_col="frame",
    x_col="x",
    y_col="y",
    spatial_transform="identity",
    raw_frame_offset=0,
    crop_size_px=None,
    min_crop_size_px=64,
    crop_padding_px=12,
    frame_step=1,
    raw_mode="final_frame",
    output_format="png",
    dpi=200,
    fps=20,
    raw_cmap="gray",
    raw_lut=None,
    contrast_limits=None,
    invert_raw=False,
    track_history="cumulative",
    history_length_frames=None,
    track_color="orange",
    track_line_width=1.0,
    head_color="cyan",
    head_size=10,
    show_time_label=True,
    frame_interval=config.TIME_BETWEEN_FRAMES,
    show_scale_bar=True,
    scale_bar_length_um=2.0,
    pixel_size_um=config.PIXELSIZE_MICRONS,
    scale_bar_position="lower_right",
    scale_bar_margin_px=8,
    scale_bar_line_width=2,
    scale_bar_color="white",
    scale_bar_label=None,
    scale_bar_fontsize=7,
    napari_tail_length=60,
    close_after_save=True,
):
    """
    Render per-track views that either follow a molecule or use one fixed crop.

    ``view_mode='follow'`` keeps the selected molecule centered in each output
    frame. ``view_mode='center'`` uses one fixed crop centered on the selected
    track centroid, padded around the track extent.

    ``render_outputs`` can include ``"png"`` and/or ``"napari"``. For SVG stills,
    set ``output_format='svg'``; the raw image remains raster inside the SVG while
    overlays remain vector.
    """
    if view_mode not in {"follow", "center"}:
        raise ValueError("view_mode must be 'follow' or 'center'")
    render_outputs = [render_outputs] if isinstance(render_outputs, str) else list(render_outputs)
    for output in render_outputs:
        if output not in {"png", "napari"}:
            raise ValueError("render_outputs entries must be 'png' or 'napari'")
    output_format = str(output_format).lower().lstrip(".")
    if output_format not in {"png", "svg"}:
        raise ValueError("output_format must be 'png' or 'svg'")
    if raw_mode not in {"final_frame", "sum_window"}:
        raise ValueError("raw_mode must be 'final_frame' or 'sum_window'")

    cell_pdf = _as_pandas_copy(single_cell_df)
    tracks = _as_pandas_copy(tracks_df)
    for col in [track_id_col, frame_col, x_col, y_col]:
        if col not in tracks.columns:
            raise ValueError(f"Column {col!r} not found in tracks_df")

    frame_start, frame_end = map(int, frame_range)
    tracks = tracks[
        (tracks[frame_col] >= frame_start) & (tracks[frame_col] <= frame_end)
    ].copy()
    if tracks.empty:
        raise ValueError("No tracks available in frame_range")

    raw_movie_path = raw_movie_path or _resolve_raw_movie_path(cell_pdf, master_dir=master_dir)
    output_dir = Path(output_dir)
    output_dir.mkdir(parents=True, exist_ok=True)

    resolved_track_color = track_color
    if isinstance(track_color, (list, tuple)):
        resolved_track_color = track_color[0] if len(track_color) else "orange"
    elif isinstance(track_color, str) and not is_color_like(track_color):
        try:
            resolved_track_color = plt.get_cmap(track_color)(0.15)
        except Exception:
            resolved_track_color = "orange"

    selected_ids = _select_track_ids_for_follow_view(
        tracks,
        track_id_col=track_id_col,
        frame_col=frame_col,
        selection_mode=track_selection_mode,
        track_ids=track_ids,
        population_col=population_col,
        populations=populations,
        n_tracks=n_tracks,
        random_state=random_state,
    )

    output_records = []
    cmap = _coerce_lut_colormap(raw_lut, target="matplotlib", fallback=raw_cmap)
    frame_step = max(1, int(frame_step))

    for track_id in selected_ids:
        track = tracks[tracks[track_id_col] == track_id].sort_values(frame_col).copy()
        if track.empty:
            continue

        track_frames = track[frame_col].astype(int).to_numpy()
        display_frames = np.arange(
            max(frame_start, int(track_frames.min())),
            min(frame_end, int(track_frames.max())) + 1,
            frame_step,
            dtype=int,
        )
        if display_frames.size == 0:
            continue

        raw_frames_needed = np.unique(display_frames + int(raw_frame_offset))
        if np.any(raw_frames_needed < 0):
            raise ValueError("raw_frame_offset makes a requested raw frame negative")
        raw_stack = _load_raw_frame_indices(raw_movie_path, raw_frames_needed)
        if raw_stack.ndim == 2:
            raw_stack = raw_stack[np.newaxis, ...]
        raw_by_frame = {int(frame): raw_stack[i] for i, frame in enumerate(raw_frames_needed)}
        height, width = raw_stack.shape[-2:]

        tx, ty = _transform_xy_for_raw_alignment(
            track[x_col].to_numpy(),
            track[y_col].to_numpy(),
            width,
            height,
            spatial_transform,
        )
        track = track.assign(_display_x=tx, _display_y=ty)
        interp_x = np.interp(display_frames, track_frames, tx)
        interp_y = np.interp(display_frames, track_frames, ty)

        if crop_size_px is None:
            track_width = float(np.nanmax(tx) - np.nanmin(tx))
            track_height = float(np.nanmax(ty) - np.nanmin(ty))
            auto_width = max(min_crop_size_px, int(np.ceil(track_width + 2 * crop_padding_px)))
            auto_height = max(min_crop_size_px, int(np.ceil(track_height + 2 * crop_padding_px)))
        elif isinstance(crop_size_px, (list, tuple)):
            auto_width, auto_height = map(int, crop_size_px)
        else:
            auto_width = auto_height = int(crop_size_px)

        if view_mode == "center":
            fixed_center_x = float(np.nanmean(tx))
            fixed_center_y = float(np.nanmean(ty))
            centers_x = np.full_like(display_frames, fixed_center_x, dtype=float)
            centers_y = np.full_like(display_frames, fixed_center_y, dtype=float)
        else:
            centers_x = interp_x
            centers_y = interp_y

        track_label = str(track_id).replace(os.sep, "_").replace(" ", "_")
        track_dir = output_dir / f"track_{track_label}_{view_mode}"
        png_dir = track_dir / f"{output_format}_frames"
        if "png" in render_outputs:
            png_dir.mkdir(parents=True, exist_ok=True)

        cropped_stack = []
        napari_rows = []
        origins = {}
        for idx, frame in enumerate(display_frames):
            raw_frame = int(frame + int(raw_frame_offset))
            raw = np.asarray(raw_by_frame[raw_frame])
            if raw_mode == "sum_window":
                # Sum from previous displayed frame to this frame for streak-style raw view.
                prior_frame = display_frames[max(0, idx - 1)]
                sum_frames = np.arange(prior_frame, frame + 1) + int(raw_frame_offset)
                sum_stack = _load_raw_frame_indices(raw_movie_path, sum_frames)
                raw = np.nansum(sum_stack, axis=0) if sum_stack.ndim == 3 else sum_stack
            if invert_raw:
                raw = np.nanmax(raw) - raw
            raw_norm = _normalize_raw_image(
                raw, contrast_limits=contrast_limits, invert_image=False
            )
            crop, origin_x, origin_y = _crop_image_around_center(
                raw_norm,
                centers_x[idx],
                centers_y[idx],
                auto_width,
                auto_height,
                fill_value=float(np.nanmin(raw_norm)),
            )
            cropped_stack.append(crop)
            origins[int(frame)] = (origin_x, origin_y)

            if track_history == "window" and history_length_frames is not None:
                history_start = max(frame_start, int(frame - history_length_frames))
            elif track_history == "window":
                history_start = max(frame_start, int(display_frames[max(0, idx - 1)]))
            elif history_length_frames is not None:
                history_start = max(frame_start, int(frame - history_length_frames))
            else:
                history_start = frame_start

            visible = track[
                (track[frame_col] >= history_start) & (track[frame_col] <= frame)
            ].copy()
            if "png" in render_outputs:
                fig, ax = plt.subplots(figsize=(3, 3), dpi=dpi)
                ax.imshow(crop, cmap=cmap, origin="upper")
                if len(visible) >= 2:
                    ax.plot(
                        visible["_display_x"] - origin_x,
                        visible["_display_y"] - origin_y,
                        color=resolved_track_color,
                        lw=track_line_width,
                        alpha=0.95,
                    )
                current = visible.tail(1)
                if not current.empty:
                    ax.scatter(
                        current["_display_x"] - origin_x,
                        current["_display_y"] - origin_y,
                        color=head_color,
                        s=head_size,
                        edgecolors="none",
                        zorder=3,
                    )
                ax.set_xlim(0, auto_width)
                ax.set_ylim(auto_height, 0)
                ax.set_aspect("equal", adjustable="box")
                ax.axis("off")
                if show_time_label:
                    ax.text(
                        0.02,
                        0.04,
                        f"{frame * frame_interval:.2f} s",
                        transform=ax.transAxes,
                        color=scale_bar_color,
                        fontsize=scale_bar_fontsize,
                        ha="left",
                        va="bottom",
                    )
                if show_scale_bar and scale_bar_length_um is not None and pixel_size_um:
                    bar_len_px = float(scale_bar_length_um) / float(pixel_size_um)
                    margin = float(scale_bar_margin_px)
                    if scale_bar_position == "lower_left":
                        x0 = margin
                        x1 = x0 + bar_len_px
                        y = auto_height - margin
                        text_y = y - 5
                        va = "bottom"
                    elif scale_bar_position == "upper_left":
                        x0 = margin
                        x1 = x0 + bar_len_px
                        y = margin
                        text_y = y + 5
                        va = "top"
                    elif scale_bar_position == "upper_right":
                        x1 = auto_width - margin
                        x0 = x1 - bar_len_px
                        y = margin
                        text_y = y + 5
                        va = "top"
                    else:
                        x1 = auto_width - margin
                        x0 = x1 - bar_len_px
                        y = auto_height - margin
                        text_y = y - 5
                        va = "bottom"
                    ax.plot([x0, x1], [y, y], color=scale_bar_color, lw=scale_bar_line_width)
                    ax.text(
                        (x0 + x1) / 2,
                        text_y,
                        scale_bar_label or f"{scale_bar_length_um:g} um",
                        color=scale_bar_color,
                        fontsize=scale_bar_fontsize,
                        ha="center",
                        va=va,
                    )
                out_path = png_dir / f"track_{track_label}_{view_mode}_{idx:04d}_frame_{frame:05d}.{output_format}"
                fig.savefig(out_path, dpi=dpi, bbox_inches="tight", pad_inches=0, format=output_format)
                plt.close(fig)

            # Napari stores each point in the crop coordinates of its own frame.
            frame_points = track[track[frame_col] == frame]
            for _, row in frame_points.iterrows():
                napari_rows.append(
                    [
                        0,
                        int(np.where(display_frames == frame)[0][0]),
                        float(row["_display_y"] - origin_y),
                        float(row["_display_x"] - origin_x),
                    ]
                )

        movie_path = None
        viewer = None
        if "napari" in render_outputs:
            viewer = napari.Viewer()
            viewer.add_image(
                np.asarray(cropped_stack),
                name=f"Raw follow view {track_id}",
                colormap=_coerce_lut_colormap(raw_lut, target="napari", fallback=raw_cmap),
                contrast_limits=None,
            )
            if napari_rows:
                napari_tracks = pd.DataFrame(napari_rows, columns=["track_id", "frame", "y", "x"])
                viewer.add_tracks(
                    napari_tracks.to_numpy(),
                    name=f"Track {track_id}",
                    tail_length=napari_tail_length,
                    tail_width=max(1, int(round(track_line_width))),
                )
                movie_path = track_dir / f"track_{track_label}_{view_mode}.mp4"
                save_movie(
                    viewer,
                    napari_tracks,
                    save_path=str(movie_path),
                    steps=max(1, len(display_frames) - 1),
                    fps=fps,
                )
            if close_after_save:
                viewer.close()

        output_records.append(
            {
                "track_id": track_id,
                "view_mode": view_mode,
                "n_frames": int(len(display_frames)),
                "frame_start": int(display_frames.min()),
                "frame_end": int(display_frames.max()),
                "crop_width": int(auto_width),
                "crop_height": int(auto_height),
                "png_dir": str(png_dir) if "png" in render_outputs else None,
                "movie_path": str(movie_path) if movie_path is not None else None,
            }
        )

    return {
        "selected_track_ids": selected_ids,
        "outputs": output_records,
        "raw_movie_path": raw_movie_path,
        "frame_range": (frame_start, frame_end),
    }


def gallery_of_tracks(
    instant_df,
    color_by="simple_threshold",
    num_tracks=20,
    colormap="Dark2",
    custom_colors=None,
    figsize=(12, 12),
    transparent_background=True,
    show_annotations=False,
    annotation_color="white",
    text_size=10,
    export_format="svg",
    save_path=None,
    show_plot=True,
    order=None,
    track_length_frames=60,
    spacing_factor=1.2,
    line_width=1.5,
    grid_cols=None,
    dpi=200,
    subplot_size_um=None,
):
    """
    Create a gallery of tracks distributed in a grid layout with consistent scaling.
    
    This function creates a visual gallery of particle tracks, where each track is 
    displayed in its own subplot with consistent scaling across all tracks for 
    visual size comparison.
    
    Parameters
    ----------
    instant_df : pandas.DataFrame or polars.DataFrame
        Instant trajectory dataframe containing track data
    color_by : str, default "simple_threshold"
        Column name to use for categorical coloring of tracks
    num_tracks : int, default 20
        Number of tracks to display per category
    colormap : str, default "Dark2"
        Colormap for coloring categories. Options:
        - 'colorblind': Wong 2011 colorblind-friendly palette (10 colors, cycles if needed)
        - 'Dark2': Matplotlib Dark2 colormap
        - Any other matplotlib colormap name
        Ignored if custom_colors is provided.
    custom_colors : list of str or None, default None
        Custom list of colors (hex codes, named colors, or RGB tuples).
        If provided, overrides colormap parameter.
        Example: ['#0173B2', '#DE8F05', '#029E73'] or ['red', 'blue', 'green']
    figsize : tuple or None, default (12, 12)
        Figure size in inches (width, height). If None, automatically calculated based on grid size
    transparent_background : bool, default True
        Whether to use transparent background
    show_annotations : bool, default False
        Whether to show track annotations
    annotation_color : str, default "white"
        Color for annotations
    text_size : int, default 10
        Font size for text annotations
    export_format : str, default "svg"
        Export format ('svg' or 'png')
    save_path : str or None, default None
        Path to save the figure. If None, saves to current directory
    show_plot : bool, default True
        Whether to display the plot
    order : list or None, default None
        Order of categories to display
    track_length_frames : int, default 60
        Number of consecutive frames to include per track
    spacing_factor : float, default 1.2
        Factor to multiply the maximum track extent for spacing between tracks
    line_width : float, default 1.5
        Width of track lines
    grid_cols : int or None, default None
        Number of columns in the grid. If None, automatically calculated
    dpi : int, default 200
        Resolution for saved figure
    subplot_size_um : float or None, default None
        Manual subplot size in microns. If None, automatically calculated from largest track extent
        
    Returns
    -------
    dict
        Dictionary containing track information and figure details
    """
    import matplotlib.pyplot as plt
    import matplotlib.patches as patches
    import numpy as np
    import random
    from matplotlib import cm
    import seaborn as sns
    
    # Auto-detect dataframe type and convert to pandas for compatibility
    is_polars = hasattr(instant_df, 'schema')
    if is_polars:
        import polars as pl
        df = instant_df.to_pandas()
    else:
        df = instant_df.copy()
    
    # Ensure required columns exist
    required_cols = ['unique_id', 'x_um', 'y_um', 'frame']
    missing_cols = [col for col in required_cols if col not in df.columns]
    if missing_cols:
        raise ValueError(f"Missing required columns: {missing_cols}")
    
    if color_by not in df.columns:
        raise ValueError(f"Column '{color_by}' not found in dataframe")
    
    # Get categories for coloring
    categories = order if order else sorted(df[color_by].unique())
    print(f"Gallery categories in order: {categories}")
    
    # Set up color mapping
    if custom_colors is not None:
        # Use custom colors provided by user
        # Cycle through colors if more categories than colors
        colors = [custom_colors[i % len(custom_colors)] for i in range(len(categories))]
    elif colormap == "colorblind":
        # Use Wong 2011 colorblind-friendly palette (same as plot_pca_3d)
        colorblind_colors = [
            '#0173B2',  # Blue
            '#DE8F05',  # Orange  
            '#029E73',  # Green
            '#CC78BC',  # Purple
            '#CA9161',  # Brown
            '#FBAFE4',  # Pink
            '#949494',  # Gray
            '#ECE133',  # Yellow
            '#56B4E9',  # Sky blue
            '#D55E00'   # Vermillion
        ]
        # Cycle through colors if more categories than colors
        colors = [colorblind_colors[i % len(colorblind_colors)] for i in range(len(categories))]
    elif colormap == "Dark2":
        cmap = cm.get_cmap("Dark2", len(categories))
        colors = cmap(np.linspace(0, 1, len(categories)))
    else:
        colors = plt.get_cmap(colormap, len(categories)).colors
    
    category_color_map = {cat: colors[i] for i, cat in enumerate(categories)}
    
    # Collect track segments for each category
    all_track_segments = []
    track_info = []
    
    for category in categories:
        # Filter by category
        cat_df = df[df[color_by] == category]
        unique_ids = cat_df['unique_id'].unique()
        
        # Randomly select tracks for this category
        selected_ids = random.sample(
            list(unique_ids), 
            min(num_tracks, len(unique_ids))
        )
        
        for unique_id in selected_ids:
            # Get all data for this track
            track_data = cat_df[cat_df['unique_id'] == unique_id].sort_values('frame')
            
            # Take a consecutive segment of the specified length
            if len(track_data) >= track_length_frames:
                # Randomly choose a starting point that allows for full segment
                max_start = len(track_data) - track_length_frames
                start_idx = random.randint(0, max_start) if max_start > 0 else 0
                track_segment = track_data.iloc[start_idx:start_idx + track_length_frames]
            else:
                # Use all available data if track is shorter
                track_segment = track_data
            
            if len(track_segment) >= 10:  # Minimum track length for visualization
                all_track_segments.append(track_segment)
                track_info.append((category, unique_id, len(track_segment)))
    
    if not all_track_segments:
        raise ValueError("No valid track segments found")
    
    print(f"Collected {len(all_track_segments)} tracks total")
    
    # Calculate subplot size
    if subplot_size_um is not None:
        # Use manually specified subplot size
        subplot_size = subplot_size_um
        print(f"Using manual subplot size: {subplot_size:.2f} μm")
    else:
        # Calculate global scale based on largest track extent
        max_extent = 0
        for segment in all_track_segments:
            x_range = segment['x_um'].max() - segment['x_um'].min()
            y_range = segment['y_um'].max() - segment['y_um'].min()
            extent = max(x_range, y_range)
            max_extent = max(max_extent, extent)
        
        # Add spacing between tracks
        subplot_size = max_extent * spacing_factor
        print(f"Using calculated subplot size: {subplot_size:.2f} μm")
    
    # Calculate grid layout
    total_tracks = len(all_track_segments)
    if grid_cols is None:
        grid_cols = int(np.ceil(np.sqrt(total_tracks)))
    grid_rows = int(np.ceil(total_tracks / grid_cols))
    
    print(f"Grid layout: {grid_rows} rows × {grid_cols} columns")
    
    # Calculate dynamic figsize if None
    if figsize is None:
        # Base size per subplot in inches (adjust as needed)
        subplot_size_inches = 2.0
        figsize = (grid_cols * subplot_size_inches, grid_rows * subplot_size_inches)
        print(f"Using dynamic figsize: {figsize}")
    
    # Create figure
    figure_background = "none" if transparent_background else "white"
    axis_background = (0, 0, 0, 0) if transparent_background else "white"
    
    fig, axes = plt.subplots(
        grid_rows, grid_cols, 
        figsize=figsize,
        facecolor=figure_background
    )
    
    # Handle single subplot case
    if grid_rows == 1 and grid_cols == 1:
        axes = [axes]
    elif grid_rows == 1 or grid_cols == 1:
        axes = axes.flatten()
    else:
        axes = axes.flatten()
    
    # Remove spacing between subplots for seamless grid
    fig.subplots_adjust(wspace=0.02, hspace=0.02)
    
    # Plot each track
    plotted_tracks = []
    for idx, (segment, (category, unique_id, segment_length)) in enumerate(zip(all_track_segments, track_info)):
        if idx >= len(axes):
            break
            
        ax = axes[idx]
        
        # Extract coordinates
        x_coords = segment['x_um'].values
        y_coords = segment['y_um'].values
        
        # Calculate centroid for centering
        x_center = x_coords.mean()
        y_center = y_coords.mean()
        
        # Plot the track
        color = category_color_map[category]
        ax.plot(x_coords, y_coords, color=color, linewidth=line_width, alpha=0.8)
        
        # Set consistent axis limits centered on track
        half_size = subplot_size / 2
        ax.set_xlim(x_center - half_size, x_center + half_size)
        ax.set_ylim(y_center - half_size, y_center + half_size)
        ax.set_aspect('equal')
        
        # Remove all axis elements
        ax.axis('off')
        ax.set_facecolor(axis_background)
        
        # Add category annotation if requested
        if show_annotations:
            ax.text(
                0.5, 0.95, f"{category}\n{unique_id}",
                transform=ax.transAxes,
                ha='center', va='top',
                fontsize=text_size,
                color=annotation_color,
                bbox=dict(boxstyle="round,pad=0.3", facecolor='black', alpha=0.7)
            )
        
        plotted_tracks.append({
            'category': category,
            'unique_id': unique_id,
            'segment_length': segment_length,
            'x_center': x_center,
            'y_center': y_center,
            'subplot_index': idx
        })
    
    # Hide any unused subplots
    for idx in range(len(all_track_segments), len(axes)):
        axes[idx].axis('off')
        axes[idx].set_facecolor(axis_background)
    
    # Add title with category information
    category_counts = {}
    for category, _, _ in track_info:
        category_counts[category] = category_counts.get(category, 0) + 1
    
    title_text = f"Gallery of Tracks (colored by {color_by})\n"
    title_text += " | ".join([f"{cat}: {count}" for cat, count in category_counts.items()])
    
    fig.suptitle(
        title_text,
        fontsize=text_size + 2,
        color=annotation_color if transparent_background else "black",
        y=0.98
    )
    
    # Save figure
    if save_path is None:
        save_path = f"gallery_of_tracks_{color_by}.{export_format}"
    
    plt.savefig(
        save_path,
        format=export_format,
        dpi=dpi,
        bbox_inches='tight',
        transparent=transparent_background,
        facecolor=figure_background
    )
    
    if show_plot:
        plt.show()
    else:
        plt.close()
    
    # Return summary information
    return {
        'plotted_tracks': plotted_tracks,
        'category_counts': category_counts,
        'total_tracks': len(all_track_segments),
        'subplot_size_um': subplot_size,
        'grid_dimensions': (grid_rows, grid_cols),
        'save_path': save_path,
        'categories': categories
    }


def get_viz_df(df, cluster_column, uncertainty_threshold=None):
    """
    Filter a Polars ``DataFrame`` for visualization (non-null cluster column and
    optional signature uncertainty cap).

    Parameters
    ----------
    df : pl.DataFrame
        Table such as ``test_windowed_df`` or ``test_instant_df``; must contain
        ``cluster_column``.
    cluster_column : str
        e.g. ``generic_cluster``, ``signature_cluster``.
    uncertainty_threshold : float or None
        If set and column ``signature_uncertainty`` exists, keep rows with
        ``signature_uncertainty <= uncertainty_threshold``.

    Returns
    -------
    pl.DataFrame
        Filtered frame (same schema subset).
    """
    if not isinstance(df, pl.DataFrame):
        raise TypeError("get_viz_df expects a polars.DataFrame")
    if cluster_column not in df.columns:
        raise ValueError(f"Column {cluster_column!r} not found in dataframe")

    _filter = pl.col(cluster_column).is_not_null()

    if uncertainty_threshold is not None and "signature_uncertainty" in df.columns:
        _filter = _filter & (pl.col("signature_uncertainty") <= uncertainty_threshold)
        print(f"   Uncertainty filter: signature_uncertainty <= {uncertainty_threshold}")

    result = df.filter(_filter)
    denom = max(df.height, 1)
    pct = result.height / denom * 100.0
    print(
        f"   Viz data: {result.height:,} / {df.height:,} rows ({pct:.1f}%)"
    )
    return result


def subsample_instant_for_gallery_by_window_uid(
    instant_df,
    color_by: str,
    num_tracks_per_category: int,
    *,
    order=None,
    random_state: int = 42,
):
    """
    Subsample instant-level rows in **Polars** by picking random ``window_uid`` values
    per ``color_by`` category (``num_tracks_per_category`` uids per category).

    Use this **before** :func:`gallery_of_tracks_v4` on large instant tables to avoid
    ``to_pandas()`` OOM. Returns a Polars ``DataFrame`` containing only rows whose
    ``window_uid`` was selected.

    Parameters
    ----------
    instant_df : pl.DataFrame
        Must include ``window_uid``, ``color_by``, and columns needed for plotting.
    color_by : str
        Column name (e.g. ``generic_cluster_name``).
    num_tracks_per_category : int
        How many distinct ``window_uid`` values to draw per category.
    order : sequence, optional
        Category order; categories not listed are appended sorted after.
    random_state : int
        RNG seed for reproducible sampling.

    Returns
    -------
    pl.DataFrame
        Filtered copy (semi-join on selected ``window_uid`` values).
    """
    import polars as pl

    if not isinstance(instant_df, pl.DataFrame):
        raise TypeError("instant_df must be a polars.DataFrame")
    if "window_uid" not in instant_df.columns:
        raise ValueError("instant_df must contain column 'window_uid'")
    if color_by not in instant_df.columns:
        raise ValueError(f"Column {color_by!r} not found in instant_df")

    raw = instant_df[color_by].drop_nulls().unique().to_list()
    if order is not None:
        categories = [c for c in order if c in raw]
        categories += [c for c in sorted(raw, key=lambda x: (isinstance(x, str), str(x))) if c not in categories]
    else:
        categories = sorted(raw, key=lambda x: (isinstance(x, str), str(x)))

    rng = np.random.default_rng(int(random_state))
    selected_uids: list = []

    for cat in categories:
        cat_uids = (
            instant_df.filter(pl.col(color_by) == cat)
            .select("window_uid")
            .unique()
            .to_series()
            .drop_nulls()
            .to_list()
        )
        n = min(int(num_tracks_per_category), len(cat_uids))
        if n == 0:
            continue
        idx = rng.choice(len(cat_uids), size=n, replace=False)
        selected_uids.extend(cat_uids[i] for i in idx)

    if not selected_uids:
        raise ValueError(
            "No window_uid values selected (empty categories or num_tracks_per_category=0)."
        )

    uid_df = pl.DataFrame({"window_uid": selected_uids})
    out = instant_df.join(uid_df, on="window_uid", how="semi")
    print(
        f"subsample_instant_for_gallery_by_window_uid: {instant_df.height:,} → {out.height:,} rows, "
        f"{len(selected_uids)} window_uids across {len(categories)} categories"
    )
    return out


def gallery_of_tracks_v4(
    instant_df,
    color_by="simple_threshold",
    num_tracks=20,
    colormap="Dark2",
    custom_colors=None,
    figsize=(12, 12),
    transparent_background=True,
    show_annotations=False,
    annotation="default",  # NEW: str | list[str] | callable | "default"
    annotation_color="white",
    text_size=10,
    export_format="svg",
    save_path=None,
    show_plot=True,
    order=None,
    track_length_frames=60,
    spacing_factor=1.2,
    line_width=1.5,
    grid_cols=None,
    dpi=200,
    subplot_size_um=None,
    show_scale_bar=False,
    scale_bar_length_um=None,
    scale_bar_color='white',
    scale_bar_linewidth=3,
    segment_by="unique_id",
    min_segment_length=None,
    random_state=None,
    max_rows_polars_to_pandas=500_000,
    use_full_window_for_window_uid=True,
):
    """
    Create a gallery of tracks distributed in a grid layout with consistent scaling.
    ...
    Parameters
    ----------
    ...
    show_annotations : bool, default False
        Whether to show track annotations
    annotation : str | list[str] | callable | "default", default "default"
        What to annotate inside each subplot.
        - If a format string, it will be formatted with variables:
          {category}, {unique_id}, {window_uid} (if present), {segment_length},
          {start_frame}, {end_frame}.
        - If a list/tuple of column names, their values (from the segment) are joined with ' | '.
        - If a callable, it must be: fn(segment_dataframe, meta_dict) -> str
        - "default" shows "{category}\n{unique_id}" (previous behavior).
    annotation_color : str, default "white"
        Color for annotations
    text_size : int, default 10
        Font size for annotations and scale bar
    subplot_size_um : float or None, default None
        Manual subplot size in microns. If None, automatically calculated from largest track extent
    show_scale_bar : bool, default False
        Whether to show a scale bar in the bottom-right subplot
    scale_bar_length_um : float or None, default None
        Length of scale bar in microns. If None, defaults to subplot_size_um
    scale_bar_color : str, default 'white'
        Color of the scale bar and label
    scale_bar_linewidth : float, default 3
        Line width of the scale bar
    
    segment_by : str, default ``"unique_id"``
        ``"unique_id"`` — sample long tracks by molecule id and optionally crop to
        ``track_length_frames`` (original behavior).
        ``"window_uid"`` — sample one segment per distinct ``window_uid`` per category
        (variable length; typically one analysis window). Requires ``window_uid`` column.
    min_segment_length : int or None
        Minimum points required to plot a segment. If ``None``, uses 10 for
        ``segment_by="unique_id"`` and 2 for ``segment_by="window_uid"``.
    random_state : int or None
        Seed for Python ``random`` sampling (reproducible track picks).
    max_rows_polars_to_pandas : int or None
        If the input is Polars and ``height`` exceeds this value, raise instead of
        calling ``to_pandas()`` (avoids OOM). Set ``None`` to disable the guard.
        Call :func:`subsample_instant_for_gallery_by_window_uid` first to shrink rows.
    use_full_window_for_window_uid : bool, default True
        If ``segment_by="window_uid"`` and True, plot the full window (ignore
        ``track_length_frames`` for cropping). If False, crop long windows like
        ``unique_id`` mode.

    Returns
    -------
    dict
        Dictionary with keys: 'plotted_tracks', 'category_counts', 'total_tracks',
        'subplot_size_um', 'grid_dimensions', 'save_path', 'categories'
    """
    import matplotlib.pyplot as plt
    import numpy as np
    import random
    from matplotlib import cm

    if random_state is not None:
        random.seed(int(random_state))

    segment_by = (segment_by or "unique_id").strip().lower()
    if segment_by not in ("unique_id", "window_uid"):
        raise ValueError('segment_by must be "unique_id" or "window_uid"')

    min_seg = (
        min_segment_length
        if min_segment_length is not None
        else (2 if segment_by == "window_uid" else 10)
    )

    # Auto-detect dataframe type; avoid full-materialization OOM on huge Polars frames
    is_polars = hasattr(instant_df, "schema")
    if is_polars:
        import polars as pl

        n_polars = instant_df.height
        if max_rows_polars_to_pandas is not None and n_polars > int(max_rows_polars_to_pandas):
            raise MemoryError(
                f"instant_df has {n_polars:,} rows, above max_rows_polars_to_pandas="
                f"{max_rows_polars_to_pandas:,}. Subsample first, e.g. "
                f"spt.subsample_instant_for_gallery_by_window_uid(...), or pass "
                f"max_rows_polars_to_pandas=None (not recommended for very large tables)."
            )
        df = instant_df.to_pandas()
    else:
        df = instant_df.copy()

    # Ensure required columns exist
    required_cols = ["unique_id", "x_um", "y_um", "frame"]
    if segment_by == "window_uid":
        required_cols = required_cols + ["window_uid"]
    missing_cols = [col for col in required_cols if col not in df.columns]
    if missing_cols:
        raise ValueError(f"Missing required columns: {missing_cols}")

    if color_by not in df.columns:
        raise ValueError(f"Column '{color_by}' not found in dataframe")

    # Get categories for coloring
    categories = order if order else sorted(df[color_by].unique())
    print(f"Gallery categories in order: {categories} (segment_by={segment_by})")

    # Set up color mapping
    if custom_colors is not None:
        colors = [custom_colors[i % len(custom_colors)] for i in range(len(categories))]
    elif colormap == "colorblind":
        colorblind_colors = [
            '#0173B2', '#DE8F05', '#029E73', '#CC78BC', '#CA9161',
            '#FBAFE4', '#949494', '#ECE133', '#56B4E9', '#D55E00'
        ]
        colors = [colorblind_colors[i % len(colorblind_colors)] for i in range(len(categories))]
    elif colormap == "Dark2":
        cmap = cm.get_cmap("Dark2", len(categories))
        colors = cmap(np.linspace(0, 1, len(categories)))
    else:
        colors = plt.get_cmap(colormap, len(categories)).colors

    category_color_map = {cat: colors[i] for i, cat in enumerate(categories)}

    # Collect track segments for each category
    all_track_segments = []
    track_info = []

    for category in categories:
        cat_df = df[df[color_by] == category]

        if segment_by == "unique_id":
            unique_ids = cat_df["unique_id"].unique()
            selected_ids = random.sample(
                list(unique_ids), min(num_tracks, len(unique_ids))
            )

            for unique_id in selected_ids:
                track_data = cat_df[cat_df["unique_id"] == unique_id].sort_values(
                    "frame"
                )

                if len(track_data) >= track_length_frames:
                    max_start = len(track_data) - track_length_frames
                    start_idx = random.randint(0, max_start) if max_start > 0 else 0
                    track_segment = track_data.iloc[
                        start_idx : start_idx + track_length_frames
                    ]
                else:
                    track_segment = track_data

                if len(track_segment) >= min_seg:
                    all_track_segments.append(track_segment)
                    track_info.append((category, unique_id, len(track_segment)))

        else:
            # One segment per window_uid (variable length)
            wuids = cat_df["window_uid"].dropna().unique()
            selected_wuids = random.sample(
                list(wuids), min(num_tracks, len(wuids))
            )

            for wuid in selected_wuids:
                track_segment = cat_df[cat_df["window_uid"] == wuid].sort_values(
                    "frame"
                )
                if use_full_window_for_window_uid:
                    pass
                elif len(track_segment) >= track_length_frames:
                    max_start = len(track_segment) - track_length_frames
                    start_idx = random.randint(0, max_start) if max_start > 0 else 0
                    track_segment = track_segment.iloc[
                        start_idx : start_idx + track_length_frames
                    ]

                if len(track_segment) >= min_seg:
                    uid0 = track_segment["unique_id"].iloc[0]
                    all_track_segments.append(track_segment)
                    track_info.append((category, uid0, len(track_segment)))

    if not all_track_segments:
        raise ValueError("No valid track segments found")

    print(f"Collected {len(all_track_segments)} tracks total")

    # Calculate subplot size
    if subplot_size_um is not None:
        subplot_size = subplot_size_um
        print(f"Using manual subplot size: {subplot_size:.2f} μm")
    else:
        max_extent = 0
        for segment in all_track_segments:
            x_range = segment['x_um'].max() - segment['x_um'].min()
            y_range = segment['y_um'].max() - segment['y_um'].min()
            extent = max(x_range, y_range)
            max_extent = max(max_extent, extent)
        subplot_size = max_extent * spacing_factor
        print(f"Using calculated subplot size: {subplot_size:.2f} μm")

    # Calculate grid layout
    total_tracks = len(all_track_segments)
    if grid_cols is None:
        grid_cols = int(np.ceil(np.sqrt(total_tracks)))
    grid_rows = int(np.ceil(total_tracks / grid_cols))
    print(f"Grid layout: {grid_rows} rows × {grid_cols} columns")

    # Dynamic figsize
    if figsize is None:
        subplot_size_inches = 2.0
        figsize = (grid_cols * subplot_size_inches, grid_rows * subplot_size_inches)
        print(f"Using dynamic figsize: {figsize}")

    # Create figure
    figure_background = "none" if transparent_background else "white"
    axis_background = (0, 0, 0, 0) if transparent_background else "white"

    fig, axes = plt.subplots(
        grid_rows, grid_cols,
        figsize=figsize,
        facecolor=figure_background
    )

    # Normalize axes to 1D list
    if grid_rows == 1 and grid_cols == 1:
        axes = [axes]
    else:
        axes = np.array(axes).flatten()

    fig.subplots_adjust(wspace=0.02, hspace=0.02)

    plotted_tracks = []

    # --- Annotation setup (NEW) ---
    def _make_annotation_text(segment, meta):
        """
        segment: pd.DataFrame for this plotted segment
        meta: dict with keys: category, unique_id, segment_length, start_frame, end_frame, window_uid (if present)
        """
        if not show_annotations:
            return None

        # Callable user function
        if callable(annotation):
            try:
                return str(annotation(segment, meta))
            except Exception as e:
                return f"(annotation error: {e})"

        # List/tuple of columns -> join their values from the segment (first non-null)
        if isinstance(annotation, (list, tuple)):
            vals = []
            for col in annotation:
                if col in segment.columns:
                    val = segment[col].iloc[0]
                else:
                    val = meta.get(col, None)
                vals.append(f"{col}={val}")
            return " | ".join(vals)

        # Format string or "default"
        if isinstance(annotation, str):
            if annotation == "default":
                return f"{meta['category']}\n{meta['unique_id']}"
            # Build context for formatting
            ctx = dict(meta)  # start with meta
            # Allow direct column access if user wrote {some_col}
            # Pull first element for each column name present
            for col in segment.columns:
                if col not in ctx:
                    try:
                        ctx[col] = segment[col].iloc[0]
                    except Exception:
                        pass
            try:
                return annotation.format(**ctx)
            except KeyError as e:
                return f"(missing {e.args[0]} in annotation)"
            except Exception as e:
                return f"(annotation error: {e})"

        # Fallback
        return f"{meta['category']}\n{meta['unique_id']}"

    # Plot each track
    for idx, (segment, (category, unique_id, segment_length)) in enumerate(zip(all_track_segments, track_info)):
        if idx >= len(axes):
            break

        ax = axes[idx]

        x_coords = segment['x_um'].values
        y_coords = segment['y_um'].values

        x_center = x_coords.mean()
        y_center = y_coords.mean()

        color = category_color_map[category]
        ax.plot(x_coords, y_coords, color=color, linewidth=line_width, alpha=0.8)

        half_size = subplot_size / 2
        ax.set_xlim(x_center - half_size, x_center + half_size)
        ax.set_ylim(y_center - half_size, y_center + half_size)
        ax.set_aspect('equal')

        ax.axis('off')
        ax.set_facecolor(axis_background)

        # Build meta for annotation formatting
        start_frame = int(segment['frame'].min())
        end_frame = int(segment['frame'].max())
        # window_uid = None
        # if 'window_uid' in segment.columns:
        #     try:
        #         window_uid = segment['window_uid'].iloc[0]
        #     except Exception:
        #         pass
        # --- NEW: support multiple window_uids if segment crosses windows ---
        window_uid = None
        window_uids = None
        if 'window_uid' in segment.columns:
            vals = segment['window_uid'].dropna().astype(str)
            if len(vals) > 0:
                window_uids = sorted(vals.unique())
                window_uid = ", ".join(window_uids)   # show all windows in this segment


        meta = {
            'category': category,
            'unique_id': unique_id,
            'segment_length': int(segment_length),
            'start_frame': start_frame,
            'end_frame': end_frame,
            'window_uid': window_uid,
            'window_uids': window_uids
        }

        ann_text = _make_annotation_text(segment, meta)
        if show_annotations and ann_text:
            ax.text(
                0.5, 0.95, ann_text,
                transform=ax.transAxes,
                ha='center', va='top',
                fontsize=text_size,
                color=annotation_color,
                bbox=dict(boxstyle="round,pad=0.3", facecolor='black', alpha=0.7)
            )

        plotted_tracks.append({
            'category': category,
            'unique_id': unique_id,
            'segment_length': segment_length,
            'x_center': x_center,
            'y_center': y_center,
            'subplot_index': idx,
            'start_frame': start_frame,
            'end_frame': end_frame,
            'window_uid': window_uid
        })

    # Hide any unused subplots
    for idx in range(len(all_track_segments), len(axes)):
        axes[idx].axis('off')
        axes[idx].set_facecolor(axis_background)

    # Add scale bar to bottom-right plotted subplot
    if show_scale_bar and len(all_track_segments) > 0:
        # Default scale bar length to subplot size
        if scale_bar_length_um is None:
            scale_bar_length_um = subplot_size
        
        # Get the last plotted subplot (bottom-right with content)
        last_plot_idx = len(all_track_segments) - 1
        scale_ax = axes[last_plot_idx]
        
        # Get the axis limits
        xlim = scale_ax.get_xlim()
        ylim = scale_ax.get_ylim()
        
        # Position scale bar at bottom-right (with padding)
        padding_fraction = 0.1  # 10% padding from edges
        x_padding = (xlim[1] - xlim[0]) * padding_fraction
        y_padding = (ylim[1] - ylim[0]) * padding_fraction
        
        # Scale bar endpoints
        scale_bar_x_end = xlim[1] - x_padding
        scale_bar_x_start = scale_bar_x_end - scale_bar_length_um
        scale_bar_y = ylim[0] + y_padding
        
        # Draw scale bar line
        scale_ax.plot(
            [scale_bar_x_start, scale_bar_x_end],
            [scale_bar_y, scale_bar_y],
            color=scale_bar_color,
            linewidth=scale_bar_linewidth,
            solid_capstyle='butt'
        )
        
        # Add end caps for scale bar
        cap_height = (ylim[1] - ylim[0]) * 0.02
        scale_ax.plot(
            [scale_bar_x_start, scale_bar_x_start],
            [scale_bar_y - cap_height, scale_bar_y + cap_height],
            color=scale_bar_color,
            linewidth=scale_bar_linewidth * 0.7
        )
        scale_ax.plot(
            [scale_bar_x_end, scale_bar_x_end],
            [scale_bar_y - cap_height, scale_bar_y + cap_height],
            color=scale_bar_color,
            linewidth=scale_bar_linewidth * 0.7
        )
        
        # Add scale bar label
        scale_ax.text(
            (scale_bar_x_start + scale_bar_x_end) / 2,
            scale_bar_y + y_padding * 0.5,
            f'{scale_bar_length_um:.1f} μm',
            ha='center',
            va='bottom',
            color=scale_bar_color,
            fontsize=text_size,
            fontweight='bold',
            bbox=dict(boxstyle="round,pad=0.3", facecolor='black', alpha=0.7)
        )

    # Title
    category_counts = {}
    for category, _, _ in track_info:
        category_counts[category] = category_counts.get(category, 0) + 1

    title_text = f"Gallery of Tracks (colored by {color_by})\n"
    title_text += " | ".join([f"{cat}: {count}" for cat, count in category_counts.items()])

    fig.suptitle(
        title_text,
        fontsize=text_size + 2,
        color=annotation_color if transparent_background else "black",
        y=0.98
    )

    # Save
    if save_path is None:
        save_path = f"gallery_of_tracks_{color_by}.{export_format}"

    plt.savefig(
        save_path,
        format=export_format,
        dpi=dpi,
        bbox_inches='tight',
        transparent=transparent_background,
        facecolor=figure_background
    )

    if show_plot:
        plt.show()
    else:
        plt.close()

    return {
        'plotted_tracks': plotted_tracks,
        'category_counts': category_counts,
        'total_tracks': len(all_track_segments),
        'subplot_size_um': subplot_size,
        'grid_dimensions': (grid_rows, grid_cols),
        'save_path': save_path,
        'categories': categories
    }


def gallery_of_tracks_v5(
    instant_df,
    order_by="superwindow_id",
    segment_color_by="final_population",
    num_tracks=20,
    segment_colors=None,
    segment_colormap="colorblind",
    figsize=(12, 12),
    transparent_background=True,
    show_annotations=False,
    annotation="default",
    annotation_color="white",  # Deprecated: use text_color instead
    text_color=None,  # NEW: Single variable for all text/annotation colors
    text_size=10,
    export_format="svg",
    save_path=None,
    show_plot=True,
    order=None,
    track_length_frames=60,
    spacing_factor=1.2,
    line_width=1.5,
    grid_cols=None,
    dpi=200,
    subplot_size_um=None,
    show_scale_bar=False,
    scale_bar_length_um=None,
    scale_bar_color='white',
    scale_bar_linewidth=3,
    # DEPRECATED: use show_subplot_border instead
    draw_box=False,
    box_colormap="tab10",
    box_colors=None,
    box_linewidth=3,
    # Subplot border (bounding box around each subplot)
    show_subplot_border=False,
    subplot_border_color=None,  # Solid color for all borders (if not using colormap)
    subplot_border_linewidth=2,
    subplot_border_color_by=None,  # 'cluster' to color by cluster, None for solid color
    subplot_border_colormap='colorblind',  # Colormap for borders when color_by is set
    subplot_border_colors=None,  # Custom color dict for borders {cluster_id: color}
    # NEW: Legend for segment colors
    show_legend=True,
    legend_title=None,  # Defaults to segment_color_by column name
    legend_loc='right',  # 'right', 'bottom', or specific matplotlib location
    legend_order=None,  # Custom order for legend items (e.g., state_order from plot_representative_sequences)
    # NEW: Structured grid layout (matching plot_representative_sequences)
    group_by=None,
    cluster_col=None,
    n_per_cluster=None,
    cluster_order=None,
    group_order=None,
    random_seed=42,
    # NEW: Use exact track order from plot_representative_sequences
    superwindow_ids=None,  # List of superwindow_ids in EXACT plotting order from plot_representative_sequences
    superwindow_id_col='superwindow_id',  # Column used ONLY to match rows to superwindow_ids (IDs from sequences)
):
    """
    Create a gallery of tracks with WITHIN-TRACK coloring by a segment attribute.
    
    This version allows tracks to be colored segment-by-segment based on a column
    like 'final_population', so you can see state transitions directly on the XY plot.
    
    Parameters
    ----------
    instant_df : pd.DataFrame or pl.DataFrame
        DataFrame with frame-level data. Must have columns: unique_id, x_um, y_um, frame
    order_by : str, default='superwindow_id'
        Column to use for ORDERING/GROUPING tracks in the gallery (e.g., 'superwindow_id', 
        'superwindow_cluster'). Tracks will be collected per unique value of this column.
    segment_color_by : str, default='final_population'
        Column to use for coloring WITHIN each track. Each unique value gets a different color.
    num_tracks : int, default=20
        Maximum number of tracks to show per order_by category
    segment_colors : dict, optional
        Custom color mapping for segment_color_by values. {value: color}
    segment_colormap : str, default='colorblind'
        Colormap to use for segment colors if segment_colors is not provided
    figsize : tuple, default=(12, 12)
        Figure size
    transparent_background : bool, default=True
        Transparent background
    show_annotations : bool, default=False
        Whether to show track annotations (displayed BELOW each subplot)
    annotation : str | list[str] | callable | "default", default="default"
        Annotation format. Use "{superwindow_id}" to show superwindow IDs.
    annotation_color : str, default="white"
        DEPRECATED: Use text_color instead. Color for annotations.
    text_color : str, optional
        Single variable to control ALL text colors (annotations, labels, legend, title).
        If None, defaults to annotation_color for backwards compatibility.
    text_size : int, default=10
        Font size for annotations
    export_format : str, default="svg"
        Export format
    save_path : str, optional
        Save path for the figure
    show_plot : bool, default=True
        Whether to display the plot
    order : list, optional
        Custom order for order_by values (e.g., list of superwindow_ids in desired order)
    track_length_frames : int, default=60
        Maximum number of frames to show per track
    spacing_factor : float, default=1.2
        Spacing factor for subplot sizing
    line_width : float, default=1.5
        Line width for track plots
    grid_cols : int, optional
        Number of columns in the grid. Auto-calculated if None.
    dpi : int, default=200
        DPI for saving
    subplot_size_um : float, optional
        Manual subplot size in microns
    show_scale_bar : bool, default=False
        Whether to show a scale bar
    scale_bar_length_um : float, optional
        Length of scale bar in microns
    scale_bar_color : str, default='white'
        Color of the scale bar
    scale_bar_linewidth : float, default=3
        Line width of the scale bar
    draw_box : bool, default=False
        Whether to draw a colored box/border around each subplot based on order_by value
    box_colormap : str, default='tab10'
        Colormap to use for box colors (e.g., 'tab10', 'colorblind', 'viridis')
    box_colors : dict, optional
        Custom color mapping for box colors. {order_by_value: color}
    box_linewidth : float, default=3
        Line width for the box border
    show_subplot_border : bool, default=False
        Whether to draw a bounding box/border around each subplot.
    subplot_border_color : str, optional
        Solid color for ALL subplot borders (used when subplot_border_color_by=None).
        Defaults to text_color if not specified.
    subplot_border_linewidth : float, default=2
        Line width for subplot borders.
    subplot_border_color_by : str, optional
        What to color the borders by. Options:
        - None: Use solid color (subplot_border_color)
        - 'cluster': Color borders by cluster (requires cluster_col to be set)
    subplot_border_colormap : str, default='colorblind'
        Colormap to use for border colors when subplot_border_color_by is set.
        Options: 'colorblind', 'tab10', 'viridis', etc.
    subplot_border_colors : dict, optional
        Custom color mapping for borders when using subplot_border_color_by.
        Example: {0: '#FF0000', 1: '#00FF00', 2: '#0000FF'}
    show_legend : bool, default=True
        Whether to show a legend mapping segment colors to their values.
        Legend appears OUTSIDE the subplot grid.
    legend_title : str, optional
        Title for the legend. Defaults to segment_color_by column name.
    legend_loc : str, default='right'
        Location for the legend. Options: 'right', 'bottom', or matplotlib location strings.
    legend_order : list, optional
        Custom order for legend items. If None, uses the order of keys in segment_colors dict
        (if provided), otherwise uses sorted order. Use this to match state_order from
        plot_representative_sequences.
    group_by : str, optional
        Column to use for ROW grouping in structured grid layout (e.g., 'mol').
        When specified along with cluster_col and n_per_cluster, creates a grid
        matching plot_representative_sequences layout:
        - Rows = unique values from group_by column
        - Columns = n_clusters * n_per_cluster
    cluster_col : str, optional
        Column to use for COLUMN grouping in structured grid layout (e.g., 'superwindow_cluster').
        Clusters are arranged left-to-right, with n_per_cluster tracks per cluster per row.
    n_per_cluster : int, optional
        Number of tracks to show per cluster per group (row).
        Similar to n_superwindows_per_cluster in plot_representative_sequences.
    cluster_order : list, optional
        Custom order for clusters. If None, uses sorted unique values.
    group_order : list, optional
        Custom order for groups (rows). If None, uses sorted unique values.
    random_seed : int, default=42
        Random seed for reproducible track selection.
    superwindow_ids : list, optional
        List of superwindow_ids in EXACT plotting order from plot_representative_sequences.
        When provided, skips random sampling and uses these IDs directly to match
        the exact order from plot_representative_sequences. Pass the `plotted_sw_ids`
        output from plot_representative_sequences.
    superwindow_id_col : str, default='superwindow_id'
        Column whose values match ``superwindow_ids`` (from ``plot_representative_sequences``).
        This is only the **join / lookup key** for which frames to draw; use ``cluster_col`` for
        cluster identity (e.g. ``superwindow_cluster_name``). Annotations can reference
        ``{superwindow_cluster_name}`` when that column exists on ``instant_df``.
        
    Returns
    -------
    dict
        Dictionary with keys: 'plotted_tracks', 'category_counts', 'total_tracks',
        'subplot_size_um', 'grid_dimensions', 'save_path', 'order_by_values', 
        'segment_color_map', 'box_color_map'
        When using structured layout, also includes: 'groups', 'clusters', 'n_per_cluster'
    """
    import matplotlib.pyplot as plt
    import numpy as np
    import random
    from matplotlib import cm

    # Auto-detect dataframe type and convert to pandas for compatibility
    try:
        import polars as pl
    except ImportError:
        pl = None

    is_polars = pl is not None and isinstance(instant_df, pl.DataFrame)

    # --- Memory: never materialize full instant_df as pandas when only a few
    # superwindows are plotted. Filtering by superwindow_id in Polars first
    # reduces rows from millions to thousands (fixes OOM on gallery_of_tracks_v5).
    sw_id_list = None
    if superwindow_ids is not None and len(superwindow_ids) > 0:
        sw_id_list = list(dict.fromkeys(superwindow_ids))  # preserve order not needed for is_in

    if is_polars:
        df_pl = instant_df
        if sw_id_list is not None and superwindow_id_col in df_pl.columns:
            n_before = df_pl.height
            df_pl = df_pl.filter(pl.col(superwindow_id_col).is_in(sw_id_list))
            print(
                f"gallery_of_tracks_v5: filtered Polars instant_df "
                f"{n_before:,} -> {df_pl.height:,} rows ({superwindow_id_col} in {len(sw_id_list)} ids)"
            )
        elif sw_id_list is not None and superwindow_id_col not in df_pl.columns:
            raise ValueError(
                f"superwindow_ids provided but '{superwindow_id_col}' not in instant_df. "
                "Join superwindow_id onto instant rows before the gallery, or pass the correct column."
            )
        df = df_pl.to_pandas()
    else:
        if sw_id_list is not None and superwindow_id_col in instant_df.columns:
            n_before = len(instant_df)
            df = instant_df.loc[instant_df[superwindow_id_col].isin(sw_id_list)].copy()
            print(
                f"gallery_of_tracks_v5: filtered pandas instant_df "
                f"{n_before:,} -> {len(df):,} rows ({superwindow_id_col} in {len(sw_id_list)} ids)"
            )
        else:
            df = instant_df.copy()

    # Ensure required columns exist
    required_cols = ['unique_id', 'x_um', 'y_um', 'frame']
    missing_cols = [col for col in required_cols if col not in df.columns]
    if missing_cols:
        raise ValueError(f"Missing required columns: {missing_cols}")

    if order_by not in df.columns:
        raise ValueError(f"Order column '{order_by}' not found in dataframe")
    
    if segment_color_by not in df.columns:
        raise ValueError(f"Segment color column '{segment_color_by}' not found in dataframe")

    # Handle text_color (single variable for all text colors)
    # If text_color is not specified, fall back to annotation_color for backwards compatibility
    if text_color is None:
        text_color = annotation_color
    
    # Set subplot_border_color to text_color if not specified
    if subplot_border_color is None:
        subplot_border_color = text_color

    # Set up border color mapping (for subplot borders colored by cluster)
    border_color_map = {}

    # Get order_by categories
    order_by_values = order if order else sorted(df[order_by].dropna().unique())
    print(f"Order by '{order_by}': {len(order_by_values)} unique values")

    # Set up box color mapping (for order_by values)
    box_color_map = {}
    if draw_box:
        if box_colors is not None:
            box_color_map = box_colors
        elif box_colormap == "colorblind":
            colorblind_colors = [
                '#0173B2', '#DE8F05', '#029E73', '#CC78BC', '#CA9161',
                '#FBAFE4', '#949494', '#ECE133', '#56B4E9', '#D55E00'
            ]
            box_color_map = {val: colorblind_colors[i % len(colorblind_colors)] 
                            for i, val in enumerate(order_by_values)}
        else:
            cmap = plt.get_cmap(box_colormap, len(order_by_values))
            box_color_map = {val: cmap(i / max(1, len(order_by_values) - 1)) 
                            for i, val in enumerate(order_by_values)}
        print(f"Box colors for {len(order_by_values)} order_by values")

    # Get all unique segment colors
    all_segment_values = sorted(df[segment_color_by].dropna().unique())
    print(f"Segment color by '{segment_color_by}': {all_segment_values}")

    # Set up segment color mapping
    if segment_colors is not None:
        segment_color_map = segment_colors
    elif segment_colormap == "colorblind":
        colorblind_colors = [
            '#0173B2', '#DE8F05', '#029E73', '#CC78BC', '#CA9161',
            '#FBAFE4', '#949494', '#ECE133', '#56B4E9', '#D55E00'
        ]
        segment_color_map = {val: colorblind_colors[i % len(colorblind_colors)] 
                            for i, val in enumerate(all_segment_values)}
    else:
        cmap = plt.get_cmap(segment_colormap, len(all_segment_values))
        segment_color_map = {val: cmap(i / len(all_segment_values)) 
                            for i, val in enumerate(all_segment_values)}

    # Set random seed for reproducibility
    random.seed(random_seed)
    np.random.seed(random_seed)
    
    # Check if using structured grid layout (matching plot_representative_sequences)
    use_structured_layout = (group_by is not None and cluster_col is not None and n_per_cluster is not None)
    
    all_track_segments = []
    track_info = []
    grid_position_map = {}  # Maps (row_idx, col_idx) to track info for structured layout
    
    if use_structured_layout:
        # ========== STRUCTURED GRID LAYOUT MODE ==========
        # Rows = groups (e.g., mol values)
        # Columns = clusters * n_per_cluster (same as plot_representative_sequences)
        
        if group_by not in df.columns:
            raise ValueError(f"group_by column '{group_by}' not found in dataframe")
        if cluster_col not in df.columns:
            raise ValueError(f"cluster_col column '{cluster_col}' not found in dataframe")
        
        # Get groups and clusters
        groups = group_order if group_order else sorted(df[group_by].dropna().unique())
        clusters = cluster_order if cluster_order else sorted(df[cluster_col].dropna().unique())
        n_clusters = len(clusters)
        
        print(f"\n=== STRUCTURED GRID LAYOUT (matching plot_representative_sequences) ===")
        print(f"Groups (rows): {groups}")
        print(f"Clusters (cols): {clusters}")
        print(f"Tracks per cluster per group: {n_per_cluster}")
        
        # Calculate grid dimensions: rows = groups, cols = clusters * n_per_cluster
        grid_rows = len(groups)
        grid_cols = n_clusters * n_per_cluster
        
        print(f"Grid layout: {grid_rows} rows × {grid_cols} columns")

        _grid_slots = int(grid_rows * grid_cols)
        
        # Check if using exact superwindow_ids from plot_representative_sequences
        use_exact_order = superwindow_ids is not None and len(superwindow_ids) > 0
        
        if use_exact_order:
            # Must be row-major: same order as plot_representative_sequences (one ID per subplot, None = empty)
            _sw = list(superwindow_ids)
            if len(_sw) != _grid_slots:
                if len(_sw) < _grid_slots:
                    print(
                        f"⚠️ len(superwindow_ids)={len(_sw)} < grid slots {_grid_slots}; "
                        f"padding with None. Re-run plot_representative_sequences() so the list "
                        f"matches the gallery grid (one entry per cell including Nones)."
                    )
                    _sw.extend([None] * (_grid_slots - len(_sw)))
                else:
                    raise ValueError(
                        f"len(superwindow_ids)={len(_sw)} exceeds grid slots {_grid_slots}. "
                        f"Trim superwindow_ids or match group_by / cluster_order / n_per_cluster to the sequence plot."
                    )
                superwindow_ids = _sw
            print(f"✅ Using EXACT order from plot_representative_sequences ({len(superwindow_ids)} slots = grid)")
            # Order: [group0_cluster0_ex0 ... exK, group0_cluster1_..., ..., group1_...]
            sw_idx = 0  # Index into superwindow_ids list

        # O(1) lookup per superwindow after filter (avoids repeated full-frame boolean masks)
        if use_exact_order and superwindow_id_col in df.columns:
            _tracks_by_sw = {
                k: g.sort_values("frame")
                for k, g in df.groupby(superwindow_id_col, sort=False)
            }
        else:
            _tracks_by_sw = None
        
        # Collect tracks in structured order (matching plot_representative_sequences)
        for group_idx, group_val in enumerate(groups):
            group_data = df[df[group_by] == group_val]
            
            col_idx = 0
            for cluster_id in clusters:
                cluster_data = group_data[group_data[cluster_col] == cluster_id]
                
                # Collect track segments for this cluster
                for ex_idx in range(n_per_cluster):
                    if use_exact_order:
                        # Use EXACT superwindow_id from plot_representative_sequences
                        if sw_idx < len(superwindow_ids):
                            target_sw_id = superwindow_ids[sw_idx]
                            sw_idx += 1

                            # Grid-aligned placeholder from plot_representative_sequences (no example in that slot)
                            if target_sw_id is None:
                                all_track_segments.append(None)
                                track_info.append((cluster_id, None, 0))
                                grid_position_map[(group_idx, col_idx)] = len(all_track_segments) - 1
                                col_idx += 1
                                continue
                            
                            # Find track data for this superwindow_id
                            if _tracks_by_sw is not None:
                                track_data = _tracks_by_sw.get(target_sw_id)
                                if track_data is None:
                                    track_data = df.iloc[0:0]
                            elif superwindow_id_col in df.columns:
                                track_data = df[df[superwindow_id_col] == target_sw_id].sort_values('frame')
                            else:
                                # Fall back to unique_id if superwindow_id_col not found
                                track_data = df[df['unique_id'] == target_sw_id].sort_values('frame')
                            
                            if len(track_data) == 0:
                                all_track_segments.append(None)
                                track_info.append((cluster_id, target_sw_id, 0))
                                grid_position_map[(group_idx, col_idx)] = len(all_track_segments) - 1
                                col_idx += 1
                                continue
                            
                            # Get cluster_id from the track data for border coloring
                            if cluster_col in track_data.columns:
                                actual_cluster = track_data[cluster_col].iloc[0]
                            else:
                                actual_cluster = cluster_id
                            
                            # When using superwindow_ids, use ALL frames for that superwindow
                            # (NO random sampling - this ensures exact alignment with sequences!)
                            track_segment = track_data  # Use ALL frames belonging to this superwindow_id
                            
                            if len(track_segment) >= 10:
                                all_track_segments.append(track_segment)
                                track_info.append((actual_cluster, target_sw_id, len(track_segment)))
                            else:
                                all_track_segments.append(None)
                                track_info.append((actual_cluster, target_sw_id, 0))
                        else:
                            # No more superwindow_ids, fill with empty (keep cluster for border alignment)
                            all_track_segments.append(None)
                            track_info.append((cluster_id, None, 0))
                        
                        grid_position_map[(group_idx, col_idx)] = len(all_track_segments) - 1
                        col_idx += 1
                    
                    else:
                        # SAMPLING MODE (original behavior when superwindow_ids not provided)
                        if ex_idx == 0:
                            # Only do this once per cluster
                            if len(cluster_data) == 0:
                                # Fill all slots for this cluster with empty (keep cluster for borders)
                                for _ in range(n_per_cluster):
                                    all_track_segments.append(None)
                                    track_info.append((cluster_id, None, 0))
                                    grid_position_map[(group_idx, col_idx)] = len(all_track_segments) - 1
                                    col_idx += 1
                                break  # Skip remaining ex_idx iterations
                            
                            # Sample tracks
                            unique_ids = cluster_data['unique_id'].unique()
                            n_available = len(unique_ids)
                            n_to_sample = min(n_per_cluster, n_available)
                            
                            if n_to_sample > 0:
                                unique_ids_df = pd.DataFrame({'unique_id': unique_ids})
                                sampled_df = unique_ids_df.sample(n=n_to_sample, random_state=42)
                                selected_ids = sampled_df['unique_id'].tolist()
                            else:
                                selected_ids = []
                        
                        if ex_idx < len(selected_ids):
                            unique_id = selected_ids[ex_idx]
                            track_data = cluster_data[cluster_data['unique_id'] == unique_id].sort_values('frame')
                            
                            if len(track_data) >= track_length_frames:
                                max_start = len(track_data) - track_length_frames
                                start_idx = random.randint(0, max_start) if max_start > 0 else 0
                                track_segment = track_data.iloc[start_idx:start_idx + track_length_frames]
                            else:
                                track_segment = track_data
                            
                            if len(track_segment) >= 10:
                                all_track_segments.append(track_segment)
                                track_info.append((cluster_id, unique_id, len(track_segment)))
                            else:
                                all_track_segments.append(None)
                                track_info.append((cluster_id, unique_id, 0))
                        else:
                            # Not enough tracks for this slot
                            all_track_segments.append(None)
                            track_info.append((cluster_id, None, 0))
                        
                        grid_position_map[(group_idx, col_idx)] = len(all_track_segments) - 1
                        col_idx += 1
        
        # Update box_color_map to use cluster values (DEPRECATED - use border_color_map)
        if draw_box:
            if box_colors is not None:
                box_color_map = box_colors
            elif box_colormap == "colorblind":
                colorblind_colors = [
                    '#0173B2', '#DE8F05', '#029E73', '#CC78BC', '#CA9161',
                    '#FBAFE4', '#949494', '#ECE133', '#56B4E9', '#D55E00'
                ]
                box_color_map = {val: colorblind_colors[i % len(colorblind_colors)] 
                                for i, val in enumerate(clusters)}
            else:
                cmap = plt.get_cmap(box_colormap, len(clusters))
                box_color_map = {val: cmap(i / max(1, len(clusters) - 1)) 
                                for i, val in enumerate(clusters)}
            print(f"Box colors based on clusters: {list(box_color_map.keys())}")
        
        # Set up border_color_map for subplot borders colored by cluster
        if show_subplot_border and subplot_border_color_by == 'cluster':
            if subplot_border_colors is not None:
                border_color_map = subplot_border_colors
            elif subplot_border_colormap == "colorblind":
                colorblind_colors = [
                    '#0173B2', '#DE8F05', '#029E73', '#CC78BC', '#CA9161',
                    '#FBAFE4', '#949494', '#ECE133', '#56B4E9', '#D55E00'
                ]
                border_color_map = {val: colorblind_colors[i % len(colorblind_colors)] 
                                   for i, val in enumerate(clusters)}
            else:
                cmap = plt.get_cmap(subplot_border_colormap, len(clusters))
                border_color_map = {val: cmap(i / max(1, len(clusters) - 1)) 
                                   for i, val in enumerate(clusters)}
            print(f"Border colors based on clusters: {list(border_color_map.keys())}")
        
        valid_tracks = sum(1 for t in all_track_segments if t is not None)
        print(f"Collected {valid_tracks} valid tracks (out of {len(all_track_segments)} grid slots)")
        
    else:
        # ========== ORIGINAL FLAT LAYOUT MODE ==========
        for order_val in order_by_values:
            # Filter to this order_by value (e.g., superwindow_id)
            order_df = df[df[order_by] == order_val]
            
            if len(order_df) == 0:
                continue
            
            # Get unique tracks in this order_by value
            unique_ids = order_df['unique_id'].unique()
            
            # Sample if needed
            selected_ids = random.sample(list(unique_ids), min(num_tracks, len(unique_ids)))

            for unique_id in selected_ids:
                track_data = order_df[order_df['unique_id'] == unique_id].sort_values('frame')

                if len(track_data) >= track_length_frames:
                    max_start = len(track_data) - track_length_frames
                    start_idx = random.randint(0, max_start) if max_start > 0 else 0
                    track_segment = track_data.iloc[start_idx:start_idx + track_length_frames]
                else:
                    track_segment = track_data

                if len(track_segment) >= 10:
                    all_track_segments.append(track_segment)
                    track_info.append((order_val, unique_id, len(track_segment)))

        if not all_track_segments:
            raise ValueError("No valid track segments found")

        print(f"Collected {len(all_track_segments)} tracks total")

        # Calculate grid layout for flat mode
        total_tracks = len(all_track_segments)
        if grid_cols is None:
            grid_cols = int(np.ceil(np.sqrt(total_tracks)))
        grid_rows = int(np.ceil(total_tracks / grid_cols))
        print(f"Grid layout: {grid_rows} rows × {grid_cols} columns")

    # Calculate subplot size
    valid_segments = [s for s in all_track_segments if s is not None]
    if not valid_segments:
        raise ValueError("No valid track segments found")
    
    if subplot_size_um is not None:
        subplot_size = subplot_size_um
        print(f"Using manual subplot size: {subplot_size:.2f} μm")
    else:
        max_extent = 0
        for segment in valid_segments:
            x_range = segment['x_um'].max() - segment['x_um'].min()
            y_range = segment['y_um'].max() - segment['y_um'].min()
            extent = max(x_range, y_range)
            max_extent = max(max_extent, extent)
        subplot_size = max_extent * spacing_factor
        print(f"Using calculated subplot size: {subplot_size:.2f} μm")

    # Dynamic figsize
    if figsize is None:
        subplot_size_inches = 2.0
        figsize = (grid_cols * subplot_size_inches, grid_rows * subplot_size_inches)
        print(f"Using dynamic figsize: {figsize}")

    # Create figure
    figure_background = "none" if transparent_background else "white"
    axis_background = (0, 0, 0, 0) if transparent_background else "white"

    fig, axes = plt.subplots(
        grid_rows, grid_cols,
        figsize=figsize,
        facecolor=figure_background,
        squeeze=False  # Always return 2D array for structured layout
    )
    
    # Keep 2D axes reference for structured layout
    axes_2d = axes
    
    # Also create 1D axes list for iteration
    axes_flat = np.array(axes).flatten()

    fig.subplots_adjust(wspace=0.02, hspace=0.02)

    plotted_tracks = []

    # --- Annotation setup ---
    def _make_annotation_text(segment, meta):
        if not show_annotations:
            return None

        # Empty subplot: no segment rows — still format annotation from meta (grid alignment)
        if segment is None:
            if callable(annotation):
                try:
                    return str(annotation(segment, meta))
                except Exception as e:
                    return f"(annotation error: {e})"
            if isinstance(annotation, str):
                if annotation == "default":
                    return ""
                try:
                    return annotation.format(**meta)
                except KeyError as e:
                    return f"(missing {e.args[0]} in annotation)"
                except Exception as e:
                    return f"(annotation error: {e})"
            return None

        if callable(annotation):
            try:
                return str(annotation(segment, meta))
            except Exception as e:
                return f"(annotation error: {e})"

        if isinstance(annotation, (list, tuple)):
            vals = []
            for col in annotation:
                if col in segment.columns:
                    val = segment[col].iloc[0]
                else:
                    val = meta.get(col, None)
                vals.append(f"{col}={val}")
            return " | ".join(vals)

        if isinstance(annotation, str):
            if annotation == "default":
                return f"{meta['order_val']}\n{meta['unique_id']}"
            ctx = dict(meta)
            for col in segment.columns:
                if col not in ctx:
                    try:
                        ctx[col] = segment[col].iloc[0]
                    except Exception:
                        pass
            try:
                return annotation.format(**ctx)
            except KeyError as e:
                return f"(missing {e.args[0]} in annotation)"
            except Exception as e:
                return f"(annotation error: {e})"

        return f"{meta['order_val']}\n{meta['unique_id']}"

    # Plot each track with WITHIN-TRACK segment coloring
    for idx, (segment, (order_val, unique_id, segment_length)) in enumerate(zip(all_track_segments, track_info)):
        if idx >= len(axes_flat):
            break

        ax = axes_flat[idx]
        
        # Handle empty/None segments: keep axes as visible boxes (aligned grid, cluster border)
        if segment is None or segment_length == 0:
            ax.set_xticks([])
            ax.set_yticks([])
            ax.set_facecolor(axis_background)
            if show_subplot_border and subplot_border_color_by == "cluster" and order_val is not None:
                border_color = border_color_map.get(order_val, subplot_border_color or text_color)
                for spine in ax.spines.values():
                    spine.set_visible(True)
                    spine.set_color(border_color)
                    spine.set_linewidth(subplot_border_linewidth)
            elif show_subplot_border:
                for spine in ax.spines.values():
                    spine.set_visible(True)
                    spine.set_color(subplot_border_color or text_color)
                    spine.set_linewidth(subplot_border_linewidth)
            else:
                for spine in ax.spines.values():
                    spine.set_visible(False)
            ax.set_xlim(0, 1)
            ax.set_ylim(0, 1)
            ax.set_aspect("equal")
            meta_empty = {
                "order_val": order_val,
                "unique_id": unique_id,
                "segment_length": 0,
                "start_frame": None,
                "end_frame": None,
                "window_uid": None,
                "window_uids": None,
                "superwindow_id": unique_id,
            }
            if use_structured_layout and cluster_col is not None:
                meta_empty[cluster_col] = order_val
            ann_text = _make_annotation_text(None, meta_empty)
            if show_annotations and ann_text:
                ax.text(
                    0.5,
                    -0.12,
                    ann_text,
                    transform=ax.transAxes,
                    ha="center",
                    va="top",
                    fontsize=text_size,
                    color=text_color,
                    style="italic",
                )
            continue

        x_coords = segment['x_um'].values
        y_coords = segment['y_um'].values
        segment_values = segment[segment_color_by].values

        x_center = x_coords.mean()
        y_center = y_coords.mean()

        # Plot segment-by-segment with different colors
        # Group consecutive frames by their segment_color_by value
        i = 0
        while i < len(x_coords) - 1:
            current_val = segment_values[i]
            color = segment_color_map.get(current_val, 'gray')
            
            # Find the end of this contiguous segment
            j = i + 1
            while j < len(segment_values) and segment_values[j] == current_val:
                j += 1
            
            # Plot this segment (include one point overlap for continuity)
            end_idx = min(j + 1, len(x_coords))
            ax.plot(x_coords[i:end_idx], y_coords[i:end_idx], 
                   color=color, linewidth=line_width, alpha=0.8)
            
            i = j

        half_size = subplot_size / 2
        ax.set_xlim(x_center - half_size, x_center + half_size)
        ax.set_ylim(y_center - half_size, y_center + half_size)
        ax.set_aspect('equal')

        # Hide ticks and labels but KEEP SPINES AVAILABLE for borders
        ax.set_xticks([])
        ax.set_yticks([])
        ax.set_xticklabels([])
        ax.set_yticklabels([])
        ax.set_facecolor(axis_background)

        # Configure subplot borders
        if show_subplot_border:
            # Determine border color for this subplot
            if subplot_border_color_by == 'cluster' and order_val is not None:
                # Color by cluster - order_val contains the cluster ID in structured mode
                border_color = border_color_map.get(order_val, subplot_border_color or text_color)
            else:
                # Solid color for all borders
                border_color = subplot_border_color or text_color
            
            # Make spines visible with the determined color
            for spine in ax.spines.values():
                spine.set_visible(True)
                spine.set_color(border_color)
                spine.set_linewidth(subplot_border_linewidth)
        else:
            # Hide all spines when borders are disabled
            for spine in ax.spines.values():
                spine.set_visible(False)
        
        # Legacy draw_box support (DEPRECATED - use show_subplot_border with subplot_border_color_by='cluster')
        if draw_box and not show_subplot_border and order_val in box_color_map:
            box_color = box_color_map[order_val]
            for spine in ax.spines.values():
                spine.set_visible(True)
                spine.set_color(box_color)
                spine.set_linewidth(box_linewidth)

        # Build meta for annotation
        start_frame = int(segment['frame'].min())
        end_frame = int(segment['frame'].max())
        
        window_uid = None
        window_uids = None
        if 'window_uid' in segment.columns:
            vals = segment['window_uid'].dropna().astype(str)
            if len(vals) > 0:
                window_uids = sorted(vals.unique())
                window_uid = ", ".join(window_uids)
        
        # Get superwindow_id if available
        superwindow_id = None
        if 'superwindow_id' in segment.columns:
            superwindow_id = segment['superwindow_id'].iloc[0]

        # Named cluster (e.g. after merging HDBSCAN ids); same as cluster_col when propagated to instant_df
        superwindow_cluster_name = None
        if 'superwindow_cluster_name' in segment.columns:
            superwindow_cluster_name = segment['superwindow_cluster_name'].iloc[0]

        meta = {
            'order_val': order_val,
            'unique_id': unique_id,
            'segment_length': int(segment_length),
            'start_frame': start_frame,
            'end_frame': end_frame,
            'window_uid': window_uid,
            'window_uids': window_uids,
            'superwindow_id': superwindow_id,
            'superwindow_cluster_name': superwindow_cluster_name,
        }

        ann_text = _make_annotation_text(segment, meta)
        if show_annotations and ann_text:
            # Place annotation BELOW the subplot (like plot_representative_sequences)
            ax.text(
                0.5, -0.12, ann_text,
                transform=ax.transAxes,
                ha='center', va='top',
                fontsize=text_size,
                color=text_color,
                style='italic'  # Match plot_representative_sequences style
            )

        plotted_tracks.append({
            'order_val': order_val,
            'unique_id': unique_id,
            'segment_length': segment_length,
            'x_center': x_center,
            'y_center': y_center,
            'subplot_index': idx,
            'start_frame': start_frame,
            'end_frame': end_frame,
            'window_uid': window_uid
        })

    # Hide any unused subplots
    for idx in range(len(all_track_segments), len(axes_flat)):
        axes_flat[idx].axis('off')
        axes_flat[idx].set_facecolor(axis_background)

    # Add row labels and column headers for STRUCTURED LAYOUT
    if use_structured_layout:
        groups = group_order if group_order else sorted(df[group_by].dropna().unique())
        clusters = cluster_order if cluster_order else sorted(df[cluster_col].dropna().unique())
        n_clusters = len(clusters)
        
        # Add column headers (cluster labels) - on first row only
        for cluster_idx, cluster_id in enumerate(clusters):
            # Position at the center of each cluster's columns
            center_col = cluster_idx * n_per_cluster + n_per_cluster // 2
            ax = axes_2d[0, center_col]
            ax.set_title(f'Cluster {cluster_id}', fontsize=text_size + 2, fontweight='bold',
                        color=text_color, pad=5)
        
        # Add row labels (group names) - on first column only
        for group_idx, group_val in enumerate(groups):
            ax = axes_2d[group_idx, 0]
            ax.set_ylabel(f'{group_val}', fontsize=text_size + 2, fontweight='bold',
                         color=text_color, rotation=90, labelpad=10)

    # Add scale bar to bottom-right plotted subplot
    valid_indices = [i for i, s in enumerate(all_track_segments) if s is not None]
    if show_scale_bar and len(valid_indices) > 0:
        if scale_bar_length_um is None:
            scale_bar_length_um = subplot_size
        
        last_plot_idx = valid_indices[-1]
        scale_ax = axes_flat[last_plot_idx]
        
        xlim = scale_ax.get_xlim()
        ylim = scale_ax.get_ylim()
        
        padding_fraction = 0.1
        x_padding = (xlim[1] - xlim[0]) * padding_fraction
        y_padding = (ylim[1] - ylim[0]) * padding_fraction
        
        scale_bar_x_end = xlim[1] - x_padding
        scale_bar_x_start = scale_bar_x_end - scale_bar_length_um
        scale_bar_y = ylim[0] + y_padding
        
        scale_ax.plot(
            [scale_bar_x_start, scale_bar_x_end],
            [scale_bar_y, scale_bar_y],
            color=scale_bar_color,
            linewidth=scale_bar_linewidth,
            solid_capstyle='butt'
        )
        
        cap_height = (ylim[1] - ylim[0]) * 0.02
        scale_ax.plot(
            [scale_bar_x_start, scale_bar_x_start],
            [scale_bar_y - cap_height, scale_bar_y + cap_height],
            color=scale_bar_color,
            linewidth=scale_bar_linewidth * 0.7
        )
        scale_ax.plot(
            [scale_bar_x_end, scale_bar_x_end],
            [scale_bar_y - cap_height, scale_bar_y + cap_height],
            color=scale_bar_color,
            linewidth=scale_bar_linewidth * 0.7
        )
        
        scale_ax.text(
            (scale_bar_x_start + scale_bar_x_end) / 2,
            scale_bar_y + y_padding * 0.5,
            f'{scale_bar_length_um:.1f} μm',
            ha='center',
            va='bottom',
            color=scale_bar_color,
            fontsize=text_size,
            fontweight='bold'
        )

    # Count tracks with data only (empty grid slots do not inflate cluster totals)
    category_counts = {}
    for seg, (order_val, _, _) in zip(all_track_segments, track_info):
        if seg is not None and order_val is not None:
            category_counts[order_val] = category_counts.get(order_val, 0) + 1

    # Title
    valid_count = sum(1 for s in all_track_segments if s is not None)
    if use_structured_layout:
        groups = group_order if group_order else sorted(df[group_by].dropna().unique())
        clusters = cluster_order if cluster_order else sorted(df[cluster_col].dropna().unique())
        title_text = f"Gallery of Tracks (rows={group_by}, cols={cluster_col}, colored by {segment_color_by})\n"
        title_text += f"{valid_count} tracks ({len(groups)} groups × {len(clusters)} clusters × {n_per_cluster} per)"
    else:
        title_text = f"Gallery of Tracks (ordered by {order_by}, colored by {segment_color_by})\n"
        title_text += f"{valid_count} tracks"

    fig.suptitle(
        title_text,
        fontsize=text_size + 2,
        color=text_color,
        y=0.98
    )

    # Add legend for segment colors (OUTSIDE the subplot grid)
    if show_legend and segment_color_map:
        from matplotlib.patches import Patch
        
        # Determine legend order:
        # 1. Use legend_order if provided explicitly
        # 2. Otherwise, use the order of keys in segment_colors dict (if user provided it)
        # 3. Otherwise, use sorted order
        if legend_order is not None:
            ordered_values = [v for v in legend_order if v in segment_color_map]
        elif segment_colors is not None:
            # Use the order from the user-provided segment_colors dict (preserves insertion order)
            ordered_values = list(segment_colors.keys())
        else:
            # Fall back to sorted order
            ordered_values = sorted(segment_color_map.keys(), key=lambda x: str(x))
        
        # Create legend handles in the determined order
        legend_handles = []
        for value in ordered_values:
            if value in segment_color_map:
                color = segment_color_map[value]
                patch = Patch(facecolor=color, edgecolor='none', label=str(value))
                legend_handles.append(patch)
        
        # Determine legend title
        leg_title = legend_title if legend_title else segment_color_by
        
        # Position legend outside the subplots
        if legend_loc == 'right':
            legend = fig.legend(
                handles=legend_handles,
                title=leg_title,
                loc='center left',
                bbox_to_anchor=(1.01, 0.5),
                frameon=False,
                fontsize=text_size,
                title_fontsize=text_size + 1
            )
        elif legend_loc == 'bottom':
            legend = fig.legend(
                handles=legend_handles,
                title=leg_title,
                loc='upper center',
                bbox_to_anchor=(0.5, -0.02),
                ncol=len(legend_handles),
                frameon=False,
                fontsize=text_size,
                title_fontsize=text_size + 1
            )
        else:
            # Use matplotlib's built-in location string
            legend = fig.legend(
                handles=legend_handles,
                title=leg_title,
                loc=legend_loc,
                frameon=False,
                fontsize=text_size,
                title_fontsize=text_size + 1
            )
        
        # Set legend text color
        legend.get_title().set_color(text_color)
        for text in legend.get_texts():
            text.set_color(text_color)

    # Save
    if save_path is None:
        if use_structured_layout:
            save_path = f"gallery_of_tracks_v5_{group_by}_{cluster_col}_{segment_color_by}.{export_format}"
        else:
            save_path = f"gallery_of_tracks_v5_{order_by}_{segment_color_by}.{export_format}"
    else:
        save_path = os.path.abspath(os.path.expanduser(str(save_path)))
        _save_dir = os.path.dirname(save_path)
        if _save_dir:
            os.makedirs(_save_dir, exist_ok=True)

    plt.savefig(
        save_path,
        format=export_format,
        dpi=dpi,
        bbox_inches='tight',
        transparent=transparent_background,
        facecolor=figure_background
    )
    print(f"✅ gallery_of_tracks_v5 saved: {save_path}")

    if show_plot:
        plt.show()
    else:
        plt.close()

    # Build return dictionary
    result = {
        'plotted_tracks': plotted_tracks,
        'category_counts': category_counts,
        'total_tracks': valid_count,
        'subplot_size_um': subplot_size,
        'grid_dimensions': (grid_rows, grid_cols),
        'save_path': save_path,
        'order_by_values': order_by_values,
        'segment_color_map': segment_color_map,
        'box_color_map': box_color_map
    }
    
    # Add structured layout info if applicable
    if use_structured_layout:
        groups = group_order if group_order else sorted(df[group_by].dropna().unique())
        clusters = cluster_order if cluster_order else sorted(df[cluster_col].dropna().unique())
        result['groups'] = groups
        result['clusters'] = clusters
        result['n_per_cluster'] = n_per_cluster
        result['group_by'] = group_by
        result['cluster_col'] = cluster_col
    
    return result


def plot_stacked_bar_percentage(
    df,
    x_category,
    stack_category,
    unique_id_col='unique_id',
    x_order=None,
    stack_order=None,
    palette='colorblind',
    figsize=(10, 6),
    title=None,
    xlabel=None,
    ylabel='Percentage (%)',
    show_percentages=True,
    percentage_threshold=5.0,
    font_size=12,
    transparent_background=False,
    line_color='black',
    grid=True,
    save_path=None,
    export_format='png',
    return_svg=False,
    show_plot=True,
    dpi=300,
):
    """
    Create a 100% stacked bar chart showing distribution of stack_category within each x_category.
    
    Automatically handles counting unique tracks and calculating percentages.
    
    Parameters
    ----------
    df : pd.DataFrame or pl.DataFrame
        Input dataframe (accepts both pandas and polars).
    x_category : str
        Column name for x-axis categories (e.g., 'mol', 'condition').
    stack_category : str
        Column name for stacking categories (e.g., 'gate_name', 'cluster_id').
    unique_id_col : str, optional
        Column name containing unique track IDs. Default is 'unique_id'.
    x_order : list, optional
        Order of categories on x-axis. Default is None (sorted).
    stack_order : list, optional
        Order of stacking categories (bottom to top). Default is None (sorted).
    palette : str or list, optional
        Color palette. Can be 'colorblind', 'raiders'/'raiders_colors2', seaborn palette name,
        or list of colors. Default is 'colorblind'.
    figsize : tuple, optional
        Figure size (width, height). Default is (10, 6).
    title : str, optional
        Plot title. Auto-generated if None.
    xlabel : str, optional
        X-axis label. Uses x_category if None.
    ylabel : str, optional
        Y-axis label. Default is 'Percentage (%)'.
    show_percentages : bool, optional
        Whether to show percentage labels on bars. Default is True.
    percentage_threshold : float, optional
        Minimum percentage to show label (avoids cluttering). Default is 5.0.
    font_size : int, optional
        Base font size. Default is 12.
    transparent_background : bool, optional
        Transparent background. Default is False.
    line_color : str, optional
        Color for text and lines. Default is 'black'.
    grid : bool, optional
        Whether to show y-axis gridlines. Default is True.
    save_path : str, optional
        Path to save figure. Default is None (no save).
    export_format : str, optional
        Export format ('png' or 'svg'). Default is 'png'.
    return_svg : bool, optional
        Return SVG string if export_format='svg'. Default is False.
    show_plot : bool, optional
        Whether to display plot. Default is True.
    dpi : int, optional
        Resolution for saved figure. Default is 300.
    
    Returns
    -------
    fig : matplotlib.figure.Figure
        Figure object.
    ax : matplotlib.axes.Axes
        Axes object.
    summary_df : pd.DataFrame
        Summary dataframe with percentages and counts.
    svg_data : str (optional)
        SVG string if return_svg=True and export_format='svg'.
    
    Examples
    --------
    >>> # Basic usage
    >>> fig, ax, summary = spt.plot_stacked_bar_percentage(
    ...     df, x_category='mol', stack_category='gate_name'
    ... )
    
    >>> # With custom colors and order
    >>> fig, ax, summary = spt.plot_stacked_bar_percentage(
    ...     df,
    ...     x_category='condition',
    ...     stack_category='cluster_id',
    ...     stack_order=['0', '1', '2', '3'],
    ...     palette=['#0173B2', '#DE8F05', '#029E73', '#CC78BC']
    ... )
    """
    # Detect and convert Polars DataFrames
    try:
        import polars as pl
        is_polars_input = isinstance(df, pl.DataFrame)
    except ImportError:
        is_polars_input = False
    
    if is_polars_input:
        # Use polars for efficient computation
        # Drop rows missing keys so group_by does not create null-key buckets
        df_work = df.filter(
            pl.col(x_category).is_not_null()
            & pl.col(stack_category).is_not_null()
            & pl.col(unique_id_col).is_not_null()
        )
        # Get unique tracks per category combination
        counts = (
            df_work
            .group_by([x_category, stack_category, unique_id_col])
            .agg(pl.len().alias('n_windows'))
            .group_by([x_category, stack_category])
            .agg([
                pl.col(unique_id_col).n_unique().alias('n_tracks'),
                pl.col('n_windows').sum().alias('total_windows')
            ])
        )
        
        # Calculate totals per x_category
        totals = (
            counts
            .group_by(x_category)
            .agg(pl.col('n_tracks').sum().alias('total_tracks'))
        )
        
        # Join and calculate percentages
        summary_df = (
            counts
            .join(totals, on=x_category, how='left')
            .with_columns([
                (pl.col('n_tracks') / pl.col('total_tracks') * 100).alias('percentage')
            ])
            .sort([x_category, stack_category])
            .to_pandas()
        )
    else:
        # Use pandas
        df_work = df.dropna(subset=[x_category, stack_category, unique_id_col])
        # Get unique tracks per category combination
        counts = (
            df_work.groupby([x_category, stack_category])[unique_id_col]
            .nunique()
            .reset_index()
            .rename(columns={unique_id_col: 'n_tracks'})
        )
        
        # Calculate totals per x_category
        totals = (
            counts.groupby(x_category)['n_tracks']
            .sum()
            .reset_index()
            .rename(columns={'n_tracks': 'total_tracks'})
        )
        
        # Join and calculate percentages
        summary_df = counts.merge(totals, on=x_category)
        summary_df['percentage'] = (summary_df['n_tracks'] / summary_df['total_tracks'] * 100)
        summary_df = summary_df.sort_values([x_category, stack_category])

    summary_df = summary_df.dropna(subset=[x_category, stack_category])
    summary_df = summary_df.drop_duplicates(subset=[x_category, stack_category])

    # Determine orders
    if x_order is None:
        x_order = sorted(summary_df[x_category].unique())
    if stack_order is None:
        stack_order = sorted(summary_df[stack_category].unique())
    
    # Get colors
    if palette == 'colorblind':
        colors = [
            '#0173B2', '#DE8F05', '#029E73', '#CC78BC', '#CA9161',
            '#FBAFE4', '#949494', '#ECE133', '#56B4E9', '#D55E00'
        ]
    elif palette == 'raiders' or palette == 'raiders_colors2':
        colors = ['#ed1e24', '#DE8F05', '#6cc176', '#95d6d7']
    elif isinstance(palette, (list, tuple)):
        colors = palette
    else:
        # Try seaborn palette
        try:
            import seaborn as sns
            colors = sns.color_palette(palette, n_colors=len(stack_order))
        except:
            colors = plt.cm.tab10(np.linspace(0, 1, len(stack_order)))
    
    # Ensure enough colors
    while len(colors) < len(stack_order):
        colors = colors * 2
    colors = colors[:len(stack_order)]
    
    # Create figure
    fig, ax = plt.subplots(figsize=figsize)
    
    if transparent_background:
        fig.patch.set_facecolor('none')
        ax.set_facecolor((0, 0, 0, 0))
    
    # Prepare data for stacking
    x_pos = np.arange(len(x_order))
    width = 0.6
    bottom = np.zeros(len(x_order))
    
    # Create stacked bars
    for i, stack_val in enumerate(stack_order):
        stack_data = summary_df[summary_df[stack_category].eq(stack_val)]

        # Get percentages for each x category
        percentages = []
        for x_val in x_order:
            match = stack_data[stack_data[x_category].eq(x_val)]
            if len(match) == 0:
                pct = 0.0
            elif len(match) == 1:
                pct = float(match['percentage'].iloc[0])
            else:
                pct = float(match['percentage'].sum())

            percentages.append(pct)
        
        # Plot bar segment
        bars = ax.bar(
            x_pos, percentages, width,
            bottom=bottom,
            label=str(stack_val),
            color=colors[i],
            edgecolor='white',
            linewidth=0.5
        )
        
        # Add percentage labels
        if show_percentages:
            for j, (x_val, pct) in enumerate(zip(x_order, percentages)):
                if pct > percentage_threshold:
                    ax.text(
                        x_pos[j],
                        bottom[j] + pct/2,
                        f'{pct:.1f}%',
                        ha='center',
                        va='center',
                        fontsize=font_size - 2,
                        fontweight='bold',
                        color='white'
                    )
        
        bottom += percentages
    
    # Styling
    if xlabel is None:
        xlabel = x_category
    if title is None:
        title = f'{stack_category} Distribution by {x_category} (100% Stacked)'
    
    ax.set_xlabel(xlabel, fontsize=font_size + 2, fontweight='bold', color=line_color)
    ax.set_ylabel(ylabel, fontsize=font_size + 2, fontweight='bold', color=line_color)
    ax.set_title(title, fontsize=font_size + 4, fontweight='bold', pad=20, color=line_color)
    ax.set_xticks(x_pos)
    ax.set_xticklabels(x_order, fontsize=font_size, color=line_color)
    ax.set_ylim(0, 100)
    ax.set_yticks(np.arange(0, 101, 20))
    ax.tick_params(colors=line_color)
    
    # Legend
    ax.legend(
        title=stack_category,
        bbox_to_anchor=(1.05, 1),
        loc='upper left',
        fontsize=font_size - 2,
        title_fontsize=font_size
    )
    
    # Grid
    if grid:
        ax.grid(True, alpha=0.3, axis='y', linestyle='--', color=line_color)
    
    # Spines
    for spine in ax.spines.values():
        spine.set_edgecolor(line_color)
    
    plt.tight_layout()
    
    # Save if requested
    svg_data = None
    if save_path is not None:
        ext = export_format.lower()
        if ext not in ['png', 'svg']:
            print("Invalid export format. Defaulting to 'png'.")
            ext = 'png'
        
        # Generate filename if directory provided
        if os.path.isdir(save_path):
            filename = f"{x_category}_by_{stack_category}_stacked.{ext}"
            full_path = os.path.join(save_path, filename)
        else:
            # Use as full path, adjust extension
            base, _ = os.path.splitext(save_path)
            full_path = f"{base}.{ext}"

        parent = os.path.dirname(os.path.abspath(full_path))
        if parent:
            os.makedirs(parent, exist_ok=True)
        
        if ext == 'svg':
            import io
            buf = io.BytesIO()
            plt.savefig(buf, format='svg', dpi=dpi, bbox_inches='tight',
                       transparent=transparent_background)
            buf.seek(0)
            svg_data = buf.read().decode('utf-8')
            
            with open(full_path, 'w') as f:
                f.write(svg_data)
        else:
            plt.savefig(full_path, dpi=dpi, bbox_inches='tight',
                       transparent=transparent_background)
        
        print(f"✅ Saved to: {full_path}")
    
    if show_plot:
        plt.show()
    
    if return_svg and svg_data is not None:
        return fig, ax, summary_df, svg_data
    else:
        return fig, ax, summary_df


def create_test_track_data_polars(n_tracks=10, track_length=50, plot_size=8):
    """
    Create simulated track data in Polars format for testing.
    
    Parameters
    ----------
    n_tracks : int
        Number of tracks to generate
    track_length : int
        Number of points per track
    plot_size : float
        Size of the plotting area in microns
        
    Returns
    -------
    polars.DataFrame
        Simulated track data
    """
    import polars as pl
    import numpy as np
    
    data = []
    
    for track_id in range(n_tracks):
        # Random starting position
        start_x = np.random.uniform(1, plot_size - 1)
        start_y = np.random.uniform(1, plot_size - 1)
        
        # Random walk parameters
        step_size = 0.1
        drift_x = np.random.uniform(-0.02, 0.02)
        drift_y = np.random.uniform(-0.02, 0.02)
        
        x_pos, y_pos = start_x, start_y
        
        for frame in range(track_length):
            # Random walk with slight drift
            x_pos += np.random.normal(drift_x, step_size)
            y_pos += np.random.normal(drift_y, step_size)
            
            # Keep within bounds
            x_pos = np.clip(x_pos, 0.1, plot_size - 0.1)
            y_pos = np.clip(y_pos, 0.1, plot_size - 0.1)
            
            # Add simple categorical for testing gallery function
            simple_threshold = 'high' if track_id % 2 == 0 else 'low'
            motion_type = ['subdiffusive', 'normal', 'superdiffusive'][track_id % 3]
            
            data.append({
                'unique_id': f'track_{track_id:03d}',
                'frame': frame,
                'x_um': x_pos,
                'y_um': y_pos,
                'particle': track_id,
                'filename': 'test_data',
                'condition': 'simulated',
                'simple_threshold': simple_threshold,
                'motion_type': motion_type
            })
    
    return pl.DataFrame(data)


def plot_xy_heatmap(
    df,
    x_col,
    y_col,
    plot_type='hexbin',
    color_by=None,
    order=None,
    small_multiples=False,
    shared_scale=True,
    gridsize=50,
    figsize=(8, 6),
    cmap=None,
    alpha=0.6,
    s=10,
    title=None,
    xlabel=None,
    ylabel=None,
    scale_data=False,
    scale_method='standard',
    scaler=None,
    scale_group_by=None,
    xlim=None,
    ylim=None,
    save_path=None,
    dpi=150,
    log_scale=True,
    transparent_background=False,
    line_color='black',
    export_format='png',
    return_svg=False,
    contour_levels=None,
    contour_cmap='viridis',
    gates=None,
    gate_order=None,
    gate_colors='black',
    gate_linewidth=2,
    gate_alpha=0.1,
    gate_edge_alpha=1.0,
    gate_text_size=10,
    gate_label_border=True,
    gate_linestyle='--',
    gate_fill_color=None,
    gate_label_position='auto',
    **kwargs
):
    """
    Create flexible x vs y plots with hexbin or scatter options.
    
    Parameters
    ----------
    df : pd.DataFrame or pl.DataFrame
        DataFrame containing the data to plot. Accepts both pandas and polars.
    x_col : str
        Column name for x-axis.
    y_col : str
        Column name for y-axis.
    plot_type : str, optional
        Type of plot. Options are:
        - 'hexbin': Hexagonal binning (good for medium-large datasets)
        - 'scatter': Individual points (good for small datasets or categorical data)
        Default is 'hexbin'.
    color_by : str, optional
        Column name to color/separate data by. If None, pools all data together.
        If specified, colors scatter plots by category or creates small multiples
        when small_multiples=True. Default is None.
    order : list, optional
        Custom order for categories when using color_by parameter. If None, 
        categories will be sorted alphabetically. If provided, should be a list 
        of category values in the desired display order. Only categories present 
        in both the order list and the data will be plotted. Default is None.
    small_multiples : bool, optional
        If True and color_by is provided, creates separate subplots for each category.
        If False, plots all data together (colored by category for scatter).
        Default is False.
    shared_scale : bool, optional
        If True (default), all subplots share the same x/y scale (max of all data).
        If False, each subplot uses different colormaps (for hexbin/hist2d).
        Only applies when small_multiples=True.
    gridsize : int, optional
        Grid size for hexbin plots. Default is 50.
    figsize : tuple, optional
        Figure size (width, height) in inches. Default is (8, 6).
    cmap : str or list of str, optional
        Colormap(s) for plots. 
        - For hexbin plots:
          * Single hexbin: string colormap name (default: 'inferno')
          * Small multiples hexbin: list of colormaps, one per subplot
            (default: ['inferno', 'viridis', 'plasma', 'magma', 'cividis', 'hot'])
        - For scatter plots:
          * Continuous color_by (numeric, >20 unique values): colormap name 
            (default: 'viridis'), displays with colorbar
          * Categorical color_by: converts colormap to discrete colors, or pass 
            list of colors directly
          * Special value 'colorblind': Wong 2011 colorblind-friendly palette
          * No color_by: ignored (uses default color)
        Good colormaps: 'colorblind' (recommended!), 'viridis', 'plasma', 
        'inferno', 'magma', 'cividis', 'coolwarm', 'RdYlBu', 'tab10', 'Set2'.
    alpha : float, optional
        Transparency for scatter plots. Default is 0.6.
    s : float or int, optional
        Marker size for scatter plots. Default is 10.
    title : str, optional
        Overall figure title. Default is None.
    xlabel : str, optional
        X-axis label. Default is x_col.
    ylabel : str, optional
        Y-axis label. Default is y_col.
    scale_data : bool, optional
        If True, applies scaling to x_col and y_col before plotting. Default is False.
    scale_method : str, optional
        Scaling method to use if scale_data=True and scaler is None. Default is 'standard'.
        Options: 'standard', 'minmax', 'robust', 'standard_minmax', etc.
    scaler : sklearn scaler object, optional
        Pre-fitted scaler to use for transforming data. If provided, this scaler
        will be used instead of fitting a new one (CRITICAL for Option A gating).
        The scaler must have a .transform() method and be already fitted.
        Default is None.
    scale_group_by : str or list of str, optional
        Group by column(s) for scaling. Only used if scaler is None. Default is None.
    xlim : tuple, optional
        X-axis limits (xmin, xmax). Default is None (auto).
    ylim : tuple, optional
        Y-axis limits (ymin, ymax). Default is None (auto).
    save_path : str, optional
        Path to save the figure. Can be:
        - A directory path: filename will be auto-generated as 
          "{x_col}_vs_{y_col}_{plot_type}_by_{color_by}_{modifiers}.{ext}"
        - A full file path: will be used as-is (extension adjusted to match export_format)
        Default is None (no save).
    dpi : int, optional
        DPI for saved figure. Default is 150.
    log_scale : bool, optional
        If True, use logarithmic color scaling for hexbin plots to better
        highlight areas of low and high density. Default is True.
    transparent_background : bool, optional
        If True, makes the background transparent. Useful for presentations
        and publications. Default is False.
    line_color : str, optional
        Color for axis lines, ticks, and labels. Default is 'black'.
        Use 'white' for dark backgrounds in presentations.
    export_format : str, optional
        File format to export ('png' or 'svg'). Default is 'png'.
    return_svg : bool, optional
        If True and export_format is 'svg', returns the cleaned SVG data as a string.
        Default is False.
    contour_levels : int or None, optional
        If specified, adds density contour lines on top of scatter/hexbin plots.
        Number indicates how many contour levels to draw. Default is None (no contours).
    contour_cmap : str, optional
        Colormap for contour lines when contour_levels is specified.
        Default is 'viridis'.
    gates : ROIManager or list, optional
        Gates to draw on the plot. Can be:
        - An ROIManager object (e.g., from interactive_roi_gating_with_capture)
        - A list of gate dictionaries with 'coordinates', 'type', and optional 'name'
        Default is None (no gates drawn).
    gate_order : list of str, optional
        Order of gate names for color assignment. If provided, gates will be colored
        in this order. Only gates present in both gate_order and the data will be drawn.
        This ensures consistent color mapping across multiple plots. Default is None
        (uses order from ROIManager or alphabetical by gate name).
    gate_colors : str or list of str, optional
        Color(s) for gate edges/borders. Can be a single color or list of colors.
        Good options for dashed lines: 'black', 'darkgray', 'navy', 'darkgreen',
        'darkred', 'purple'. Default is 'black'.
    gate_linewidth : float, optional
        Line width for gate borders. Default is 2.
    gate_alpha : float, optional
        Transparency for gate fill (0-1). Set to 0 for no fill. Default is 0.1.
        This does NOT affect edge transparency - edges use gate_edge_alpha.
    gate_edge_alpha : float, optional
        Transparency for gate edges/borders (0-1). Default is 1.0 (fully opaque).
        Keep at 1.0 for clear, visible gate boundaries.
    gate_text_size : float, optional
        Font size for gate labels. Default is 10.
    gate_label_border : bool, optional
        Whether to draw a border around gate label text boxes. Default is True.
    gate_linestyle : str, optional
        Line style for gate borders. Options: '-' (solid), '--' (dashed), 
        '-.' (dash-dot), ':' (dotted). Default is '--' (dashed).
    gate_fill_color : str or None, optional
        Fill color for gates. If None, uses same color as edge with alpha.
        Set to 'none' for transparent fill. Good options: 'lightgray', 'lightblue',
        'lightyellow', 'white', or 'none'. Default is None (uses edge color).
    gate_label_position : str, optional
        Label position strategy. Options:
        - 'auto': Smart positioning based on gate location (recommended)
          * Gates closer to left side (0) → label at top-left corner
          * Gates closer to right side (1) → label at top-right corner
          * Always positions at top of gate for visibility
        - 'top-left': Always top-left corner
        - 'top-right': Always top-right corner
        - 'center': Center of gate
        Default is 'auto'.
    **kwargs
        Additional keyword arguments passed to plotting functions.
    
    Returns
    -------
    fig : matplotlib.figure.Figure
        The figure object.
    axes : matplotlib.axes.Axes or np.ndarray of Axes
        The axes object(s).
    svg_data : str (optional)
        If export_format='svg' and return_svg=True, returns cleaned SVG string.
    
    Examples
    --------
    >>> # Simple hexbin plot (all data pooled)
    >>> fig, ax = plot_xy_heatmap(df, 'x_um', 'y_um')
    
    >>> # Scatter plot colored by category (automatic colors)
    >>> fig, ax = plot_xy_heatmap(df, 'speed', 'D', plot_type='scatter', color_by='mol')
    
    >>> # Scatter plot with colorblind-friendly palette (recommended!)
    >>> fig, ax = plot_xy_heatmap(df, 'speed', 'D', plot_type='scatter', 
    ...                            color_by='mol', cmap='colorblind')
    
    >>> # Scatter plot with other custom colormap for categories
    >>> fig, ax = plot_xy_heatmap(df, 'speed', 'D', plot_type='scatter', 
    ...                            color_by='mol', cmap='Set2')
    
    >>> # Scatter plot with continuous colormap (for numeric color_by)
    >>> fig, ax = plot_xy_heatmap(df, 'x_um', 'y_um', plot_type='scatter',
    ...                            color_by='speed', cmap='plasma')
    
    >>> # Small multiples by condition
    >>> fig, axes = plot_xy_heatmap(df, 'x_um', 'y_um', 
    ...                              color_by='condition',
    ...                              small_multiples=True)
    
    >>> # Small multiples with custom order
    >>> fig, axes = plot_xy_heatmap(df, 'x_um', 'y_um', 
    ...                              color_by='condition',
    ...                              order=['control', 'drug1', 'drug2'],
    ...                              small_multiples=True)
    
    >>> # With data scaling
    >>> fig, ax = plot_xy_heatmap(df, 'x_um', 'y_um',
    ...                            scale_data=True,
    ...                            scale_method='standard_minmax')
    
    >>> # With gates (dashed lines, no fill, opaque edges)
    >>> fig, ax = plot_xy_heatmap(df, 'x_um', 'y_um',
    ...                            gates=roi_manager,
    ...                            gate_colors='black',
    ...                            gate_linestyle='--',
    ...                            gate_fill_color='none',
    ...                            gate_linewidth=2,
    ...                            gate_edge_alpha=1.0)  # Opaque edges (default)
    
    >>> # With gates (transparent fill, smart auto label positioning, separate alphas)
    >>> fig, ax = plot_xy_heatmap(df, 'x_um', 'y_um',
    ...                            gates=roi_manager,
    ...                            gate_colors='navy',
    ...                            gate_fill_color='lightblue',
    ...                            gate_alpha=0.15,          # Fill transparency
    ...                            gate_edge_alpha=1.0,      # Opaque edges
    ...                            gate_label_position='auto')  # Smart: left gates→top-left, right gates→top-right
    
    >>> # With gates (no label borders for clean look)
    >>> fig, ax = plot_xy_heatmap(df, 'x_um', 'y_um',
    ...                            gates=roi_manager,
    ...                            gate_colors='black',
    ...                            gate_linestyle='--',
    ...                            gate_fill_color='none',
    ...                            gate_label_border=False)  # No borders around labels
    
    >>> # With gates (consistent color mapping across plots)
    >>> gate_names = ['Low_Speed', 'Medium_Speed', 'High_Speed', 'Very_High']
    >>> gate_colors = ['#0173B2', '#DE8F05', '#029E73', '#CC78BC']
    >>> fig, ax = plot_xy_heatmap(df, 'x_um', 'y_um',
    ...                            gates=roi_manager,
    ...                            gate_order=gate_names,  # Consistent order
    ...                            gate_colors=gate_colors,  # Matches order
    ...                            gate_linestyle='--')
    
    """
    # Detect and convert Polars DataFrames to Pandas for plotting
    # Matplotlib requires pandas/numpy for plotting operations
    try:
        import polars as pl
        is_polars_input = isinstance(df, pl.DataFrame)
    except ImportError:
        is_polars_input = False
    
    if is_polars_input:
        # Convert to pandas for plotting (matplotlib requires pandas/numpy)
        plot_df = df.to_pandas()
    else:
        # Create a copy of the dataframe to avoid modifying the original
        plot_df = df.copy()
    
    # Apply scaling if requested
    if scale_data:
        if scaler is not None:
            # Use the provided scaler (OPTION A - for population-level gating)
            plot_df[[x_col, y_col]] = scaler.transform(plot_df[[x_col, y_col]])
        else:
            # Fit a new scaler on this data (default behavior)
            plot_df = center_scale_data(
                plot_df,
                columns=[x_col, y_col],
                method=scale_method,
                group_by=scale_group_by,
                copy=False
            )
    
    # Set default labels
    if xlabel is None:
        xlabel = x_col
    if ylabel is None:
        ylabel = y_col
    
    def add_density_contours(ax, x, y, levels=5, cmap_name='viridis', alpha_contour=0.6):
        """Add 2D density contours."""
        # Calculate 2D density
        try:
            xy = np.vstack([x, y])
            z = gaussian_kde(xy)(xy)
            
            # Create grid for contours
            x_min, x_max = x.min(), x.max()
            y_min, y_max = y.min(), y.max()
            x_range = x_max - x_min
            y_range = y_max - y_min
            
            # Add padding
            x_min -= x_range * 0.1
            x_max += x_range * 0.1
            y_min -= y_range * 0.1
            y_max += y_range * 0.1
            
            xx, yy = np.mgrid[x_min:x_max:100j, y_min:y_max:100j]
            positions = np.vstack([xx.ravel(), yy.ravel()])
            f = np.reshape(gaussian_kde(xy)(positions).T, xx.shape)
            
            # Draw contours
            contours = ax.contour(xx, yy, f, levels=levels, cmap=cmap_name, 
                                 alpha=alpha_contour, linewidths=1.5)
            ax.clabel(contours, inline=True, fontsize=8)
        except (ValueError, np.linalg.LinAlgError):
            # Skip if KDE fails (too few points or singular matrix)
            pass
    
    # Set default colormaps
    default_hexbin_cmaps = ['inferno', 'viridis', 'plasma', 'magma', 'cividis', 'hot']
    if cmap is None:
        if plot_type == 'hexbin':
            cmap = 'inferno'  # Single plot default
        else:
            cmap = None  # Scatter uses categorical colors
    
    # Set backgrounds
    figure_background = 'none' if transparent_background else 'white'
    axis_background = (0, 0, 0, 0) if transparent_background else 'white'
    
    # Determine if we need subplots based on color_by and small_multiples
    if color_by is not None and small_multiples:
        if order is not None:
            # Use custom order, filtering to only include categories present in data
            unique_vals = set(plot_df[color_by].unique())
            categories = [cat for cat in order if cat in unique_vals]
        else:
            # Default: sort alphabetically
            categories = sorted(plot_df[color_by].unique())
        n_cats = len(categories)
        
        # Always create vertical stack of plots for small multiples
        fig, axes = plt.subplots(
            n_cats, 1,
            figsize=(figsize[0], figsize[1] * n_cats)
        )
        fig.patch.set_facecolor(figure_background)
        if n_cats == 1:
            axes = [axes]
        
        # Calculate shared scale if needed
        if shared_scale:
            x_min, x_max = plot_df[x_col].min(), plot_df[x_col].max()
            y_min, y_max = plot_df[y_col].min(), plot_df[y_col].max()
            # Use max range for both axes
            data_range = max(x_max - x_min, y_max - y_min)
            x_center = (x_max + x_min) / 2
            y_center = (y_max + y_min) / 2
            xlim_shared = (x_center - data_range/2, x_center + data_range/2)
            ylim_shared = (y_center - data_range/2, y_center + data_range/2)
        
        # Handle colormap list for hexbin plots
        cmap_list = cmap
        if plot_type == 'hexbin':
            if isinstance(cmap, str):
                # Single colormap provided - use different ones for each subplot
                cmap_list = default_hexbin_cmaps
            if isinstance(cmap_list, list):
                # Extend list if needed
                if len(cmap_list) < n_cats:
                    cmap_list = (cmap_list * (n_cats // len(cmap_list) + 1))[:n_cats]
            else:
                cmap_list = [cmap_list] * n_cats
        
        # Plot each category
        for idx, cat in enumerate(categories):
            ax = axes[idx]
            ax.set_facecolor(axis_background)
            cat_df = plot_df[plot_df[color_by] == cat]
            
            if plot_type == 'hexbin':
                # Use different colormap for each subplot
                current_cmap = cmap_list[idx] if isinstance(cmap_list, list) else cmap_list
                norm = LogNorm() if log_scale else None
                
                hb = ax.hexbin(
                    cat_df[x_col],
                    cat_df[y_col],
                    gridsize=gridsize,
                    cmap=current_cmap,
                    mincnt=1,
                    norm=norm,
                    **kwargs
                )
                cbar = plt.colorbar(hb, ax=ax, label='Count (log scale)' if log_scale else 'Count')
                cbar.ax.yaxis.set_tick_params(color=line_color)
                cbar.ax.yaxis.label.set_color(line_color)
                plt.setp(plt.getp(cbar.ax.axes, 'yticklabels'), color=line_color)
                
                # Add contours if requested
                if contour_levels is not None:
                    add_density_contours(ax, cat_df[x_col].values, cat_df[y_col].values, 
                                        levels=contour_levels, cmap_name=contour_cmap)
                
            elif plot_type == 'scatter':
                # For scatter in small multiples, use uniform single color per subplot
                # Get color from specified palette or use default
                if cmap == 'colorblind':
                    # Use Wong 2011 colorblind-friendly palette
                    colorblind_colors = [
                        '#0173B2',  # Blue
                        '#DE8F05',  # Orange  
                        '#029E73',  # Green
                        '#CC78BC',  # Purple
                        '#CA9161',  # Brown
                        '#FBAFE4',  # Pink
                        '#949494',  # Gray
                        '#ECE133',  # Yellow
                        '#56B4E9',  # Sky blue
                        '#D55E00'   # Vermillion
                    ]
                    color_palette = colorblind_colors[idx % len(colorblind_colors)]
                elif cmap is not None and isinstance(cmap, (list, tuple)):
                    # Custom list of colors
                    color_palette = cmap[idx % len(cmap)]
                elif cmap is not None and isinstance(cmap, str):
                    # Try to use as colormap
                    try:
                        colormap = plt.cm.get_cmap(cmap)
                        color_palette = colormap(idx / n_cats)
                    except:
                        color_palette = plt.cm.tab10(idx % 10)
                else:
                    # Default to tab10
                    color_palette = plt.cm.tab10(idx % 10)
                
                ax.scatter(cat_df[x_col], cat_df[y_col], s=s, alpha=alpha, 
                          color=color_palette, **kwargs)
                
                # Add contours if requested
                if contour_levels is not None:
                    add_density_contours(ax, cat_df[x_col].values, cat_df[y_col].values,
                                        levels=contour_levels, cmap_name=contour_cmap)
            else:
                raise ValueError(f"plot_type must be 'hexbin' or 'scatter', got '{plot_type}'")
            
            # Set limits
            if shared_scale:
                ax.set_xlim(xlim_shared if xlim is None else xlim)
                ax.set_ylim(ylim_shared if ylim is None else ylim)
            else:
                if xlim is not None:
                    ax.set_xlim(xlim)
                if ylim is not None:
                    ax.set_ylim(ylim)
            
            # Labels and styling
            ax.set_xlabel(xlabel, color=line_color)
            ax.set_ylabel(ylabel, color=line_color)
            ax.set_title(f"{color_by}: {cat}", color=line_color)
            ax.grid(alpha=0.3, color=line_color)
            ax.tick_params(colors=line_color)
            for spine in ax.spines.values():
                spine.set_edgecolor(line_color)
        
        # No unused axes to hide in vertical layout
        
    else:
        # Single plot (pool all data or color by category)
        fig, ax = plt.subplots(figsize=figsize)
        fig.patch.set_facecolor(figure_background)
        ax.set_facecolor(axis_background)
        
        if plot_type == 'hexbin':
            # Density plot - pool all data
            norm = LogNorm() if log_scale else None
            hb = ax.hexbin(
                plot_df[x_col],
                plot_df[y_col],
                gridsize=gridsize,
                cmap=cmap,
                mincnt=1,
                norm=norm,
                **kwargs
            )
            cbar = plt.colorbar(hb, ax=ax, label='Count (log scale)' if log_scale else 'Count')
            cbar.ax.yaxis.set_tick_params(color=line_color)
            cbar.ax.yaxis.label.set_color(line_color)
            plt.setp(plt.getp(cbar.ax.axes, 'yticklabels'), color=line_color)
            
            # Add contours if requested
            if contour_levels is not None:
                add_density_contours(ax, plot_df[x_col].values, plot_df[y_col].values,
                                    levels=contour_levels, cmap_name=contour_cmap)
            
        elif plot_type == 'scatter':
            if color_by is not None and color_by in plot_df.columns:
                # Check if color_by is numeric (continuous) or categorical
                is_numeric_color = np.issubdtype(plot_df[color_by].dtype, np.number)
                n_unique = plot_df[color_by].nunique()
                
                # Treat as continuous if numeric and many unique values
                if is_numeric_color and n_unique > 20:
                    # Continuous coloring with colormap
                    scatter_cmap = cmap if cmap is not None else 'viridis'
                    scatter = ax.scatter(
                        plot_df[x_col],
                        plot_df[y_col],
                        c=plot_df[color_by],
                        s=s,
                        alpha=alpha,
                        cmap=scatter_cmap,
                        **kwargs
                    )
                    cbar = plt.colorbar(scatter, ax=ax, label=color_by)
                    cbar.ax.yaxis.set_tick_params(color=line_color)
                    cbar.ax.yaxis.label.set_color(line_color)
                    plt.setp(plt.getp(cbar.ax.axes, 'yticklabels'), color=line_color)
                else:
                    # Categorical coloring
                    if order is not None:
                        # Use custom order, filtering to only include categories present in data
                        unique_vals = set(plot_df[color_by].unique())
                        unique_colors = [cat for cat in order if cat in unique_vals]
                    else:
                        # Default: sort alphabetically
                        unique_colors = sorted(plot_df[color_by].unique())
                    
                    # Get colors from colormap if provided, otherwise use default palette
                    if cmap is not None:
                        # Handle special palette names
                        if cmap == 'colorblind':
                            # Use Wong 2011 colorblind-friendly palette
                            colors = [
                                '#0173B2',  # Blue
                                '#DE8F05',  # Orange  
                                '#029E73',  # Green
                                '#CC78BC',  # Purple
                                '#CA9161',  # Brown
                                '#FBAFE4',  # Pink
                                '#949494',  # Gray
                                '#ECE133',  # Yellow
                                '#56B4E9',  # Sky blue
                                '#D55E00'   # Vermillion
                            ]
                        elif isinstance(cmap, str):
                            # Try to get it as a matplotlib colormap
                            try:
                                colormap = plt.cm.get_cmap(cmap)
                                colors = [colormap(i / len(unique_colors)) for i in range(len(unique_colors))]
                            except ValueError:
                                # If not a valid colormap, try as seaborn palette
                                try:
                                    import seaborn as sns
                                    colors = sns.color_palette(cmap, n_colors=len(unique_colors))
                                except:
                                    # Fall back to default
                                    colors = plt.rcParams['axes.prop_cycle'].by_key()['color']
                        else:
                            colors = cmap  # Assume it's a list of colors
                    else:
                        # Use matplotlib's default color cycle
                        colors = plt.rcParams['axes.prop_cycle'].by_key()['color']
                    
                    for idx, color_val in enumerate(unique_colors):
                        color_df = plot_df[plot_df[color_by] == color_val]
                        ax.scatter(
                            color_df[x_col],
                            color_df[y_col],
                            s=s,
                            alpha=alpha,
                            color=colors[idx % len(colors)],
                            label=str(color_val),
                            **kwargs
                        )
                    ax.legend(title=color_by, bbox_to_anchor=(1.05, 1), loc='upper left')
                
                # Add contours if requested (on all data)
                if contour_levels is not None:
                    add_density_contours(ax, plot_df[x_col].values, plot_df[y_col].values,
                                        levels=contour_levels, cmap_name=contour_cmap)
            else:
                # Single color scatter (pool all data)
                # For single scatter without color_by, cmap is not used
                ax.scatter(plot_df[x_col], plot_df[y_col], s=s, alpha=alpha, **kwargs)
                
                # Add contours if requested
                if contour_levels is not None:
                    add_density_contours(ax, plot_df[x_col].values, plot_df[y_col].values,
                                        levels=contour_levels, cmap_name=contour_cmap)
        else:
            raise ValueError(f"plot_type must be 'hexbin' or 'scatter', got '{plot_type}'")
        
        # Set limits
        if xlim is not None:
            ax.set_xlim(xlim)
        if ylim is not None:
            ax.set_ylim(ylim)
        
        # Labels and styling
        ax.set_xlabel(xlabel, color=line_color)
        ax.set_ylabel(ylabel, color=line_color)
        ax.grid(alpha=0.3, color=line_color)
        ax.tick_params(colors=line_color)
        for spine in ax.spines.values():
            spine.set_edgecolor(line_color)
        axes = ax
    
    # Draw gates if provided
    if gates is not None:
        # Handle both ROIManager object and list of gate dictionaries
        gate_list = []
        if hasattr(gates, 'rois'):  # ROIManager object
            # If scale_data is False and ROIManager has a scaler, we need to inverse transform
            # the gate coordinates to match the unscaled plot
            if not scale_data and hasattr(gates, 'scaler') and gates.scaler is not None:
                gate_list = gates.get_inverse_transformed_gates()
            else:
                gate_list = gates.rois
        elif isinstance(gates, list):  # List of gate dicts
            gate_list = gates
        else:
            print(f"Warning: gates parameter type not recognized. Expected ROIManager or list.")
        
        # Apply gate_order if provided
        if gate_order is not None:
            # Create mapping of gate names to gates
            gate_dict = {gate.get('name', f"Gate {i}"): gate for i, gate in enumerate(gate_list)}
            # Reorder gates according to gate_order, filtering to only include present gates
            ordered_gates = []
            for gate_name in gate_order:
                if gate_name in gate_dict:
                    ordered_gates.append(gate_dict[gate_name])
            gate_list = ordered_gates
        
        # Draw gates on all axes
        axes_to_draw = [axes] if not isinstance(axes, np.ndarray) else axes.flatten()
        
        from matplotlib.patches import Rectangle
        from matplotlib.patches import Polygon as MplPolygon
        import matplotlib.colors as mcolors
        
        for ax_obj in axes_to_draw:
            # Get axis limits for smart positioning
            x_lim = ax_obj.get_xlim()
            y_lim = ax_obj.get_ylim()
            x_range = x_lim[1] - x_lim[0]
            y_range = y_lim[1] - y_lim[0]
            x_mid = (x_lim[0] + x_lim[1]) / 2
            y_mid = (y_lim[0] + y_lim[1]) / 2
            
            for i, gate in enumerate(gate_list):
                coords = gate.get('coordinates', [])
                gate_name = gate.get('name', f"Gate {i}")
                
                if not coords:
                    continue
                
                # Determine gate edge color
                if isinstance(gate_colors, str):
                    edge_color_base = gate_colors
                elif isinstance(gate_colors, list):
                    edge_color_base = gate_colors[i % len(gate_colors)]
                else:
                    edge_color_base = 'black'
                
                # Convert edge color to RGBA with edge_alpha baked in
                edge_rgba = mcolors.to_rgba(edge_color_base, alpha=gate_edge_alpha)
                
                # Determine gate fill color with fill_alpha baked in
                if gate_fill_color == 'none':
                    fill_rgba = 'none'
                elif gate_fill_color is not None:
                    # Convert fill color to RGBA with gate_alpha baked in
                    fill_rgba = mcolors.to_rgba(gate_fill_color, alpha=gate_alpha)
                else:
                    # Use edge color with gate_alpha for fill
                    fill_rgba = mcolors.to_rgba(edge_color_base, alpha=gate_alpha)
                
                # Draw based on gate type
                if gate.get('type') == 'rect':
                    # Rectangle gate
                    x0, y0 = coords[0]
                    x1, y1 = coords[2]  # Opposite corner
                    width = x1 - x0
                    height = y1 - y0
                    
                    rect = Rectangle(
                        (x0, y0), width, height,
                        linewidth=gate_linewidth,
                        edgecolor=edge_rgba,  # RGBA with edge_alpha baked in
                        facecolor=fill_rgba,  # RGBA with fill_alpha baked in (or 'none')
                        linestyle=gate_linestyle,
                        label=gate_name,
                        clip_on=True,
                    )
                    # Don't set alpha parameter - it would multiply with the baked-in alphas!
                    ax_obj.add_patch(rect)
                    
                    # Smart label positioning
                    gate_center_x = x0 + width / 2
                    gate_center_y = y0 + height / 2
                    
                    if gate_label_position == 'auto':
                        # Smart positioning based on gate proximity to 0 and 1 on axes
                        # Calculate how close gate is to min (0-like) vs max (1-like) on each axis
                        
                        # For X-axis: determine if gate is closer to left (0) or right (1)
                        dist_to_left = gate_center_x - x_lim[0]
                        dist_to_right = x_lim[1] - gate_center_x
                        
                        # For Y-axis: we always want labels at TOP of gates for visibility
                        # but adjust horizontal position based on X proximity
                        
                        if dist_to_left < dist_to_right:
                            # Gate closer to left/0 side → label at top-left
                            label_x = x0 + width * 0.05
                            ha = 'left'
                        else:
                            # Gate closer to right/1 side → label at top-right
                            label_x = x1 - width * 0.05
                            ha = 'right'
                        
                        # Always put labels at top of gate for better visibility
                        label_y = y1 - height * 0.05
                        va = 'top'
                    elif gate_label_position == 'top-left':
                        label_x = x0 + width * 0.05
                        label_y = y1 - height * 0.05
                        ha = 'left'
                        va = 'top'
                    elif gate_label_position == 'top-right':
                        label_x = x1 - width * 0.05
                        label_y = y1 - height * 0.05
                        ha = 'right'
                        va = 'top'
                    elif gate_label_position == 'center':
                        label_x = gate_center_x
                        label_y = gate_center_y
                        ha = 'center'
                        va = 'center'
                    else:
                        # Default to top-left
                        label_x = x0 + width * 0.05
                        label_y = y1 - height * 0.05
                        ha = 'left'
                        va = 'top'
                    
                    # Add label
                    if gate_label_border:
                        label_bbox = dict(boxstyle='round,pad=0.3', facecolor='white', alpha=0.8, 
                                         edgecolor=edge_color_base, linewidth=1)
                    else:
                        label_bbox = dict(boxstyle='round,pad=0.3', facecolor='white', alpha=0.8, 
                                         edgecolor='none', linewidth=0)
                    
                    ax_obj.text(
                        label_x,
                        label_y,
                        gate_name,
                        fontsize=gate_text_size,
                        color=edge_color_base,  # Use base color for text
                        fontweight='bold',
                        ha=ha,
                        va=va,
                        bbox=label_bbox
                    )
                else:
                    # Polygon gate
                    polygon = MplPolygon(
                        coords,
                        linewidth=gate_linewidth,
                        edgecolor=edge_rgba,  # RGBA with edge_alpha baked in
                        facecolor=fill_rgba,  # RGBA with fill_alpha baked in (or 'none')
                        linestyle=gate_linestyle,
                        label=gate_name,
                        clip_on=True,
                    )
                    # Don't set alpha parameter - it would multiply with the baked-in alphas!
                    ax_obj.add_patch(polygon)
                    
                    # Add label for polygon
                    xs, ys = zip(*coords)
                    cx, cy = np.mean(xs), np.mean(ys)
                    
                    # Smart positioning for polygon
                    if gate_label_position == 'auto':
                        # Use same logic as rectangles: proximity to left vs right
                        dist_to_left = cx - x_lim[0]
                        dist_to_right = x_lim[1] - cx
                        
                        if dist_to_left < dist_to_right:
                            # Polygon closer to left/0 side → position label to left
                            ha = 'right'
                            label_offset_x = -0.02 * x_range
                        else:
                            # Polygon closer to right/1 side → position label to right
                            ha = 'left'
                            label_offset_x = 0.02 * x_range
                        
                        # Position slightly above centroid
                        va = 'bottom'
                        label_offset_y = 0.02 * y_range
                        
                        label_x = cx + label_offset_x
                        label_y = cy + label_offset_y
                    else:
                        label_x = cx
                        label_y = cy
                        ha = 'center'
                        va = 'center'
                    
                    if gate_label_border:
                        label_bbox = dict(boxstyle='round,pad=0.3', facecolor='white', alpha=0.8, 
                                         edgecolor=edge_color_base, linewidth=1)
                    else:
                        label_bbox = dict(boxstyle='round,pad=0.3', facecolor='white', alpha=0.8, 
                                         edgecolor='none', linewidth=0)
                    
                    ax_obj.text(
                        label_x,
                        label_y,
                        gate_name,
                        fontsize=gate_text_size,
                        color=edge_color_base,  # Use base color for text
                        fontweight='bold',
                        ha=ha,
                        va=va,
                        bbox=label_bbox
                    )
    
    # Set overall title
    if title is not None:
        fig.suptitle(title, fontsize=14, fontweight='bold', color=line_color)
    
    plt.tight_layout()
    
    # Save if requested
    svg_data = None
    if save_path is not None:
        ext = export_format.lower()
        if ext not in ['png', 'svg']:
            print("Invalid export format specified. Defaulting to 'png'.")
            ext = 'png'
        
        # Check if save_path is a directory or a full file path
        if os.path.isdir(save_path) or (not os.path.exists(save_path) and not save_path.endswith(('.png', '.svg'))):
            # It's a directory - generate filename automatically
            save_dir = save_path
            
            # Build descriptive filename
            filename_parts = [f"{x_col}_vs_{y_col}", plot_type]
            if color_by is not None:
                filename_parts.append(f"by_{color_by}")
            if small_multiples:
                filename_parts.append("multiples")
            if scale_data:
                filename_parts.append(scale_method)
            
            filename = "_".join(filename_parts) + f".{ext}"
            save_path = os.path.join(save_dir, filename)
        else:
            # It's a full file path - use as is but ensure correct extension
            save_dir = os.path.dirname(save_path)
            if not save_path.endswith(f'.{ext}'):
                save_path = save_path.rsplit('.', 1)[0] + f'.{ext}' if '.' in save_path else f'{save_path}.{ext}'
        
        # Create directory if it doesn't exist
        if save_dir and not os.path.exists(save_dir):
            os.makedirs(save_dir)
        
        fig.savefig(
            save_path,
            transparent=transparent_background,
            dpi=dpi,
            format=ext,
            bbox_inches='tight'
        )
        
        # SVG post-processing
        if ext == 'svg':
            try:
                with open(save_path, encoding='utf-8') as f:
                    svg_data = f.read()
                # Remove <clipPath> definitions, metadata, XML declaration, and DOCTYPE
                svg_data = re.sub(
                    r'<clipPath id="[^"]*">.*?</clipPath>', '', svg_data, flags=re.DOTALL
                )
                svg_data = re.sub(r'\s*clip-path="url\([^)]*\)"', '', svg_data)
                svg_data = re.sub(
                    r'<metadata>.*?</metadata>', '', svg_data, flags=re.DOTALL
                )
                svg_data = re.sub(r'<\?xml[^>]*\?>', '', svg_data, flags=re.DOTALL)
                svg_data = re.sub(r'<!DOCTYPE[^>]*>', '', svg_data, flags=re.DOTALL)
                svg_data = svg_data.strip()
                with open(save_path, 'w', encoding='utf-8') as f:
                    f.write(svg_data)
            except Exception as e:
                print(f"Warning: SVG post-processing failed: {e}")
        
        print(f"Figure saved to: {save_path}")
    
    if return_svg and svg_data:
        return fig, axes, svg_data
    else:
        return fig, axes


def interactive_roi_gating(
    df,
    x_col,
    y_col,
    color_by=None,
    scale_data=False,
    scale_method='standard',
    title=None,
    point_size=3,
    opacity=0.6,
    contour_density=True,
    n_contours=10,
    contour_colorscale='Viridis',
    height=700,
    width=900,
    show_legend=True,
    sample_frac=None,
    colorscale='Plotly',
):
    """
    Interactive FACS-style gating plot using Plotly with polygonal ROI selection.
    
    This function creates an interactive scatter plot where you can draw polygonal 
    regions of interest (ROIs) to gate/filter your data, similar to FACS analysis.
    
    Parameters
    ----------
    df : pd.DataFrame
        DataFrame containing the data to plot.
    x_col : str
        Column name for x-axis.
    y_col : str
        Column name for y-axis.
    color_by : str, optional
        Column name to color points by. If None, all points are the same color.
        Can be categorical or continuous. Default is None.
    scale_data : bool, optional
        If True, applies scaling to x_col and y_col before plotting. Default is False.
    scale_method : str, optional
        Scaling method if scale_data=True. Options: 'standard', 'minmax', 
        'robust', 'standard_minmax'. Default is 'standard'.
    title : str, optional
        Plot title. Default is auto-generated from column names.
    point_size : int, optional
        Size of scatter points. Default is 3.
    opacity : float, optional
        Opacity of scatter points (0-1). Default is 0.6.
    contour_density : bool, optional
        If True, adds density contours to the plot. Default is True.
    n_contours : int, optional
        Number of contour levels to show if contour_density=True. Default is 10.
    contour_colorscale : str, optional
        Colorscale for contours. Default is 'Viridis'.
    height : int, optional
        Plot height in pixels. Default is 700.
    width : int, optional
        Plot width in pixels. Default is 900.
    show_legend : bool, optional
        Whether to show the legend. Default is True.
    sample_frac : float, optional
        Fraction of data to plot (for very large datasets). If None, plots all data.
        Example: 0.1 plots 10% of the data. Default is None.
    colorscale : str, optional
        Colorscale for continuous color_by values. Options: 'Plotly', 'Viridis', 
        'Cividis', 'Inferno', 'Magma', 'Plasma', 'Turbo'. Default is 'Plotly'.
    
    Returns
    -------
    fig : plotly.graph_objects.Figure
        The interactive Plotly figure. Use fig.show() to display.
        
    Notes
    -----
    How to use:
    1. Run the function to display the interactive plot
    2. Click the "Draw a closed shape" tool in the toolbar (lasso/polygon icon)
    3. Click points to draw your ROI polygon
    4. Double-click to close the polygon
    5. The selected points are automatically highlighted
    6. Use fig.data to access the ROI coordinates and selected data
    
    To extract ROI data programmatically:
    ```python
    # After drawing ROIs, extract the selection:
    from shapely.geometry import Point, Polygon
    
    # Get ROI coordinates from the drawn shape
    # You can access selectedData from the figure or export via browser
    
    # Or use the companion function: extract_roi_data(df, roi_coords, x_col, y_col)
    ```
    
    Examples
    --------
    >>> # Basic interactive plot
    >>> fig = interactive_roi_gating(df, 'PC1', 'PC2')
    >>> fig.show()
    
    >>> # Colored by molecule type with contours
    >>> fig = interactive_roi_gating(df, 'diffusion_coefficient', 'radius_of_gyration',
    ...                               color_by='mol', contour_density=True)
    >>> fig.show()
    
    >>> # With data scaling
    >>> fig = interactive_roi_gating(df, 'x_um', 'y_um',
    ...                               scale_data=True, scale_method='standard')
    >>> fig.show()
    
    >>> # For very large datasets, sample the data
    >>> fig = interactive_roi_gating(df, 'PC1', 'PC2', sample_frac=0.1)
    >>> fig.show()
    """
    try:
        import plotly.graph_objects as go
        import plotly.express as px
        from plotly.subplots import make_subplots
    except ImportError:
        raise ImportError(
            "Plotly is required for interactive gating. "
            "Install with: pip install plotly"
        )
    
    # Create a copy of the dataframe
    plot_df = df.copy()
    
    # Sample data if requested (for performance with large datasets)
    if sample_frac is not None:
        if 0 < sample_frac < 1:
            plot_df = plot_df.sample(frac=sample_frac, random_state=42)
            print(f"📊 Sampled {len(plot_df):,} points ({sample_frac*100:.1f}% of data)")
    
    # Apply scaling if requested
    if scale_data:
        plot_df = center_scale_data(
            plot_df,
            columns=[x_col, y_col],
            method=scale_method,
            copy=False
        )
        print(f"✓ Data scaled using '{scale_method}' method")
    
    # Set default title
    if title is None:
        title = f"{y_col} vs {x_col}"
        if color_by:
            title += f" (colored by {color_by})"
    
    # Create the figure
    fig = go.Figure()
    
    # Determine if color_by is categorical or continuous
    is_categorical = False
    if color_by is not None:
        if plot_df[color_by].dtype == 'object' or plot_df[color_by].nunique() < 20:
            is_categorical = True
    
    # Add scatter plot
    if color_by is None:
        # Single color scatter
        fig.add_trace(go.Scattergl(
            x=plot_df[x_col],
            y=plot_df[y_col],
            mode='markers',
            marker=dict(
                size=point_size,
                color='#636EFA',  # Plotly default blue
                opacity=opacity,
                line=dict(width=0)
            ),
            name='Data',
            showlegend=show_legend,
            hovertemplate=(
                f'{x_col}: %{{x:.3f}}<br>'
                f'{y_col}: %{{y:.3f}}<br>'
                '<extra></extra>'
            )
        ))
    elif is_categorical:
        # Categorical coloring - one trace per category
        categories = sorted(plot_df[color_by].unique())
        colors = px.colors.qualitative.Plotly
        if len(categories) > len(colors):
            colors = px.colors.qualitative.Dark24
        
        for i, cat in enumerate(categories):
            cat_df = plot_df[plot_df[color_by] == cat]
            fig.add_trace(go.Scattergl(
                x=cat_df[x_col],
                y=cat_df[y_col],
                mode='markers',
                marker=dict(
                    size=point_size,
                    color=colors[i % len(colors)],
                    opacity=opacity,
                    line=dict(width=0)
                ),
                name=str(cat),
                showlegend=show_legend,
                hovertemplate=(
                    f'{color_by}: {cat}<br>'
                    f'{x_col}: %{{x:.3f}}<br>'
                    f'{y_col}: %{{y:.3f}}<br>'
                    '<extra></extra>'
                )
            ))
    else:
        # Continuous coloring
        fig.add_trace(go.Scattergl(
            x=plot_df[x_col],
            y=plot_df[y_col],
            mode='markers',
            marker=dict(
                size=point_size,
                color=plot_df[color_by],
                colorscale=colorscale,
                opacity=opacity,
                showscale=True,
                colorbar=dict(title=color_by),
                line=dict(width=0)
            ),
            name='Data',
            showlegend=False,
            hovertemplate=(
                f'{x_col}: %{{x:.3f}}<br>'
                f'{y_col}: %{{y:.3f}}<br>'
                f'{color_by}: %{{marker.color:.3f}}<br>'
                '<extra></extra>'
            )
        ))
    
    # Add density contours if requested
    if contour_density:
        try:
            from scipy.stats import gaussian_kde
            
            # Calculate 2D density
            x_data = plot_df[x_col].values
            y_data = plot_df[y_col].values
            
            # Remove NaN values
            mask = ~(np.isnan(x_data) | np.isnan(y_data))
            x_data = x_data[mask]
            y_data = y_data[mask]
            
            if len(x_data) > 10:
                # Create grid for contours
                x_min, x_max = x_data.min(), x_data.max()
                y_min, y_max = y_data.min(), y_data.max()
                x_range = x_max - x_min
                y_range = y_max - y_min
                
                # Add padding
                x_min -= x_range * 0.05
                x_max += x_range * 0.05
                y_min -= y_range * 0.05
                y_max += y_range * 0.05
                
                # Create meshgrid
                x_grid = np.linspace(x_min, x_max, 100)
                y_grid = np.linspace(y_min, y_max, 100)
                xx, yy = np.meshgrid(x_grid, y_grid)
                
                # Calculate density
                positions = np.vstack([xx.ravel(), yy.ravel()])
                kernel = gaussian_kde(np.vstack([x_data, y_data]))
                density = np.reshape(kernel(positions).T, xx.shape)
                
                # Add contour
                fig.add_trace(go.Contour(
                    x=x_grid,
                    y=y_grid,
                    z=density,
                    colorscale=contour_colorscale,
                    opacity=0.4,
                    ncontours=n_contours,
                    showscale=False,
                    hoverinfo='skip',
                    line=dict(width=1),
                    name='Density'
                ))
        except Exception as e:
            print(f"Warning: Could not add density contours: {e}")
    
    # Update layout with drawing tools
    fig.update_layout(
        title=dict(
            text=title,
            x=0.5,
            xanchor='center',
            font=dict(size=16)
        ),
        xaxis=dict(
            title=x_col,
            showgrid=True,
            gridcolor='lightgray',
            zeroline=True,
            zerolinecolor='lightgray'
        ),
        yaxis=dict(
            title=y_col,
            showgrid=True,
            gridcolor='lightgray',
            zeroline=True,
            zerolinecolor='lightgray'
        ),
        height=height,
        width=width,
        hovermode='closest',
        dragmode='drawclosedpath',  # Enable polygon drawing by default
        newshape=dict(
            line=dict(color='red', width=3),
            fillcolor='rgba(255, 0, 0, 0.1)',
            opacity=0.5
        ),
        modebar_add=[
            'drawclosedpath',
            'drawopenpath', 
            'drawrect',
            'eraseshape'
        ],
        template='plotly_white',
        legend=dict(
            yanchor="top",
            y=0.99,
            xanchor="right",
            x=0.99
        )
    )
    
    # Add config for better interactivity
    config = {
        'modeBarButtonsToAdd': ['drawclosedpath', 'eraseshape'],
        'displaylogo': False,
        'toImageButtonOptions': {
            'format': 'png',
            'filename': f'{x_col}_vs_{y_col}_gating',
            'height': height,
            'width': width,
            'scale': 2
        }
    }
    
    print("\n" + "="*80)
    print("🎨 INTERACTIVE GATING PLOT")
    print("="*80)
    print(f"📊 Plotting {len(plot_df):,} points")
    print(f"📈 X-axis: {x_col}")
    print(f"📈 Y-axis: {y_col}")
    if color_by:
        print(f"🎨 Colored by: {color_by}")
    print("\n" + "─"*80)
    print("🖱️  HOW TO USE:")
    print("─"*80)
    print("1. Click 'Draw a closed shape' button in the toolbar (top-right)")
    print("2. Click points on the plot to draw your ROI polygon")
    print("3. Double-click to close the polygon")
    print("4. Draw multiple ROIs if needed")
    print("5. Use 'Erase active shape' to remove ROIs")
    print("6. Use extract_roi_data() to get the gated data (see below)")
    print("="*80 + "\n")
    
    # Store the dataframe in the figure for later extraction
    fig._df = plot_df
    fig._x_col = x_col
    fig._y_col = y_col
    
    return fig


def extract_roi_data(fig=None, df=None, roi_coords=None, x_col=None, y_col=None):
    """
    Extract data points within drawn ROI polygons.
    
    Parameters
    ----------
    fig : plotly.graph_objects.Figure, optional
        The figure object returned by interactive_roi_gating(). 
        If provided, uses the stored dataframe and coordinates.
    df : pd.DataFrame, optional
        DataFrame to filter. Required if fig is not provided.
    roi_coords : list of tuples, optional
        List of (x, y) coordinates defining the ROI polygon.
        Required if fig is not provided.
    x_col : str, optional
        Column name for x-axis. Required if fig is not provided.
    y_col : str, optional
        Column name for y-axis. Required if fig is not provided.
    
    Returns
    -------
    pd.DataFrame
        Filtered dataframe containing only points within the ROI(s).
    dict
        Dictionary with ROI statistics and metadata.
    
    Examples
    --------
    >>> # Method 1: After drawing ROIs in the plot, manually provide coordinates
    >>> roi_coords = [(0.5, 0.5), (1.5, 0.5), (1.5, 1.5), (0.5, 1.5)]
    >>> filtered_df, info = extract_roi_data(df=my_df, roi_coords=roi_coords, 
    ...                                       x_col='PC1', y_col='PC2')
    
    >>> # Method 2: With saved ROI coordinates from multiple gates
    >>> gate1 = [(0, 0), (1, 0), (1, 1), (0, 1)]
    >>> gate2 = [(2, 2), (3, 2), (3, 3), (2, 3)]
    >>> df_gate1, _ = extract_roi_data(df=my_df, roi_coords=gate1, x_col='PC1', y_col='PC2')
    >>> df_gate2, _ = extract_roi_data(df=my_df, roi_coords=gate2, x_col='PC1', y_col='PC2')
    """
    try:
        from shapely.geometry import Point, Polygon
    except ImportError:
        raise ImportError(
            "Shapely is required for ROI extraction. "
            "Install with: pip install shapely"
        )
    
    # Get data from figure if provided
    if fig is not None and hasattr(fig, '_df'):
        df = fig._df
        x_col = fig._x_col
        y_col = fig._y_col
    
    # Validate inputs
    if df is None or x_col is None or y_col is None:
        raise ValueError(
            "Must provide either 'fig' from interactive_roi_gating(), "
            "or all of: df, x_col, y_col"
        )
    
    if roi_coords is None:
        print("⚠️  No ROI coordinates provided.")
        print("    After drawing ROIs in the plot, you need to:")
        print("    1. Manually copy the coordinates from the drawn shapes, or")
        print("    2. Use Plotly's relayout_data callback to capture the shape coordinates")
        print("\n    Example:")
        print("    roi_coords = [(x1, y1), (x2, y2), (x3, y3), ...]")
        print("    filtered_df, info = extract_roi_data(df=df, roi_coords=roi_coords,")
        print("                                          x_col='PC1', y_col='PC2')")
        return df.iloc[:0], {}  # Return empty dataframe
    
    # Create polygon from coordinates
    try:
        polygon = Polygon(roi_coords)
    except Exception as e:
        raise ValueError(f"Invalid ROI coordinates: {e}")
    
    # Filter points within polygon
    points = [Point(x, y) for x, y in zip(df[x_col], df[y_col])]
    mask = [polygon.contains(point) for point in points]
    
    filtered_df = df[mask].copy()
    
    # Calculate statistics
    n_total = len(df)
    n_selected = len(filtered_df)
    percent_selected = (n_selected / n_total * 100) if n_total > 0 else 0
    
    info = {
        'n_total': n_total,
        'n_selected': n_selected,
        'percent_selected': percent_selected,
        'roi_coords': roi_coords,
        'x_col': x_col,
        'y_col': y_col
    }
    
    print(f"✅ ROI Filtering Complete")
    print(f"   Total points: {n_total:,}")
    print(f"   Selected points: {n_selected:,} ({percent_selected:.2f}%)")
    
    return filtered_df, info


def save_roi_coordinates(roi_coords, filename, save_path=None):
    """
    Save ROI coordinates to a file for later use.
    
    Parameters
    ----------
    roi_coords : list of tuples
        List of (x, y) coordinates defining the ROI polygon.
    filename : str
        Name for the saved file (without extension).
    save_path : str, optional
        Directory to save the file. If None, saves to current directory.
    
    Examples
    --------
    >>> roi = [(0, 0), (1, 0), (1, 1), (0, 1)]
    >>> save_roi_coordinates(roi, 'my_gate_1', save_path='./gates/')
    """
    import json
    
    if save_path is None:
        save_path = '.'
    
    os.makedirs(save_path, exist_ok=True)
    
    filepath = os.path.join(save_path, f'{filename}.json')
    
    with open(filepath, 'w') as f:
        json.dump(roi_coords, f, indent=2)
    
    print(f"✅ ROI coordinates saved to: {filepath}")


def load_roi_coordinates(filename, save_path=None):
    """
    Load ROI coordinates from a saved file.
    
    Parameters
    ----------
    filename : str
        Name of the saved file (with or without .json extension).
    save_path : str, optional
        Directory where the file is saved. If None, looks in current directory.
    
    Returns
    -------
    list of tuples
        List of (x, y) coordinates defining the ROI polygon.
    
    Examples
    --------
    >>> roi = load_roi_coordinates('my_gate_1', save_path='./gates/')
    >>> filtered_df, _ = extract_roi_data(df=df, roi_coords=roi, x_col='PC1', y_col='PC2')
    """
    import json
    
    if save_path is None:
        save_path = '.'
    
    if not filename.endswith('.json'):
        filename += '.json'
    
    filepath = os.path.join(save_path, filename)
    
    with open(filepath, 'r') as f:
        roi_coords = json.load(f)
    
    print(f"✅ ROI coordinates loaded from: {filepath}")
    print(f"   {len(roi_coords)} vertices")
    
    return roi_coords


def interactive_roi_gating_with_capture(
    df,
    x_col,
    y_col,
    color_by=None,
    scale_data=False,
    scale_method='standard',
    scaler=None,
    roi_manager=None,
    title=None,
    point_size=3,
    opacity=0.6,
    contour_density=True,
    n_contours=10,
    contour_colorscale='Viridis',
    height=700,
    width=900,
    show_legend=True,
    sample_frac=None,
    colorscale='Plotly',
):
    """
    Interactive FACS-style gating plot with automatic ROI coordinate capture.
    
    This enhanced version uses FigureWidget to automatically capture drawn ROI coordinates
    in real-time, making it easy to extract gated data without manual coordinate entry.
    
    Parameters
    ----------
    df : pd.DataFrame or pl.DataFrame
        DataFrame containing the data to plot. Accepts both pandas and polars.
    x_col : str
        Column name for x-axis.
    y_col : str
        Column name for y-axis.
    color_by : str, optional
        Column name to color points by. If None, all points are the same color.
    scale_data : bool, optional
        If True, applies scaling to x_col and y_col before plotting. Default is False.
    scale_method : str, optional
        Scaling method if scale_data=True. Options: 'standard', 'minmax', 
        'robust', 'standard_minmax'. Default is 'standard'.
    scaler : sklearn scaler object, optional
        Pre-fitted scaler to use for transforming data. If provided, this scaler
        will be stored in the ROIManager and used for on-the-fly transformations
        when classifying new data. This allows gates defined in scaled space to
        be applied to unscaled data efficiently.
    roi_manager : ROIManager, optional
        Pre-initialized ROIManager object to use. If provided, this manager will
        be used instead of creating a new one. This allows you to set up gates
        programmatically before displaying the plot, or to reuse the same manager
        across multiple plots. Default is None (creates a new manager).
    title : str, optional
        Plot title. Default is auto-generated.
    point_size : int, optional
        Size of scatter points. Default is 3.
    opacity : float, optional
        Opacity of scatter points (0-1). Default is 0.6.
    contour_density : bool, optional
        If True, adds density contours. Default is True.
    n_contours : int, optional
        Number of contour levels if contour_density=True. Default is 10.
    contour_colorscale : str, optional
        Colorscale for contours. Default is 'Viridis'.
    height : int, optional
        Plot height in pixels. Default is 700.
    width : int, optional
        Plot width in pixels. Default is 900.
    show_legend : bool, optional
        Whether to show legend. Default is True.
    sample_frac : float, optional
        Fraction of data to plot (for large datasets). Default is None.
    colorscale : str, optional
        Colorscale for continuous color_by values. Default is 'Plotly'.
    
    Returns
    -------
    fig : plotly.graph_objects.FigureWidget
        Interactive FigureWidget with ROI capture capabilities.
    roi_manager : ROIManager
        Manager object containing captured ROI coordinates and extraction methods.
        Access via: roi_manager.get_all_rois(), roi_manager.extract_data()
    
    Examples
    --------
    >>> # Example 1: Basic usage with automatic ROI manager creation
    >>> fig, roi_manager = spt.interactive_roi_gating_with_capture(
    ...     df, 'x', 'y', color_by='mol', scale_data=True
    ... )
    >>> display(fig)
    >>> 
    >>> # Example 2: With fitted scaler
    >>> from sklearn.preprocessing import StandardScaler
    >>> from sklearn.pipeline import Pipeline
    >>> scaler = Pipeline([('std', StandardScaler()), ('minmax', MinMaxScaler())])
    >>> scaler.fit(df[['x', 'y']])
    >>> fig, roi_manager = spt.interactive_roi_gating_with_capture(
    ...     df, 'x', 'y', color_by='mol', scale_data=True, scaler=scaler
    ... )
    >>> display(fig)
    >>> 
    >>> # Example 3: Pre-create ROI manager and add gates programmatically
    >>> # Create manager separately
    >>> roi_manager = spt.ROIManager(df, 'x', 'y', scaler=scaler)
    >>> # Add gates before plotting
    >>> roi_manager.add_rectangle_gate(x_min=0.0, x_max=0.3, y_min=0.0, y_max=0.2, name='Gate1')
    >>> roi_manager.add_rectangle_gate(x_min=0.5, x_max=1.0, y_min=0.5, y_max=1.0, name='Gate2')
    >>> # Now create the plot with the pre-configured manager
    >>> fig, roi_manager = spt.interactive_roi_gating_with_capture(
    ...     df, 'x', 'y', color_by='mol', scale_data=True, roi_manager=roi_manager
    ... )
    >>> display(fig)
    >>> 
    >>> # After drawing (or using pre-defined gates), get all ROIs
    >>> rois = roi_manager.get_all_rois()
    >>> print(f"Captured {len(rois)} ROIs")
    >>> 
    >>> # Extract data for a specific ROI
    >>> gated_df = roi_manager.extract_data(roi_index=0)
    >>> 
    >>> # Or extract data for all ROIs
    >>> all_gated_data = roi_manager.extract_all_data()
    >>> 
    >>> # Apply gates to NEW data (scaler transforms automatically!)
    >>> df_classified = roi_manager.classify_data(new_df)
    >>> 
    >>> # Save ROIs
    >>> roi_manager.save_all_rois('my_gates', save_path='./gates/')
    """
    try:
        import plotly.graph_objects as go
        import plotly.express as px
    except ImportError:
        raise ImportError(
            "Plotly is required for interactive gating. "
            "Install with: pip install plotly"
        )
    
    # Detect and convert Polars DataFrames
    try:
        import polars as pl
        is_polars_input = isinstance(df, pl.DataFrame)
    except ImportError:
        is_polars_input = False
    
    if is_polars_input:
        # Convert to pandas for Plotly
        df_pandas = df.to_pandas()
    else:
        df_pandas = df
    
    # Create or use provided ROI manager
    if roi_manager is None:
        # Create ROI manager to store captured coordinates
        # If a scaler is provided, store it for on-the-fly transformations
        # Pass the original df (can be polars or pandas) - ROIManager handles both
        roi_manager = ROIManager(df, x_col, y_col, scaler=scaler)
    else:
        # Use provided ROI manager, but update its dataframe and columns
        roi_manager.df = df
        roi_manager.x_col = x_col
        roi_manager.y_col = y_col
        # Update scaler if one was provided (otherwise keep the manager's scaler)
        if scaler is not None:
            roi_manager.scaler = scaler
    
    # Create a copy and apply scaling if requested
    plot_df = df_pandas.copy()
    
    if sample_frac is not None:
        if 0 < sample_frac < 1:
            plot_df = plot_df.sample(frac=sample_frac, random_state=42)
            print(f"📊 Sampled {len(plot_df):,} points ({sample_frac*100:.1f}% of data)")
    
    if scale_data:
        # If a scaler was provided, use it; otherwise use center_scale_data
        if scaler is not None:
            plot_df[[x_col, y_col]] = scaler.transform(plot_df[[x_col, y_col]])
            print(f"✓ Data scaled using provided scaler")
        else:
            plot_df = center_scale_data(
                plot_df,
                columns=[x_col, y_col],
                method=scale_method,
                copy=False
            )
            print(f"✓ Data scaled using '{scale_method}' method")
    
    roi_manager._plot_df = plot_df  # Store for later extraction
    
    # Set default title
    if title is None:
        title = f"{y_col} vs {x_col}"
        if color_by:
            title += f" (colored by {color_by})"
    
    # Create FigureWidget instead of Figure for callbacks
    fig = go.FigureWidget()
    
    # Determine if color_by is categorical or continuous
    is_categorical = False
    if color_by is not None:
        if plot_df[color_by].dtype == 'object' or plot_df[color_by].nunique() < 20:
            is_categorical = True
    
    # Add scatter plot (same as before)
    if color_by is None:
        fig.add_trace(go.Scattergl(
            x=plot_df[x_col],
            y=plot_df[y_col],
            mode='markers',
            marker=dict(
                size=point_size,
                color='#636EFA',
                opacity=opacity,
                line=dict(width=0)
            ),
            name='Data',
            showlegend=show_legend,
            hovertemplate=(
                f'{x_col}: %{{x:.3f}}<br>'
                f'{y_col}: %{{y:.3f}}<br>'
                '<extra></extra>'
            )
        ))
    elif is_categorical:
        categories = sorted(plot_df[color_by].unique())
        colors = px.colors.qualitative.Plotly
        if len(categories) > len(colors):
            colors = px.colors.qualitative.Dark24
        
        for i, cat in enumerate(categories):
            cat_df = plot_df[plot_df[color_by] == cat]
            fig.add_trace(go.Scattergl(
                x=cat_df[x_col],
                y=cat_df[y_col],
                mode='markers',
                marker=dict(
                    size=point_size,
                    color=colors[i % len(colors)],
                    opacity=opacity,
                    line=dict(width=0)
                ),
                name=str(cat),
                showlegend=show_legend,
                hovertemplate=(
                    f'{color_by}: {cat}<br>'
                    f'{x_col}: %{{x:.3f}}<br>'
                    f'{y_col}: %{{y:.3f}}<br>'
                    '<extra></extra>'
                )
            ))
    else:
        fig.add_trace(go.Scattergl(
            x=plot_df[x_col],
            y=plot_df[y_col],
            mode='markers',
            marker=dict(
                size=point_size,
                color=plot_df[color_by],
                colorscale=colorscale,
                opacity=opacity,
                showscale=True,
                colorbar=dict(title=color_by),
                line=dict(width=0)
            ),
            name='Data',
            showlegend=False,
            hovertemplate=(
                f'{x_col}: %{{x:.3f}}<br>'
                f'{y_col}: %{{y:.3f}}<br>'
                f'{color_by}: %{{marker.color:.3f}}<br>'
                '<extra></extra>'
            )
        ))
    
    # Add density contours if requested
    if contour_density:
        try:
            from scipy.stats import gaussian_kde
            
            x_data = plot_df[x_col].values
            y_data = plot_df[y_col].values
            
            mask = ~(np.isnan(x_data) | np.isnan(y_data))
            x_data = x_data[mask]
            y_data = y_data[mask]
            
            if len(x_data) > 10:
                x_min, x_max = x_data.min(), x_data.max()
                y_min, y_max = y_data.min(), y_data.max()
                x_range = x_max - x_min
                y_range = y_max - y_min
                
                x_min -= x_range * 0.05
                x_max += x_range * 0.05
                y_min -= y_range * 0.05
                y_max += y_range * 0.05
                
                x_grid = np.linspace(x_min, x_max, 100)
                y_grid = np.linspace(y_min, y_max, 100)
                xx, yy = np.meshgrid(x_grid, y_grid)
                
                positions = np.vstack([xx.ravel(), yy.ravel()])
                kernel = gaussian_kde(np.vstack([x_data, y_data]))
                density = np.reshape(kernel(positions).T, xx.shape)
                
                fig.add_trace(go.Contour(
                    x=x_grid,
                    y=y_grid,
                    z=density,
                    colorscale=contour_colorscale,
                    opacity=0.4,
                    ncontours=n_contours,
                    showscale=False,
                    hoverinfo='skip',
                    line=dict(width=1),
                    name='Density'
                ))
        except Exception as e:
            print(f"Warning: Could not add density contours: {e}")
    
    # Update layout with drawing tools
    fig.update_layout(
        title=dict(
            text=title,
            x=0.5,
            xanchor='center',
            font=dict(size=16)
        ),
        xaxis=dict(
            title=x_col,
            showgrid=True,
            gridcolor='lightgray',
            zeroline=True,
            zerolinecolor='lightgray'
        ),
        yaxis=dict(
            title=y_col,
            showgrid=True,
            gridcolor='lightgray',
            zeroline=True,
            zerolinecolor='lightgray'
        ),
        height=height,
        width=width,
        hovermode='closest',
        dragmode='drawclosedpath',
        newshape=dict(
            line=dict(color='red', width=3),
            fillcolor='rgba(255, 0, 0, 0.1)',
            opacity=0.5
        ),
        modebar_add=[
            'drawclosedpath',
            'drawopenpath', 
            'drawrect',
            'eraseshape'
        ],
        template='plotly_white',
        legend=dict(
            yanchor="top",
            y=0.99,
            xanchor="right",
            x=0.99
        )
    )
    
    # Add callback to capture drawn shapes
    def on_relayout(layout, shapes_data):
        """Callback function to capture ROI coordinates when shapes are drawn."""
        if 'shapes' in layout:
            roi_manager.update_rois(layout['shapes'])
    
    fig.layout.on_change(on_relayout, 'shapes')
    
    # Store figure in manager for manual capture
    roi_manager._fig = fig
    
    print("\n" + "="*80)
    print("🎨 INTERACTIVE GATING PLOT WITH AUTO-CAPTURE")
    print("="*80)
    print(f"📊 Plotting {len(plot_df):,} points")
    print(f"📈 X-axis: {x_col}")
    print(f"📈 Y-axis: {y_col}")
    if color_by:
        print(f"🎨 Colored by: {color_by}")
    print("\n" + "─"*80)
    print("🖱️  HOW TO USE:")
    print("─"*80)
    print("1. Click 'Draw rectangle' or 'Draw closed shape' in the toolbar")
    print("2. Draw your ROI on the plot:")
    print("   - Rectangle: Click and drag")
    print("   - Polygon: Click points, double-click to close")
    print("3. After drawing, run: roi_manager.capture_rois()")
    print("4. Then extract data: roi_manager.extract_all_data()")
    print("─"*80)
    print("💡 TIP: If auto-capture doesn't work, use roi_manager.capture_rois()")
    print("="*80 + "\n")
    
    return fig, roi_manager


class ROIManager:
    """
    Manager class for storing and manipulating captured ROI coordinates.
    
    Supports on-the-fly data scaling using a fitted scaler object. This allows
    gates to be defined in scaled space while working with unscaled data, without
    needing to store scaled columns in the dataframe.
    """
    
    def __init__(self, df, x_col, y_col, scaler=None):
        """
        Initialize ROIManager.
        
        Parameters
        ----------
        df : pd.DataFrame or pl.DataFrame
            Input dataframe
        x_col : str
            Column name for x-axis
        y_col : str
            Column name for y-axis
        scaler : sklearn scaler object, optional
            Pre-fitted scaler for transforming data (e.g., fitted StandardScaler
            or custom pipeline). If provided, gates are assumed to be in scaled
            space, and data will be transformed before checking gate membership.
            The scaler must have a .transform() method and be already fitted.
        """
        self.df = df
        self.x_col = x_col
        self.y_col = y_col
        self.scaler = scaler  # Store the fitted scaler
        self._plot_df = df  # Will be updated with scaled/sampled data
        self._fig = None  # Will store the figure for manual capture
        self.rois = []
    
    def capture_rois(self):
        """
        Manually capture ROIs from the figure.
        
        Use this method after drawing your ROIs if automatic capture doesn't work.
        This is the most reliable method to ensure your ROIs are captured.
        
        Returns
        -------
        int
            Number of ROIs captured.
        
        Examples
        --------
        >>> # After drawing ROIs on the plot
        >>> roi_manager.capture_rois()
        ✅ Captured 2 ROI(s)
        """
        if self._fig is None:
            print("❌ No figure available for capture.")
            print("   Make sure you ran the cell that creates the figure first.")
            return 0
        
        # Access shapes from figure layout
        try:
            shapes = self._fig.layout.shapes
            
            # Convert tuple to list if needed
            if shapes is None:
                shapes_list = []
            elif isinstance(shapes, tuple):
                shapes_list = list(shapes)
            else:
                shapes_list = shapes
                
            if len(shapes_list) > 0:
                print(f"🔍 Found {len(shapes_list)} shape(s) in the figure...")
                self.update_rois(shapes_list)
                return len(self.rois)
            else:
                print("⚠️  No shapes found in the figure yet.")
                print("\n📝 INSTRUCTIONS:")
                print("   1. Look at the plot above")
                print("   2. Find the toolbar at the TOP-RIGHT")
                print("   3. Click the 'Draw rectangle' button (looks like a box 📦)")
                print("   4. Click and DRAG on the plot to draw a rectangle")
                print("   5. The rectangle should appear (might be faint)")
                print("   6. Run this cell again to capture it")
                print("\n💡 TIP: The shapes are stored in fig.layout.shapes")
                print(f"   Current shapes: {self._fig.layout.shapes}")
                return 0
                
        except Exception as e:
            print(f"❌ Error accessing shapes: {e}")
            print(f"   Figure type: {type(self._fig)}")
            print(f"   Has layout: {hasattr(self._fig, 'layout')}")
            if hasattr(self._fig, 'layout'):
                print(f"   Layout type: {type(self._fig.layout)}")
                print(f"   Has shapes: {hasattr(self._fig.layout, 'shapes')}")
                if hasattr(self._fig.layout, 'shapes'):
                    print(f"   Shapes: {self._fig.layout.shapes}")
            return 0
        
    def update_rois(self, shapes):
        """Update ROIs from Plotly shapes."""
        self.rois = []
        for shape in shapes:
            if shape['type'] in ['rect', 'path']:
                coords = self._extract_coordinates(shape)
                if coords:
                    self.rois.append({
                        'type': shape['type'],
                        'coordinates': coords,
                        'shape': shape
                    })
        print(f"✅ Captured {len(self.rois)} ROI(s)")
    
    def _extract_coordinates(self, shape):
        """Extract coordinates from a Plotly shape."""
        if shape['type'] == 'rect':
            # Rectangle: convert to polygon coordinates
            x0, y0 = shape['x0'], shape['y0']
            x1, y1 = shape['x1'], shape['y1']
            return [(x0, y0), (x1, y0), (x1, y1), (x0, y1)]
        
        elif shape['type'] == 'path':
            # Parse SVG path string
            path_str = shape['path']
            coords = []
            
            # Simple parser for M (move) and L (line) commands
            import re
            # Extract M and L commands with coordinates
            commands = re.findall(r'[ML]\s*([-\d.]+)[,\s]+([-\d.]+)', path_str)
            for cmd, x, y in commands:
                coords.append((float(x), float(y)))
            
            return coords if coords else None
        
        return None
    
    def get_all_rois(self):
        """Get list of all captured ROI coordinates."""
        return [roi['coordinates'] for roi in self.rois]
    
    def get_roi(self, roi_index):
        """Get specific ROI by index."""
        if 0 <= roi_index < len(self.rois):
            return self.rois[roi_index]['coordinates']
        else:
            raise IndexError(f"ROI index {roi_index} out of range (0-{len(self.rois)-1})")
    
    def extract_data(self, roi_index=0, use_original_df=False):
        """
        Extract data points within a specific ROI.
        
        Parameters
        ----------
        roi_index : int
            Index of the ROI to extract (0-based). Default is 0.
        use_original_df : bool
            If True, applies ROI to original unscaled/unsampled df.
            If False, applies to the plot dataframe. Default is False.
        
        Returns
        -------
        pd.DataFrame or pl.DataFrame
            Filtered dataframe with points inside the ROI. Returns same type as input.
        """
        try:
            from shapely.geometry import Point, Polygon
        except ImportError:
            raise ImportError("Shapely required: pip install shapely")
        
        roi_coords = self.get_roi(roi_index)
        polygon = Polygon(roi_coords)
        
        target_df = self.df if use_original_df else self._plot_df
        
        # Detect if target is Polars DataFrame
        try:
            import polars as pl
            is_polars = isinstance(target_df, pl.DataFrame)
        except ImportError:
            is_polars = False
        
        # Get x and y values
        if is_polars:
            x_vals = target_df[self.x_col].to_list()
            y_vals = target_df[self.y_col].to_list()
        else:
            x_vals = target_df[self.x_col]
            y_vals = target_df[self.y_col]
        
        # Create mask
        points = [Point(x, y) for x, y in zip(x_vals, y_vals)]
        mask = [polygon.contains(point) for point in points]
        
        # Filter based on dataframe type
        if is_polars:
            # Polars requires .filter() method with a Series
            import polars as pl
            mask_series = pl.Series("mask", mask)
            filtered_df = target_df.filter(mask_series)
        else:
            # Pandas supports boolean indexing
            filtered_df = target_df[mask].copy()
        
        print(f"✅ ROI {roi_index}: {len(filtered_df):,} / {len(target_df):,} points "
              f"({len(filtered_df)/len(target_df)*100:.1f}%)")
        
        return filtered_df
    
    def extract_all_data(self, use_original_df=False):
        """
        Extract data for all ROIs.
        
        Returns
        -------
        list of pd.DataFrame
            List of filtered dataframes, one per ROI.
        """
        return [self.extract_data(i, use_original_df) for i in range(len(self.rois))]
    
    def save_all_rois(self, base_filename, save_path=None):
        """Save all ROI coordinates to separate files."""
        if save_path is None:
            save_path = '.'
        
        os.makedirs(save_path, exist_ok=True)
        
        for i, roi_coords in enumerate(self.get_all_rois()):
            filename = f"{base_filename}_roi{i}"
            save_roi_coordinates(roi_coords, filename, save_path)
        
        print(f"✅ Saved {len(self.rois)} ROI(s) to {save_path}")
    
    def show_shapes(self):
        """
        Debug method to show what shapes are currently in the figure.
        
        Use this to troubleshoot if capture_rois() isn't finding your shapes.
        """
        if self._fig is None:
            print("No figure stored.")
            return
        
        print("\n" + "="*80)
        print("DEBUG: Figure Shapes Information")
        print("="*80)
        print(f"Figure type: {type(self._fig)}")
        print(f"Has layout: {hasattr(self._fig, 'layout')}")
        
        if hasattr(self._fig, 'layout'):
            print(f"Has shapes attribute: {hasattr(self._fig.layout, 'shapes')}")
            if hasattr(self._fig.layout, 'shapes'):
                shapes = self._fig.layout.shapes
                print(f"Shapes type: {type(shapes)}")
                print(f"Number of shapes: {len(shapes) if shapes else 0}")
                if shapes:
                    print("\nShapes content:")
                    for i, shape in enumerate(shapes):
                        print(f"\n  Shape {i}:")
                        print(f"    Type: {shape.get('type', 'unknown')}")
                        if shape.get('type') == 'rect':
                            print(f"    Coordinates: ({shape.get('x0')}, {shape.get('y0')}) to ({shape.get('x1')}, {shape.get('y1')})")
                        elif shape.get('type') == 'path':
                            print(f"    Path: {shape.get('path', 'N/A')[:100]}...")
                else:
                    print("  Shapes is None or empty")
        print("="*80 + "\n")
    
    def add_rectangle_gate(self, x_min, x_max, y_min, y_max, name=None):
        """
        Manually add a rectangular gate by specifying its bounds.
        
        This is the SIMPLE, WORKING alternative to interactive drawing.
        
        Parameters
        ----------
        x_min : float
            Minimum x coordinate
        x_max : float
            Maximum x coordinate  
        y_min : float
            Minimum y coordinate
        y_max : float
            Maximum y coordinate
        name : str, optional
            Name for this gate
            
        Examples
        --------
        >>> # Look at your plot and identify the rectangle bounds
        >>> roi_manager.add_rectangle_gate(x_min=0.0, x_max=0.3, y_min=0.0, y_max=0.2)
        >>> # Add another gate
        >>> roi_manager.add_rectangle_gate(x_min=0.5, x_max=1.0, y_min=0.5, y_max=1.0)
        >>> # Extract data
        >>> all_data = roi_manager.extract_all_data()
        """
        coords = [(x_min, y_min), (x_max, y_min), (x_max, y_max), (x_min, y_max)]
        
        gate = {
            'type': 'rect',
            'coordinates': coords,
            'shape': {
                'type': 'rect',
                'x0': x_min,
                'y0': y_min,
                'x1': x_max,
                'y1': y_max
            }
        }
        
        if name:
            gate['name'] = name
            
        self.rois.append(gate)
        
        print(f"✅ Added rectangular gate: x=[{x_min:.3f}, {x_max:.3f}], y=[{y_min:.3f}, {y_max:.3f}]")
        print(f"   Total gates: {len(self.rois)}")
        return len(self.rois) - 1  # Return index of added gate
    
    def clear_gates(self):
        """Remove all gates."""
        n = len(self.rois)
        self.rois = []
        print(f"🗑️  Cleared {n} gate(s)")
    
    def add_polygon_gate(self, coordinates, name=None):
        """
        Manually add a polygonal gate by specifying its vertices.
        
        This allows you to define arbitrary polygon shapes programmatically.
        
        Parameters
        ----------
        coordinates : list of tuples
            List of (x, y) coordinate tuples defining the polygon vertices.
            Example: [(0.1, 0.2), (0.5, 0.2), (0.5, 0.8), (0.1, 0.8)]
        name : str, optional
            Name for this gate
            
        Examples
        --------
        >>> # Triangle gate
        >>> roi_manager.add_polygon_gate([(0, 0), (1, 0), (0.5, 1)], name='triangle')
        >>> 
        >>> # Complex polygon
        >>> coords = [(0.1, 0.2), (0.5, 0.1), (0.8, 0.5), (0.4, 0.9), (0.1, 0.6)]
        >>> roi_manager.add_polygon_gate(coords, name='pentagonal_gate')
        """
        if len(coordinates) < 3:
            raise ValueError("Polygon must have at least 3 vertices")
        
        gate = {
            'type': 'path',
            'coordinates': coordinates,
            'shape': {
                'type': 'path',
                'path': self._coords_to_svg_path(coordinates)
            }
        }
        
        if name:
            gate['name'] = name
            
        self.rois.append(gate)
        
        print(f"✅ Added polygon gate with {len(coordinates)} vertices")
        if name:
            print(f"   Name: {name}")
        print(f"   Total gates: {len(self.rois)}")
        return len(self.rois) - 1  # Return index of added gate
    
    def _coords_to_svg_path(self, coordinates):
        """Convert coordinate list to SVG path string."""
        if not coordinates:
            return ""
        path_parts = [f"M {coordinates[0][0]},{coordinates[0][1]}"]
        for x, y in coordinates[1:]:
            path_parts.append(f"L {x},{y}")
        path_parts.append("Z")  # Close the path
        return " ".join(path_parts)
    
    def add_diagonal_separator(self, point1, point2, xlim, ylim, 
                                buffer=0.01, names=None):
        """
        Add two ROIs separated by a diagonal line.
        
        This creates two polygonal regions: one "below/left" and one "above/right" 
        of the diagonal line you specify. Perfect for separating two populations!
        
        Parameters
        ----------
        point1 : tuple
            (x, y) coordinates of first point on the line
        point2 : tuple
            (x, y) coordinates of second point on the line
        xlim : tuple
            (xmin, xmax) limits of your plot
        ylim : tuple
            (ymin, ymax) limits of your plot
        buffer : float, optional
            Small buffer distance perpendicular to the line (prevents overlap).
            Default is 0.01. Set to 0 for no gap.
        names : tuple of str, optional
            (name_below, name_above) - Names for the two gates.
            Default is ('below_line', 'above_line')
            
        Returns
        -------
        tuple
            (index_below, index_above) - Indices of the two created gates
            
        Examples
        --------
        >>> # Simple diagonal from bottom-left to top-right
        >>> roi_manager.add_diagonal_separator(
        ...     point1=(0.0, 0.0), 
        ...     point2=(1.0, 1.0),
        ...     xlim=(0, 1),
        ...     ylim=(0, 1),
        ...     names=('low_pop', 'high_pop')
        ... )
        >>> 
        >>> # Custom diagonal after looking at your plot
        >>> roi_manager.add_diagonal_separator(
        ...     point1=(0.2, 0.1), 
        ...     point2=(0.8, 0.9),
        ...     xlim=(0, 1),
        ...     ylim=(0, 1),
        ...     buffer=0.02,
        ...     names=('immobile', 'mobile')
        ... )
        >>> 
        >>> # Extract the separated populations
        >>> pop_below = roi_manager.extract_data(roi_index=0)
        >>> pop_above = roi_manager.extract_data(roi_index=1)
        """
        x1, y1 = point1
        x2, y2 = point2
        xmin, xmax = xlim
        ymin, ymax = ylim
        
        if names is None:
            names = ('below_line', 'above_line')
        
        # Calculate perpendicular offset vector for buffer
        dx = x2 - x1
        dy = y2 - y1
        length = np.sqrt(dx**2 + dy**2)
        
        if length == 0:
            raise ValueError("point1 and point2 must be different")
        
        # Perpendicular unit vector (rotated 90 degrees)
        perp_x = -dy / length
        perp_y = dx / length
        
        # Create buffered line points
        # Line offset "below" (negative perpendicular direction)
        line_below = [
            (x1 - buffer * perp_x, y1 - buffer * perp_y),
            (x2 - buffer * perp_x, y2 - buffer * perp_y)
        ]
        
        # Line offset "above" (positive perpendicular direction)
        line_above = [
            (x1 + buffer * perp_x, y1 + buffer * perp_y),
            (x2 + buffer * perp_x, y2 + buffer * perp_y)
        ]
        
        # Create polygon for "below" region
        # Strategy: Find where line intersects the plot boundaries and build polygon
        below_coords = self._create_half_plane_polygon(
            line_below, xlim, ylim, side='below', 
            perp_vector=(-perp_x, -perp_y)
        )
        
        # Create polygon for "above" region
        above_coords = self._create_half_plane_polygon(
            line_above, xlim, ylim, side='above',
            perp_vector=(perp_x, perp_y)
        )
        
        # Add both gates
        idx_below = self.add_polygon_gate(below_coords, name=names[0])
        idx_above = self.add_polygon_gate(above_coords, name=names[1])
        
        print(f"\n📐 Diagonal separator created:")
        print(f"   Line from ({x1:.3f}, {y1:.3f}) to ({x2:.3f}, {y2:.3f})")
        print(f"   Gate '{names[0]}': {len(below_coords)} vertices (index {idx_below})")
        print(f"   Gate '{names[1]}': {len(above_coords)} vertices (index {idx_above})")
        
        return idx_below, idx_above
    
    def _create_half_plane_polygon(self, line_points, xlim, ylim, side, perp_vector):
        """
        Create polygon for half-plane on one side of a line.
        
        Parameters
        ----------
        line_points : list of 2 tuples
            [(x1, y1), (x2, y2)] defining the separator line
        xlim : tuple
            (xmin, xmax)
        ylim : tuple
            (ymin, ymax)
        side : str
            'below' or 'above'
        perp_vector : tuple
            (px, py) perpendicular vector pointing toward the half-plane
        """
        xmin, xmax = xlim
        ymin, ymax = ylim
        (x1, y1), (x2, y2) = line_points
        px, py = perp_vector
        
        # Get corners of plot area
        corners = [
            (xmin, ymin),
            (xmax, ymin),
            (xmax, ymax),
            (xmin, ymax)
        ]
        
        # Determine which side of the line each corner is on
        # Using cross product: (point - line_start) × (line_end - line_start)
        def point_side(px, py):
            """Positive if left of line, negative if right"""
            return (px - x1) * (y2 - y1) - (py - y1) * (x2 - x1)
        
        # Collect corners on the correct side
        polygon_points = []
        
        # Add line endpoints first
        polygon_points.append((x1, y1))
        polygon_points.append((x2, y2))
        
        # Add corners that are on the correct side
        target_sign = 1 if side == 'above' else -1
        
        for corner in corners:
            side_val = point_side(corner[0], corner[1])
            if (side_val * target_sign) >= 0:  # Same sign or zero
                polygon_points.append(corner)
        
        # Sort points to form a proper polygon (counterclockwise)
        # Calculate centroid
        cx = sum(p[0] for p in polygon_points) / len(polygon_points)
        cy = sum(p[1] for p in polygon_points) / len(polygon_points)
        
        # Sort by angle from centroid
        def angle_from_centroid(point):
            return np.arctan2(point[1] - cy, point[0] - cx)
        
        polygon_points.sort(key=angle_from_centroid)
        
        return polygon_points
    
    def _transform_data(self, df_pd, x_col, y_col):
        """
        Apply scaler transformation to x and y columns if scaler is available.
        
        Parameters
        ----------
        df_pd : pd.DataFrame
            Input dataframe (pandas)
        x_col : str
            X column name
        y_col : str
            Y column name
            
        Returns
        -------
        x_transformed, y_transformed : arrays
            Transformed x and y values (or original if no scaler)
        """
        if self.scaler is None:
            return df_pd[x_col].values, df_pd[y_col].values
        
        # Transform using the scaler
        # Scaler expects 2D array
        data_to_transform = df_pd[[x_col, y_col]].values
        transformed = self.scaler.transform(data_to_transform)
        
        return transformed[:, 0], transformed[:, 1]
    
    def get_inverse_transformed_gates(self):
        """
        Get gate coordinates in original (unscaled) space.
        
        This is useful for plotting gates on unscaled data. If no scaler is set,
        returns gates as-is.
        
        Returns
        -------
        list of dict
            List of gate dictionaries with inverse-transformed coordinates.
            
        Examples
        --------
        >>> # Get gates in original space for plotting on unscaled data
        >>> unscaled_gates = roi_manager.get_inverse_transformed_gates()
        >>> fig = spt.plot_xy_heatmap(df, 'x', 'y', gates=unscaled_gates, scale_data=False)
        """
        if self.scaler is None:
            # No transformation needed
            return self.rois
        
        # Check if scaler has inverse_transform method
        if not hasattr(self.scaler, 'inverse_transform'):
            print("Warning: scaler does not have inverse_transform method. Returning gates as-is.")
            return self.rois
        
        # Inverse transform each gate's coordinates
        inverse_gates = []
        for gate in self.rois:
            coords = gate.get('coordinates', [])
            if not coords:
                inverse_gates.append(gate)
                continue
            
            # Convert coordinates to array and inverse transform
            coords_array = np.array(coords)
            coords_inverse = self.scaler.inverse_transform(coords_array)
            
            # Create new gate dict with inverse coordinates
            inverse_gate = gate.copy()
            inverse_gate['coordinates'] = [(x, y) for x, y in coords_inverse]
            
            # Update shape if it's a rectangle
            if gate.get('type') == 'rect' and len(coords_inverse) >= 4:
                inverse_gate['shape'] = {
                    'type': 'rect',
                    'x0': coords_inverse[0, 0],
                    'y0': coords_inverse[0, 1],
                    'x1': coords_inverse[2, 0],
                    'y1': coords_inverse[2, 1]
                }
            
            inverse_gates.append(inverse_gate)
        
        return inverse_gates
    
    def classify_data(self, df, x_col=None, y_col=None, gate_col_name='gate_id', 
                     gate_name_col='gate_name', return_type=None,
                     parent_gate_col=None, parent_gate_ids=None, 
                     not_applicable_label='parent_gate_filtered'):
        """
        Classify each row of a dataframe by which gate it belongs to.
        
        Adds two new columns with gate classifications:
        - gate_col_name: integer gate ID (0, 1, 2, ...) or -1 if not in any gate
        - gate_name_col: gate name (string) or 'ungated' if not in any gate
        
        If a scaler is set, data will be transformed on-the-fly before checking
        gate membership (no need to pre-scale the data).
        
        For sequential/hierarchical gating, use different column names for each round
        (e.g., 'gate_id', 'gate2_id', 'gate3_id') and specify parent gates to 
        distinguish between "ungated" and "not applicable".
        
        Parameters
        ----------
        df : pd.DataFrame or pl.DataFrame
            Input dataframe to classify (in original/unscaled space if using scaler)
        x_col : str, optional
            Column name for x coordinate. If None, uses self.x_col
        y_col : str, optional
            Column name for y coordinate. If None, uses self.y_col
        gate_col_name : str, optional
            Name for the gate ID column. Default is 'gate_id'.
            Use different names for multiple rounds: 'gate2_id', 'gate3_id', etc.
        gate_name_col : str, optional
            Name for the gate name column. Default is 'gate_name'.
            Use different names for multiple rounds: 'gate2_name', 'gate3_name', etc.
        return_type : {'pandas', 'polars', None}, optional
            Return type. If None, returns same type as input.
        parent_gate_col : str, optional
            Column name of parent gate (e.g., 'gate_id') for hierarchical gating.
            If specified, only rows matching parent_gate_ids will be evaluated.
            Others get not_applicable_label. Default is None (no hierarchical gating).
        parent_gate_ids : int, list of int, or None, optional
            Parent gate ID(s) to filter by. Only rows with these parent gate values
            will be evaluated for current gates. Can be single int or list.
            Default is None (evaluate all rows).
        not_applicable_label : str, optional
            Label for rows that don't match parent gate filter. Default is 
            'parent_gate_filtered'. Use this to distinguish from 'ungated'.
            
        Returns
        -------
        pd.DataFrame or pl.DataFrame
            Dataframe with added gate classification columns
            
        Examples
        --------
        >>> # Round 1: Gate on speed vs intersections
        >>> df = roi_manager1.classify_data(df)
        >>> # Adds: gate_id (0, 1, -1), gate_name
        >>> 
        >>> # Round 2: Hierarchical gating ONLY on gate_id==0 population
        >>> df = roi_manager2.classify_data(
        ...     df, 
        ...     gate_col_name='gate2_id',
        ...     gate_name_col='gate2_name',
        ...     parent_gate_col='gate_id',    # ← Check parent gate
        ...     parent_gate_ids=0              # ← Only gate rows where gate_id==0
        ... )
        >>> # Result:
        >>> #   - Rows with gate_id==0: get gate2_id (0, 1, -1) and gate2_name
        >>> #   - Rows with gate_id!=0: get gate2_id=-1, gate2_name='parent_gate_filtered'
        >>> 
        >>> # Round 2 alternative: Gate on multiple parent populations
        >>> df = roi_manager2.classify_data(
        ...     df,
        ...     gate_col_name='gate2_id',
        ...     gate_name_col='gate2_name', 
        ...     parent_gate_col='gate_id',
        ...     parent_gate_ids=[0, 1]        # ← Gate both populations 0 and 1
        ... )
        >>> 
        >>> # Now analyze:
        >>> # These are in parent gate 0 but not in any gate2
        >>> ungated_in_parent = df[df['gate2_name'] == 'ungated']
        >>> # These were filtered out by parent gate
        >>> not_applicable = df[df['gate2_name'] == 'parent_gate_filtered']
        """
        from shapely.geometry import Point, Polygon
        
        # Detect input type
        try:
            import polars as pl
            is_polars = isinstance(df, pl.DataFrame)
        except ImportError:
            is_polars = False
        
        # Convert to pandas for processing
        if is_polars:
            df_pd = df.to_pandas()
        else:
            df_pd = df.copy()
        
        # Use provided columns or fall back to stored ones
        x_col = x_col or self.x_col
        y_col = y_col or self.y_col
        
        if x_col not in df_pd.columns or y_col not in df_pd.columns:
            raise ValueError(f"Columns '{x_col}' and/or '{y_col}' not found in dataframe")
        
        # Handle parent gate filtering for hierarchical gating
        if parent_gate_col is not None:
            if parent_gate_col not in df_pd.columns:
                raise ValueError(f"Parent gate column '{parent_gate_col}' not found in dataframe")
            
            # Normalize parent_gate_ids to list
            if parent_gate_ids is None:
                raise ValueError("parent_gate_ids must be specified when using parent_gate_col")
            if not isinstance(parent_gate_ids, (list, tuple)):
                parent_gate_ids = [parent_gate_ids]
            
            # Create mask for rows that match parent gate
            in_parent_mask = df_pd[parent_gate_col].isin(parent_gate_ids)
            
            # Initialize columns with appropriate defaults
            df_pd[gate_col_name] = -1
            df_pd[gate_name_col] = not_applicable_label  # Default for rows NOT in parent
            
            # Update only rows in parent gate to 'ungated'
            df_pd.loc[in_parent_mask, gate_name_col] = 'ungated'
            
            print(f"🔍 Hierarchical gating:")
            print(f"   Parent gate: {parent_gate_col} in {parent_gate_ids}")
            print(f"   Eligible rows: {in_parent_mask.sum():,} / {len(df_pd):,}")
            print(f"   Filtered rows labeled as: '{not_applicable_label}'")
        else:
            # Standard gating: initialize all as ungated
            df_pd[gate_col_name] = -1
            df_pd[gate_name_col] = 'ungated'
            in_parent_mask = None  # Will gate all rows
        
        # Transform data if scaler is available
        x_transformed, y_transformed = self._transform_data(df_pd, x_col, y_col)
        
        # For each gate, check which points are inside
        for gate_idx, gate in enumerate(self.rois):
            coords = gate.get('coordinates', [])
            if not coords:
                continue
            
            # Create polygon from gate coordinates (gates are in transformed space if scaler exists)
            poly = Polygon(coords)
            
            # Check each point using transformed coordinates
            for idx in range(len(df_pd)):
                # Skip if hierarchical gating and not in parent gate
                if in_parent_mask is not None and not in_parent_mask.iloc[idx]:
                    continue
                
                point = Point(x_transformed[idx], y_transformed[idx])
                if poly.contains(point):
                    df_pd.iloc[idx, df_pd.columns.get_loc(gate_col_name)] = gate_idx
                    df_pd.iloc[idx, df_pd.columns.get_loc(gate_name_col)] = gate.get('name', f'Gate {gate_idx}')
        
        # Convert back to polars if requested or if input was polars
        if return_type == 'polars' or (return_type is None and is_polars):
            try:
                import polars as pl
                return pl.from_pandas(df_pd)
            except ImportError:
                print("Warning: polars not available, returning pandas DataFrame")
                return df_pd
        else:
            return df_pd
    
    def get_gate_summary(self, df, x_col=None, y_col=None):
        """
        Get a summary of how many points fall into each gate.
        
        If a scaler is set, data will be transformed on-the-fly before checking
        gate membership.
        
        Parameters
        ----------
        df : pd.DataFrame or pl.DataFrame
            Dataframe to analyze (in original/unscaled space if using scaler)
        x_col : str, optional
            Column name for x coordinate. If None, uses self.x_col
        y_col : str, optional
            Column name for y coordinate. If None, uses self.y_col
            
        Returns
        -------
        dict
            Summary statistics for each gate
            
        Examples
        --------
        >>> summary = roi_manager.get_gate_summary(df)
        >>> print(summary)
        {
            'total_points': 1000,
            'ungated': 250,
            'gates': [
                {'id': 0, 'name': 'low_speed', 'count': 300, 'percent': 30.0},
                {'id': 1, 'name': 'high_speed', 'count': 450, 'percent': 45.0}
            ]
        }
        """
        from shapely.geometry import Point, Polygon
        
        # Detect input type and convert to pandas if needed
        try:
            import polars as pl
            is_polars = isinstance(df, pl.DataFrame)
            if is_polars:
                df_pd = df.to_pandas()
            else:
                df_pd = df
        except ImportError:
            df_pd = df
        
        # Use provided columns or fall back to stored ones
        x_col = x_col or self.x_col
        y_col = y_col or self.y_col
        
        total_points = len(df_pd)
        gate_counts = []
        
        # Transform data if scaler is available
        x_transformed, y_transformed = self._transform_data(df_pd, x_col, y_col)
        
        # Initialize counters for each gate
        for gate_idx, gate in enumerate(self.rois):
            coords = gate.get('coordinates', [])
            if not coords:
                continue
            
            poly = Polygon(coords)
            count = 0
            
            # Count points in this gate using transformed coordinates
            for idx in range(len(df_pd)):
                point = Point(x_transformed[idx], y_transformed[idx])
                if poly.contains(point):
                    count += 1
            
            gate_counts.append({
                'id': gate_idx,
                'name': gate.get('name', f'Gate {gate_idx}'),
                'count': count,
                'percent': (count / total_points * 100) if total_points > 0 else 0
            })
        
        # Calculate ungated
        gated_total = sum(g['count'] for g in gate_counts)
        ungated_count = total_points - gated_total
        
        return {
            'total_points': total_points,
            'ungated': ungated_count,
            'ungated_percent': (ungated_count / total_points * 100) if total_points > 0 else 0,
            'gates': gate_counts
        }
    
    def __repr__(self):
        return f"ROIManager({len(self.rois)} ROIs captured)"



